package com.ghordrin.bosshealthbar;

import java.time.Duration;
import javax.inject.Singleton;
import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;

@Singleton
class DamageTracker
{
	static final Duration DISPLAY_HOLD = Duration.ofMillis(2500);
	static final Duration PARTY_WINDOW = Duration.ofMillis(2500);
	static final int NO_TICK = -1;

	// Hits on the same or the next tick belong to one attack (multi-hit weapons and specs land a tick apart).
	private static final int MAX_TICK_GAP = 1;

	@Getter(AccessLevel.PACKAGE)
	private long lastHitMillis;

	@Getter(AccessLevel.PACKAGE)
	private int lastHitAmount;

	@Getter(AccessLevel.PACKAGE)
	private int comboDamage;

	@Getter(AccessLevel.PACKAGE)
	private long lastDamageDealtMillis;

	private int comboStartTick = NO_TICK;

	void recordHit(Hitsplat hitsplat, int tick, boolean partyTotal)
	{
		if (hitsplat.getAmount() <= 0 || hitsplat.getHitsplatType() == HitsplatID.HEAL)
		{
			return;
		}

		final long now = System.currentTimeMillis();
		lastHitMillis = now;
		lastHitAmount = hitsplat.getAmount();

		// Party members' hits arrive over the party connection instead, so other players' hitsplats never count.
		if (hitsplat.isMine())
		{
			addToCombo(hitsplat.getAmount(), now, tick, partyTotal);
		}
	}

	void recordPartyHit(int amount, int tick)
	{
		if (amount > 0)
		{
			addToCombo(amount, System.currentTimeMillis(), tick, true);
		}
	}

	// A party total keeps adding while hits keep coming; otherwise each attack gets its own number.
	void addToCombo(int amount, long now, int tick, boolean partyTotal)
	{
		final boolean continues = partyTotal
			? continuesPartyTotal(lastDamageDealtMillis, now)
			: isSameAttack(comboStartTick, tick);
		if (!continues)
		{
			comboDamage = 0;
			comboStartTick = tick;
		}
		comboDamage += amount;
		lastDamageDealtMillis = now;
	}

	static boolean continuesPartyTotal(long lastDamageMillis, long now)
	{
		return lastDamageMillis != 0 && now - lastDamageMillis <= PARTY_WINDOW.toMillis();
	}

	void resetCombo()
	{
		comboDamage = 0;
		lastDamageDealtMillis = 0;
		comboStartTick = NO_TICK;
	}

	void reset()
	{
		lastHitMillis = 0;
		resetCombo();
	}

	// Measured from the first hit, so hits that keep landing a tick apart can't chain into one long total.
	static boolean isSameAttack(int startTick, int tick)
	{
		final int gap = tick - startTick;
		return startTick != NO_TICK && gap >= 0 && gap <= MAX_TICK_GAP;
	}
}

package com.ghordrin.bosshealthbar;

import java.util.Objects;
import javax.inject.Singleton;
import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.api.Actor;
import net.runelite.api.Constants;

// How long the fight with the current opponent has lasted, counted in game ticks from the first hit on it.
@Singleton
class FightTimer
{
	static final int NO_TICK = -1;
	// A boss that swaps to a new NPC between phases can be gone for a moment before the new one shows up.
	static final int SWAP_TICKS = 10;

	static final class Fight
	{
		final String name;
		final int startTick;
		final int endTick;

		Fight(String name, int startTick, int endTick)
		{
			this.name = name;
			this.startTick = startTick;
			this.endTick = endTick;
		}
	}

	private Actor opponent;
	private String name;
	private int endTick = NO_TICK;
	private int clearedTick = NO_TICK;
	private Actor lastHitActor;
	private int lastHitTick = NO_TICK;

	// Identifies the current fight, or NO_TICK before its first hit.
	@Getter(AccessLevel.PACKAGE)
	private int startTick = NO_TICK;
	private int shownTicks = NO_TICK;
	@Getter(AccessLevel.PACKAGE)
	private String text;

	void opponentChanged(Actor next, String nextName, boolean previousDefeated, boolean pairHeld, int tick)
	{
		opponentChanged(nextName, previousDefeated, pairHeld, next == lastHitActor ? lastHitTick : NO_TICK, tick);
		opponent = next;
	}

	// earlierHitTick is the latest hit on the new opponent from before it became the opponent, if any.
	// pairHeld is whether the new opponent's pair is still being kept from before.
	void opponentChanged(String nextName, boolean previousDefeated, boolean pairHeld, int earlierHitTick, int tick)
	{
		if (!keepsCounting(name, previousDefeated || endTick != NO_TICK, clearedTick, nextName, pairHeld, tick))
		{
			clearFight();
		}
		opponent = null;
		name = nextName;
		clearedTick = NO_TICK;
		if (startTick == NO_TICK)
		{
			startTick = recentHitTick(earlierHitTick, tick);
		}
		updateText(tick);
	}

	void opponentReturned(Actor next, Fight fight, int tick)
	{
		opponentReturned(fight, next == lastHitActor ? lastHitTick : NO_TICK, tick);
		opponent = next;
	}

	// An opponent that went out of sight carries on its own fight, whatever was fought in between.
	void opponentReturned(Fight fight, int earlierHitTick, int tick)
	{
		opponent = null;
		name = fight.name;
		startTick = fight.startTick;
		endTick = fight.endTick;
		clearedTick = NO_TICK;
		if (startTick == NO_TICK && endTick == NO_TICK)
		{
			startTick = recentHitTick(earlierHitTick, tick);
		}
		updateText(tick);
	}

	void startOver(int tick)
	{
		startTick = tick;
		endTick = NO_TICK;
		updateText(tick);
	}

	Fight save()
	{
		return new Fight(name, startTick, endTick);
	}

	void opponentDespawned(boolean defeated, int tick)
	{
		if (defeated)
		{
			defeat(tick);
		}
		opponent = null;
		clearedTick = tick;
		updateText(tick);
	}

	// The opponent can be picked after the hit that started the fight, e.g. when the game's boss bar comes up.
	void onCombatHit(Actor actor, int tick)
	{
		lastHitActor = actor;
		lastHitTick = tick;
		if (actor != null && actor == opponent)
		{
			onHit(tick);
		}
	}

	void onHit(int tick)
	{
		if (startTick == NO_TICK && endTick == NO_TICK)
		{
			startTick = tick;
			updateText(tick);
		}
	}

	void onGameTick(Actor current, boolean defeated, int tick)
	{
		final boolean tracked = current != null && current == opponent;
		onGameTick(tracked, tracked && defeated, tick);
	}

	void onGameTick(boolean tracked, boolean dead, int tick)
	{
		if (tracked)
		{
			if (dead)
			{
				defeat(tick);
			}
			else
			{
				// Some opponents drop to 0 and come back for another phase.
				endTick = NO_TICK;
			}
		}
		updateText(tick);
	}

	// The pair was forgotten, so its next member starts a new fight. The time shown stays until then.
	void pairCleared(String pair)
	{
		if (Objects.equals(name, pair))
		{
			name = null;
		}
	}

	void reset()
	{
		clearFight();
		lastHitActor = null;
		lastHitTick = NO_TICK;
	}

	private void clearFight()
	{
		opponent = null;
		name = null;
		startTick = NO_TICK;
		endTick = NO_TICK;
		clearedTick = NO_TICK;
		shownTicks = NO_TICK;
		text = null;
	}

	private void defeat(int tick)
	{
		if (startTick != NO_TICK && endTick == NO_TICK)
		{
			endTick = tick;
		}
	}

	private void updateText(int tick)
	{
		final int ticks = elapsedTicks(startTick, endTick, tick);
		if (ticks != shownTicks)
		{
			shownTicks = ticks;
			text = ticks == NO_TICK ? null : format(ticks);
		}
	}

	static int elapsedTicks(int startTick, int endTick, int tick)
	{
		if (startTick == NO_TICK)
		{
			return NO_TICK;
		}
		return Math.max(0, (endTick != NO_TICK ? endTick : tick) - startTick);
	}

	static int recentHitTick(int hitTick, int tick)
	{
		return hitTick != NO_TICK && tick - hitTick >= 0 && tick - hitTick <= 1 ? hitTick : NO_TICK;
	}

	// A new NPC with the same name carries on the fight, unless the last one was defeated or has been gone too long.
	// The members of a pair can be out of reach for longer between phases, so they don't time out while the pair is kept.
	static boolean keepsCounting(String previousName, boolean previousDefeated, int clearedTick, String nextName,
		boolean pairHeld, int tick)
	{
		return previousName != null
			&& !previousDefeated
			&& Objects.equals(previousName, nextName)
			&& (clearedTick == NO_TICK || tick - clearedTick <= SWAP_TICKS || (pairHeld && PairBosses.isPairKey(nextName)));
	}

	static String format(int ticks)
	{
		final long seconds = (long) ticks * Constants.GAME_TICK_LENGTH / 1000;
		final long hours = seconds / 3600;
		final long minutes = seconds / 60 % 60;
		final long secs = seconds % 60;
		final StringBuilder builder = new StringBuilder(8);
		if (hours > 0)
		{
			builder.append(hours).append(':');
			if (minutes < 10)
			{
				builder.append('0');
			}
		}
		builder.append(minutes).append(':');
		if (secs < 10)
		{
			builder.append('0');
		}
		return builder.append(secs).toString();
	}
}

package com.ghordrin.bosshealthbar;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.WindowConstants;
import javax.swing.border.Border;
import net.runelite.api.Client;
import net.runelite.api.Texture;
import net.runelite.api.TextureProvider;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

class FillTexturePickerDialog extends JDialog
{
	private static final int THUMB_SIZE = 48;
	private static final int COLUMNS = 6;
	private static final int TEXTURES_PER_FRAME = 50;
	private static final Border SELECTED_BORDER = BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE, 2);
	private static final Border HOVER_BORDER = BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR, 2);
	private static final Border IDLE_BORDER = BorderFactory.createEmptyBorder(2, 2, 2, 2);

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final BossHealthBarConfig config;
	private final JPanel resultsPanel = new JPanel(new GridLayout(0, COLUMNS, 4, 4));
	private final JLabel statusLabel = new JLabel();

	private JButton selectedButton;
	private volatile int loadGeneration;

	FillTexturePickerDialog(Client client, ClientThread clientThread, ConfigManager configManager, BossHealthBarConfig config)
	{
		super(SwingUtilities.getWindowAncestor(client.getCanvas()), "Choose fill texture");
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.config = config;

		setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);

		final JPanel content = new JPanel(new BorderLayout(0, 8));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setContentPane(content);

		final JButton none = new JButton("None");
		none.setToolTipText("Go back to the plain fill");
		none.setFocusable(false);
		none.addActionListener(e -> selectNone());

		final JButton refresh = new JButton("Refresh");
		refresh.setToolTipText("Read the game's textures again");
		refresh.setFocusable(false);
		refresh.addActionListener(e -> loadTextures());

		final JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		buttons.setOpaque(false);
		buttons.add(none);
		buttons.add(refresh);

		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statusLabel.setFont(FontManager.getRunescapeSmallFont());

		final JPanel header = new JPanel(new BorderLayout(0, 6));
		header.setOpaque(false);
		header.add(buttons, BorderLayout.NORTH);
		header.add(statusLabel, BorderLayout.SOUTH);

		// Keeps the grid at its own size in the top left, instead of stretching it over the whole view.
		final JPanel resultsHolder = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		resultsHolder.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		resultsPanel.setOpaque(false);
		resultsHolder.add(resultsPanel);
		final JScrollPane scrollPane = new JScrollPane(resultsHolder);
		scrollPane.setBorder(null);
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);

		content.add(header, BorderLayout.NORTH);
		content.add(scrollPane, BorderLayout.CENTER);

		setSize(400, 460);
		setResizable(false);
		setLocationRelativeTo(getOwner());

		loadTextures();
	}

	private void loadTextures()
	{
		statusLabel.setText("Loading...");
		// Decoded in batches over several frames so opening the window doesn't stall the game.
		// A newer load (from Refresh) makes an older one stop.
		final int generation = ++loadGeneration;
		final List<Integer> ids = new ArrayList<>();
		final List<BufferedImage> images = new ArrayList<>();
		final int[] nextId = {0};

		clientThread.invoke(() ->
		{
			if (generation != loadGeneration)
			{
				return true;
			}

			final TextureProvider provider = client.getTextureProvider();
			if (provider != null)
			{
				final Texture[] textures = provider.getTextures();
				final int end = Math.min(textures.length, nextId[0] + TEXTURES_PER_FRAME);
				for (int id = nextId[0]; id < end; id++)
				{
					if (textures[id] == null)
					{
						continue;
					}
					final BufferedImage image = toThumbnail(provider, id);
					if (image != null)
					{
						ids.add(id);
						images.add(image);
					}
				}
				nextId[0] = end;
				if (end < textures.length)
				{
					return false;
				}
			}

			SwingUtilities.invokeLater(() ->
			{
				if (generation == loadGeneration)
				{
					populate(ids, images);
				}
			});
			return true;
		});
	}

	private static BufferedImage toThumbnail(TextureProvider provider, int id)
	{
		final int[] pixels = provider.load(id);
		if (pixels == null || pixels.length == 0)
		{
			return null;
		}
		final int side = (int) Math.round(Math.sqrt(pixels.length));
		if (side * side != pixels.length)
		{
			return null;
		}
		final BufferedImage image = new BufferedImage(side, side, BufferedImage.TYPE_INT_RGB);
		image.setRGB(0, 0, side, side, pixels, 0, side);

		final BufferedImage thumb = new BufferedImage(THUMB_SIZE, THUMB_SIZE, BufferedImage.TYPE_INT_RGB);
		final Graphics2D g = thumb.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(image, 0, 0, THUMB_SIZE, THUMB_SIZE, null);
		g.dispose();
		return thumb;
	}

	private void populate(List<Integer> ids, List<BufferedImage> images)
	{
		resultsPanel.removeAll();
		selectedButton = null;
		final int currentId = config.fillTextureId();

		for (int i = 0; i < ids.size(); i++)
		{
			final int id = ids.get(i);
			final JButton button = buildButton(id, images.get(i));
			if (id == currentId)
			{
				selectedButton = button;
				button.setBorder(SELECTED_BORDER);
			}
			resultsPanel.add(button);
		}

		statusLabel.setText(ids.isEmpty() ? "No textures loaded yet, try Refresh" : ids.size() + " textures");
		resultsPanel.revalidate();
		resultsPanel.repaint();
	}

	private JButton buildButton(int textureId, BufferedImage image)
	{
		final JButton button = new JButton(new ImageIcon(image));
		button.setToolTipText("Texture " + textureId);
		button.setPreferredSize(new Dimension(THUMB_SIZE + 4, THUMB_SIZE + 4));
		button.setBorder(IDLE_BORDER);
		button.setContentAreaFilled(false);
		button.setFocusable(false);
		button.addActionListener(e -> select(button, textureId));
		button.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (button != selectedButton)
				{
					button.setBorder(HOVER_BORDER);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (button != selectedButton)
				{
					button.setBorder(IDLE_BORDER);
				}
			}
		});
		return button;
	}

	private void select(JButton button, int textureId)
	{
		if (selectedButton != null)
		{
			selectedButton.setBorder(IDLE_BORDER);
		}
		selectedButton = button;
		button.setBorder(SELECTED_BORDER);
		configManager.setConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.FILL_TEXTURE_ID_KEY, textureId);
	}

	private void selectNone()
	{
		if (selectedButton != null)
		{
			selectedButton.setBorder(IDLE_BORDER);
			selectedButton = null;
		}
		configManager.unsetConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.FILL_TEXTURE_ID_KEY);
	}
}

package com.ghordrin.bosshealthbar;

import java.awt.Color;

// Themes that aren't in the Theme dropdown. Oldschool is turned on with its own checkbox.
enum FlatTheme implements BarTheme
{
	OLDSCHOOL(ThemeColors.builder()
		.fillHigh(new Color(0x00C000))
		.fillLow(new Color(0x00C000))
		.track(new Color(0xB40000))
		.trail(new Color(0xD07A20))
		.frame(new Color(0x0A0A0A))
		.text(new Color(0xF4F4F4))
		.levelText(new Color(0xF2E08A))
		.hitpointsText(new Color(0xDCDCDC))
		.defeatedText(new Color(0xF07070))
		.build());

	private final ThemeColors colors;

	FlatTheme(ThemeColors colors)
	{
		this.colors = colors;
	}

	@Override
	public ThemeColors getColors()
	{
		return colors;
	}

	@Override
