	{
		return true;
	}
}

package com.ghordrin.bosshealthbar;

import com.google.common.collect.ImmutableList;
import java.awt.Font;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.config.FontType;

final class FontDefaultMigration
{
	private static final int OLD_DEFAULT_SIZE = 17;
	static final List<String> SMALL_TEXT_FONT_KEYS = ImmutableList.of(
		BossHealthBarConfig.COMBAT_LEVEL_FONT_KEY,
		BossHealthBarConfig.HITPOINTS_FONT_KEY,
		BossHealthBarConfig.KILL_COUNT_FONT_KEY,
		BossHealthBarConfig.PARTY_DEFENCE_FONT_KEY,
		BossHealthBarConfig.SPECIAL_ATTACK_COUNTS_FONT_KEY,
		BossHealthBarConfig.WEAKNESS_FONT_KEY,
		BossHealthBarConfig.DRAIN_CAP_FONT_KEY);

	private FontDefaultMigration()
	{
	}

	// The default before the RuneScape font. RuneLite saves defaults before the plugin starts, so
	// everyone who never changed the font has this saved.
	static boolean isOldDefault(FontType font)
	{
		return font != null
			&& Font.SERIF.equals(font.getFamily())
			&& font.getSize() == OLD_DEFAULT_SIZE
			&& !font.isBold()
			&& !font.isItalic();
	}

	// The RuneScape fonts used to ignore the saved size, and the font picker keeps the old size when the
	// family changes, so a saved size other than the native one was never seen. Returns null to keep the font.
	static FontType withNativePixelSize(FontType font)
	{
		if (font == null || font.getFamily() == null)
		{
			return null;
		}
		for (FontType pixel : new FontType[]{FontType.REGULAR, FontType.SMALL})
		{
			if (pixel.getFamily().equals(font.getFamily()))
			{
				return font.getSize() == pixel.getSize() ? null : font.withSize(pixel.getSize());
			}
		}
		return null;
	}

	// The damage number always used the name's font, whatever it was. The smaller text only needs a change
	// for other fonts, since the RuneScape defaults already match.
	static Map<String, FontType> itemFontWrites(FontType name)
	{
		final Map<String, FontType> writes = new LinkedHashMap<>();
		if (name == null)
		{
			return writes;
		}
		writes.put(BossHealthBarConfig.DAMAGE_NUMBER_FONT_KEY, name);
		final FontType small = smallTextFont(name);
		if (small != null)
		{
			for (String key : SMALL_TEXT_FONT_KEYS)
			{
				writes.put(key, small);
			}
		}
		return writes;
	}

	// Before each item had its own font, other fonts drew the smaller text in the name's family at a smaller
	// size, italic like the name but never bold. Returns null for the RuneScape fonts, whose defaults already match.
	static FontType smallTextFont(FontType name)
	{
		if (name == null || name.getFamily() == null || BarTextPainter.isRunescapeFont(name.getFamily()))
		{
			return null;
		}
		return new FontType()
			.withFamily(name.getFamily())
			.withSize(BarTextPainter.smallTextSize(name.getSize()))
			.withItalic(name.isItalic());
	}
}

package com.ghordrin.bosshealthbar;

import java.util.Arrays;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

@Singleton
class GameBossBar
{
	// Set to 1 on NPCs whose game boss bar only shows a percentage. No gameval constant exists for it.
	private static final int PARAM_HP_PERCENTAGE_ONLY = 2289;

	// The layer holding only the bar, since the game mounts other HUDs, like pillar health bars, in the same interface.
	private static final int GAME_BAR = InterfaceID.HpbarHud.HPDODGER;

	private static final int[] PHASE_MARKER_VARBITS = {
		VarbitID.HPBAR_HUD_LOWER_THRESHOLD,
		VarbitID.HPBAR_HUD_UPPER_THRESHOLD,
		VarbitID.HPBAR_HUD_HP_1,
		VarbitID.HPBAR_HUD_HP_2,
	};

	private final Client client;

	private boolean hidden;
	private NPC npc;
	private int searchedId = -1;
	private int replacedId = -1;
	private int healthSeenId = -1;

	private int percentOnlyNpcId = -1;
	private boolean percentOnly;

	private final int[] phaseMarkerValues = new int[PHASE_MARKER_VARBITS.length];
	private int phaseMarkerMaxHealth;
	private float[] phaseMarkers = BarState.NO_PHASE_MARKERS;

	@Inject
	GameBossBar(Client client)
	{
		this.client = client;
	}

	int trackedNpcId()
	{
		if (client.getVarbitValue(VarbitID.HPBAR_HUD_BOSS_DISABLED) != 0)
		{
			return -1;
		}
		return client.getVarpValue(VarPlayerID.HPBAR_HUD_NPC);
	}

	boolean isTracking(Actor actor)
	{
		if (!(actor instanceof NPC))
		{
			return false;
		}
		final int trackedId = trackedNpcId();
		return trackedId != -1 && NpcUtil.baseId((NPC) actor) == trackedId;
	}

	NPC findNpc(Actor opponent)
	{
		final int trackedId = trackedNpcId();
		if (trackedId == -1)
		{
			npc = null;
			searchedId = -1;
			return null;
		}

		if (isTracking(opponent))
		{
			npc = (NPC) opponent;
			return npc;
		}

		final Player player = client.getLocalPlayer();
		final Actor target = player != null ? player.getInteracting() : null;
		if (isTracking(target))
		{
			npc = (NPC) target;
			return npc;
		}

		if (npc != null && NpcUtil.baseId(npc) == trackedId)
		{
			return npc;
		}

		if (npc == null && trackedId == searchedId)
		{
			return null;
		}

		npc = null;
		searchedId = trackedId;
		for (NPC candidate : client.getTopLevelWorldView().npcs())
		{
			if (NpcUtil.baseId(candidate) == trackedId)
			{
				npc = candidate;
				break;
			}
		}
		return npc;
	}

	void onNpcSpawned()
	{
		searchedId = -1;
	}

	void onNpcDespawned(NPC despawned)
	{
		if (despawned == npc)
		{
			npc = null;
		}
	}

	boolean update(Actor opponent, boolean replaceEnabled, boolean opponentGetsBar)
	{
		final Widget bar = client.getWidget(GAME_BAR);
		if (bar == null)
		{
			hidden = false;
			return false;
		}

		boolean replace = false;
		if (replaceEnabled)
		{
			// An opponent without our bar, such as one on the Never show for list, keeps the game's bar.
			if (isTracking(opponent))
			{
				replace = opponentGetsBar;
				replacedId = trackedNpcId();
			}
			else
			{
				// After the boss despawns, the game's bar can stay up on it while the defeat animation
				// plays, so keep it hidden until it tracks a different NPC.
				replace = replacedId != -1 && trackedNpcId() == replacedId;
			}
		}

		if (replace)
		{
			if (!bar.isSelfHidden())
			{
				bar.setHidden(true);
				hidden = true;
			}
		}
		else
		{
			replacedId = -1;
			restore();
		}
		return replace;
	}

	void restore()
	{
		if (!hidden || trackedNpcId() == -1)
		{
			return;
		}
		release();
	}

	private void release()
	{
		if (hidden)
		{
			final Widget bar = client.getWidget(GAME_BAR);
			if (bar != null)
			{
				bar.setHidden(false);
			}
		}
		hidden = false;
	}

	void reset()
	{
		// Nothing else unhides the bar, so do it here even when the game no longer tracks an NPC.
		release();
		npc = null;
		searchedId = -1;
		replacedId = -1;
		healthSeenId = -1;
	}

	int maxHealth()
	{
		return client.getVarbitValue(VarbitID.HPBAR_HUD_BASEHP);
	}

	int health()
	{
		return client.getVarbitValue(VarbitID.HPBAR_HUD_HP);
	}

	// Right after the bar moves to another NPC it can read 0 before that NPC's health arrives, so a 0 only
	// counts once the bar has shown health above 0 for the NPC it tracks.
	boolean hasHealth()
	{
		final int trackedId = trackedNpcId();
		if (health() > 0)
		{
			healthSeenId = trackedId;
			return true;
		}
		return trackedId != -1 && trackedId == healthSeenId;
	}

	boolean isPercentOnly()
	{
		final int npcId = client.getVarpValue(VarPlayerID.HPBAR_HUD_NPC);
		if (npcId != percentOnlyNpcId)
		{
			final NPCComposition composition = npcId != -1 ? client.getNpcDefinition(npcId) : null;
			percentOnly = composition != null && composition.getIntValue(PARAM_HP_PERCENTAGE_ONLY) == 1;
			percentOnlyNpcId = npcId;
		}
		return percentOnly;
	}

	float[] phaseMarkers(int maxHealth)
	{
		boolean changed = maxHealth != phaseMarkerMaxHealth;
		for (int i = 0; i < PHASE_MARKER_VARBITS.length; i++)
		{
			final int value = client.getVarbitValue(PHASE_MARKER_VARBITS[i]);
			if (value != phaseMarkerValues[i])
			{
				phaseMarkerValues[i] = value;
				changed = true;
			}
		}
		if (!changed)
		{
			return phaseMarkers;
		}
		phaseMarkerMaxHealth = maxHealth;

		float[] markers = null;
		int count = 0;
		for (int value : phaseMarkerValues)
		{
			if (value > 0 && value <= maxHealth + 1)
			{
				if (markers == null)
				{
					markers = new float[PHASE_MARKER_VARBITS.length];
				}
				markers[count++] = markerFraction(value, maxHealth);
			}
		}
		phaseMarkers = markers == null ? BarState.NO_PHASE_MARKERS : Arrays.copyOf(markers, count);
		return phaseMarkers;
	}

	// Same placement as the game's own bar: a marker for value v sits at (v - 1) / max health.
	static float markerFraction(int value, int maxHealth)
	{
		return BarAnimation.clamp01((value - 1) / (float) maxHealth);
	}
}

package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.ColorUtil.brighten;
import static com.ghordrin.bosshealthbar.ColorUtil.withAlpha;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.LinearGradientPaint;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Path2D;
import java.util.Random;
import javax.inject.Inject;
import javax.inject.Named;

class GoldBar
{
	static final Color GOLD = new Color(0xE0B84A);
	private static final int CHANCE = 250;
	private static final int DEVELOPER_CHANCE = 2;

	// Plays once, just after the intro animation has filled the bar.
	private static final long SHINE_DELAY_MILLIS = 850;
	private static final long SHINE_MILLIS = 900;
	private static final Color SHINE = new Color(255, 248, 225);

	private static final long SPARKLE_PERIOD_MILLIS = 1800;
	private static final float SPARKLE_VISIBLE = 0.35f;
	private static final Color SPARKLE = new Color(255, 246, 214);
	// x and y in crest radii from its centre, then a phase offset.
	private static final float[][] SPARKLES = {
		{-0.95f, -0.75f, 0f},
		{0.9f, -0.95f, 0.33f},
		{-0.15f, 1.05f, 0.66f},
	};

	private final Random random = new Random();
	private final int chance;

	private ThemeColors source;
	private ThemeColors gold;

	@Inject
	GoldBar(@Named("developerMode") boolean developerMode)
	{
		chance = developerMode ? DEVELOPER_CHANCE : CHANCE;
	}

	boolean roll()
	{
		return random.nextInt(chance) == 0;
	}

	ThemeColors colors(ThemeColors colors)
	{
		if (colors != source)
		{
			gold = gilded(colors);
			source = colors;
		}
		return gold;
	}

	static ThemeColors gilded(ThemeColors colors)
	{
		return colors.toBuilder()
			.frame(GOLD)
			.levelText(brighten(GOLD, 0.35f))
			.defeatedText(brighten(GOLD, 0.45f))
			.build();
	}

	void drawShine(Graphics2D graphics, int x, int y, int width, int height, long barAgeMillis)
	{
		final long time = barAgeMillis - SHINE_DELAY_MILLIS;
		if (time < 0 || time >= SHINE_MILLIS || width <= 0)
		{
			return;
		}

		final float progress = time / (float) SHINE_MILLIS;
		final float band = Math.max(24f, height * 3f);
		final float centre = x - band + (width + band * 2) * progress;
		graphics.setPaint(new LinearGradientPaint(
			centre - band / 2, y, centre + band / 2, y + height,
			new float[]{0f, 0.5f, 1f},
			new Color[]{withAlpha(SHINE, 0), withAlpha(SHINE, 150), withAlpha(SHINE, 0)}));
		graphics.fillRect(x, y, width, height);
	}

	void drawSparkles(Graphics2D graphics, float centreX, float centreY, float radius, boolean mirrored, long nowMillis)
	{
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		final float cycle = (nowMillis % SPARKLE_PERIOD_MILLIS) / (float) SPARKLE_PERIOD_MILLIS;
		for (float[] sparkle : SPARKLES)
		{
			final float phase = (cycle + sparkle[2] + (mirrored ? 0.5f : 0f)) % 1f;
			if (phase >= SPARKLE_VISIBLE)
			{
				continue;
			}

			final float strength = (float) Math.sin(Math.PI * phase / SPARKLE_VISIBLE);
			final float x = centreX + (mirrored ? -sparkle[0] : sparkle[0]) * radius;
			final float y = centreY + sparkle[1] * radius;
			graphics.setColor(withAlpha(SPARKLE, Math.round(230 * strength)));
			graphics.fill(star(x, y, Math.max(1.5f, radius * 0.4f * strength)));
		}
	}

	private static Shape star(float x, float y, float size)
	{
		final float waist = size * 0.22f;
		final Path2D.Float path = new Path2D.Float();
		path.moveTo(x, y - size);
		path.lineTo(x + waist, y - waist);
		path.lineTo(x + size, y);
		path.lineTo(x + waist, y + waist);
		path.lineTo(x, y + size);
		path.lineTo(x - waist, y + waist);
		path.lineTo(x - size, y);
		path.lineTo(x - waist, y - waist);
		path.closePath();
		return path;
	}
}

