	{
		return name != null ? BOSSES.get(Text.removeTags(name).toLowerCase(Locale.ROOT)) : null;
	}

	private static final class Builder
	{
		private final ImmutableMap.Builder<String, Boss> bosses = ImmutableMap.builder();
		private final Map<Integer, ThemeColors> palettes = new HashMap<>();

		Builder sprite(int spriteId, int color, String... names)
		{
			return add(new Icon(false, spriteId), palette(color), names);
		}

		Builder sprite(int spriteId, HealthBarTheme theme, String... names)
		{
			return add(new Icon(false, spriteId), theme.getColors(), names);
		}

		Builder item(int itemId, int color, String... names)
		{
			return add(new Icon(true, itemId), palette(color), names);
		}

		Builder item(int itemId, HealthBarTheme theme, String... names)
		{
			return add(new Icon(true, itemId), theme.getColors(), names);
		}

		Builder noIcon(int color, String... names)
		{
			return add(null, palette(color), names);
		}

		private ThemeColors palette(int color)
		{
			return palettes.computeIfAbsent(color, rgb -> ThemeColors.fromBase(new Color(rgb)));
		}

		private Builder add(Icon icon, ThemeColors colors, String... names)
		{
			final Boss boss = new Boss(icon, colors);
			for (String name : names)
			{
				bosses.put(name.toLowerCase(Locale.ROOT), boss);
			}
			return this;
		}

		Map<String, Boss> build()
		{
			return bosses.build();
		}
	}
}

package com.ghordrin.bosshealthbar;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Iterator;

// The last health read for the few most recent opponents of the current fight, for a moment where an
// opponent has no reading yet, such as an NPC that comes back after leaving or a boss bar that moved over.
final class LastHealth
{
	static final int CAPACITY = 8;

	private static final class Entry
	{
		final int index;
		final String name;
		final int fight;
		final BarState state;

		Entry(int index, String name, int fight, BarState state)
		{
			this.index = index;
			this.name = name;
			this.fight = fight;
			this.state = state;
		}
	}

	private final Deque<Entry> entries = new ArrayDeque<>();

	// fight identifies the fight the reading belongs to, such as the tick it started. Below 0 means no fight yet.
	void remember(int index, String name, int fight, BarState state)
	{
		if (name == null || fight < 0 || state == null || state.scale <= 0)
		{
			return;
		}
		final Entry newest = entries.peekFirst();
		if (newest != null && newest.index == index && newest.fight == fight && newest.state == state
			&& newest.name.equals(name))
		{
			return;
		}
		removeMatching(index, name);
		entries.addFirst(new Entry(index, name, fight, state));
		while (entries.size() > CAPACITY)
		{
			entries.removeLast();
		}
	}

	// Same NPC first. An NPC that left and came back gets a new index, so a single entry with its name counts too.
	BarState find(int index, String name, int fight)
	{
		if (name == null || fight < 0)
		{
			return null;
		}
		Entry byName = null;
		int sameName = 0;
		for (Entry entry : entries)
		{
			if (entry.fight != fight || !entry.name.equals(name))
			{
				continue;
			}
			if (entry.index == index)
			{
				return entry.state;
			}
			byName = entry;
			sameName++;
		}
		return sameName == 1 ? byName.state : null;
	}

	void clear()
	{
		entries.clear();
	}

	private void removeMatching(int index, String name)
	{
		for (Iterator<Entry> it = entries.iterator(); it.hasNext(); )
		{
			final Entry entry = it.next();
			if (entry.index == index && entry.name.equals(name))
			{
				it.remove();
			}
		}
	}
}

package com.ghordrin.bosshealthbar;

import com.google.common.annotations.VisibleForTesting;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.IdentityHashMap;
import java.util.Map;
import net.runelite.client.util.ImageUtil;

// Tells Better Party Defence's Magic defence box apart by its image. With its theme icon option on it draws its
// own 16x16 copy of the Magic icon (or of a resource pack's override), so those copies are rebuilt the same way
// here and compared pixel by pixel.
class MagicIconMatcher
{
	@VisibleForTesting
	static final int THEMED_ICON_SIZE = 16;
	private static final int MAX_VERDICTS = 8;

	private BufferedImage classicSource;
	private BufferedImage classic;
	private BufferedImage overrideSource;
	private BufferedImage override;
	private final Map<BufferedImage, Boolean> verdicts = new IdentityHashMap<>();

	boolean isMagic(BufferedImage image, BufferedImage skillImage, BufferedImage overrideImage)
	{
		if (image == null)
		{
			return false;
		}
		if (image == skillImage)
		{
			return true;
		}

		if (skillImage != classicSource)
		{
			classicSource = skillImage;
			classic = themed(skillImage);
			verdicts.clear();
		}
		if (overrideImage != overrideSource)
		{
			overrideSource = overrideImage;
			override = themed(overrideImage);
			verdicts.clear();
		}

		Boolean verdict = verdicts.get(image);
		if (verdict == null)
		{
			if (verdicts.size() >= MAX_VERDICTS)
			{
				verdicts.clear();
			}
			verdict = samePixels(image, classic) || samePixels(image, override);
			verdicts.put(image, verdict);
		}
		return verdict;
	}

	void reset()
	{
		classicSource = null;
		classic = null;
		overrideSource = null;
		override = null;
		verdicts.clear();
	}

	@VisibleForTesting
	static BufferedImage themed(BufferedImage source)
	{
		return source != null && source.getWidth() > 0 && source.getHeight() > 0
			? ImageUtil.resizeImage(source, THEMED_ICON_SIZE, THEMED_ICON_SIZE) : null;
	}

	@VisibleForTesting
	static boolean samePixels(BufferedImage a, BufferedImage b)
	{
		if (a == null || b == null || a.getWidth() != b.getWidth() || a.getHeight() != b.getHeight())
		{
			return false;
		}
		final int width = a.getWidth();
		final int height = a.getHeight();
		return Arrays.equals(a.getRGB(0, 0, width, height, null, 0, width), b.getRGB(0, 0, width, height, null, 0, width));
	}
}

package com.ghordrin.bosshealthbar;

public enum NativeBossBarMode
{
	REPLACE("Replace it"),
	BOTH("Show both"),
	HIDE_OURS("Hide this bar");

	private final String label;

	NativeBossBarMode(String label)
	{
		this.label = label;
	}

	boolean hidesGameBar()
	{
		return this == REPLACE;
	}

	boolean hidesOurBar()
	{
		return this == HIDE_OURS;
	}

	// The old "Replace game's boss health bar" checkbox: on replaced the game's bar, off hid ours.
	static NativeBossBarMode fromReplaceSetting(String saved)
	{
		if (saved == null)
		{
			return null;
		}
		return Boolean.parseBoolean(saved) ? REPLACE : HIDE_OURS;
	}

	// RuneLite saves the default before the plugin starts, so a saved REPLACE may not be the user's choice.
	static NativeBossBarMode migrate(String oldSaved, String currentSaved)
	{
		final NativeBossBarMode old = fromReplaceSetting(oldSaved);
		if (old == null || (currentSaved != null && !REPLACE.name().equals(currentSaved)))
		{
			return null;
		}
		return old;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.ghordrin.bosshealthbar;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.NPC;
import net.runelite.client.util.Text;
import net.runelite.client.util.WildcardMatcher;

// A list of NPC IDs and names, separated by commas or new lines, where names may use * as a wildcard.
final class NpcFilter
{
	enum Match
	{
		NEVER,
		ALSO,
		NONE
	}

	static final NpcFilter EMPTY = new NpcFilter(new HashSet<>(), new HashSet<>(), new ArrayList<>());

	private final Set<Integer> ids;
	private final Set<String> names;
	private final List<String> patterns;

	private NpcFilter(Set<Integer> ids, Set<String> names, List<String> patterns)
	{
		this.ids = ids;
		this.names = names;
		this.patterns = patterns;
	}

	static NpcFilter parse(String csv)
	{
		if (csv == null || csv.trim().isEmpty())
		{
			return EMPTY;
		}

		final Set<Integer> ids = new HashSet<>();
		final Set<String> names = new HashSet<>();
		final List<String> patterns = new ArrayList<>();
		for (String entry : Text.fromCSV(csv.replace('\n', ',')))
		{
			if (entry.chars().allMatch(Character::isDigit))
			{
				try
				{
					ids.add(Integer.parseInt(entry));
				}
				catch (NumberFormatException e)
				{
					// Too long to be an NPC ID.
				}
			}
			else if (entry.indexOf('*') >= 0)
			{
				patterns.add(entry);
			}
			else
			{
				names.add(Text.standardize(entry));
			}
		}
		return new NpcFilter(ids, names, patterns);
	}

	boolean isEmpty()
	{
		return ids.isEmpty() && names.isEmpty() && patterns.isEmpty();
	}

	// The name must already be standardized.
	boolean matches(String name, int id, int currentId)
	{
		if (ids.contains(id) || ids.contains(currentId) || names.contains(name))
		{
			return true;
		}
		for (String pattern : patterns)
		{
			if (WildcardMatcher.matches(pattern, name))
			{
				return true;
			}
		}
		return false;
	}

	static Match check(NpcFilter never, NpcFilter also, String name, int id, int currentId)
	{
		if (never.matches(name, id, currentId))
		{
			return Match.NEVER;
		}
		return also.matches(name, id, currentId) ? Match.ALSO : Match.NONE;
	}

	// The lists are checked every frame, so the answer is kept for the last NPC, name and form.
	static final class LastMatch
	{
		private NPC npc;
		private String name;
		private int currentId;
		private Match match = Match.NONE;

		Match get(NPC npc, NpcFilter never, NpcFilter also)
		{
			final String name = npc.getName();
			final int currentId = NpcUtil.currentId(npc);
			if (npc != this.npc || currentId != this.currentId || !name.equals(this.name))
			{
				this.npc = npc;
				this.name = name;
				this.currentId = currentId;
				match = check(never, also, Text.standardize(name), NpcUtil.baseId(npc), currentId);
			}
			return match;
		}

		void clear()
		{
			npc = null;
		}
	}
}

package com.ghordrin.bosshealthbar;

import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.gameval.NpcID;

final class NpcUtil
{
	private NpcUtil()
	{
	}

	static boolean isAttackable(NPC npc)
	{
		final NPCComposition composition = npc.getTransformedComposition();
		if (composition == null)
		{
			return false;
		}
		for (String action : composition.getActions())
		{
			if ("Attack".equals(action))
			{
				return true;
			}
		}
		return false;
	}

	static int size(NPC npc)
	{
		final NPCComposition composition = npc.getTransformedComposition();
		return composition != null ? composition.getSize() : 0;
	}

	static int currentId(NPC npc)
	{
		final NPCComposition composition = npc.getTransformedComposition();
		return composition != null ? composition.getId() : npc.getId();
	}

	static boolean canBeDefeated(Actor actor)
	{
		return !(actor instanceof NPC) || canBeDefeated(((NPC) actor).getId());
	}

	// Forms that restore health instead of dying, so 0 health there isn't a kill.
	static boolean canBeDefeated(int npcId)
	{
		switch (npcId)
		{
			case NpcID.ABYSSALSIRE_SIRE_STASIS_SLEEPING:
			case NpcID.ABYSSALSIRE_SIRE_STASIS_AWAKE:
			case NpcID.ABYSSALSIRE_SIRE_STASIS_STUNNED:
			case NpcID.ABYSSALSIRE_SIRE_PUPPET:
			case NpcID.ABYSSALSIRE_SIRE_WANDERING:
			case NpcID.ABYSSALSIRE_SIRE_PANICKING:
				return false;
			default:
				return true;
		}
	}

	// The game's boss bar tracks the base NPC ID, not the ID of the current form.
	static int baseId(NPC npc)
	{
		final NPCComposition composition = npc.getComposition();
		return composition != null ? composition.getId() : -1;
	}
}

package com.ghordrin.bosshealthbar;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import lombok.Value;

// The Oldschool checkbox turns off Match boss colors and Rare gold bars and brings them back when it's
// unticked. Ticking either of those while Oldschool is on unticks Oldschool instead.
final class OldschoolToggle
{
	@Value
	static class Settings
	{
		boolean oldschool;
		boolean matchBossColors;
		boolean rareGoldBars;
		// Null when nothing is remembered.
		Boolean savedMatchBossColors;
		Boolean savedRareGoldBars;
	}

	// A null value means unset the key.
	@Value
	static class Write
	{
		String key;
		Boolean value;
	}

	private OldschoolToggle()
	{
	}

	static boolean handles(String key)
	{
		return BossHealthBarConfig.OLDSCHOOL_THEME_KEY.equals(key)
			|| BossHealthBarConfig.MATCH_BOSS_COLORS_KEY.equals(key)
			|| BossHealthBarConfig.RARE_GOLD_BARS_KEY.equals(key);
	}

	// The defaults of the three boxes. Memory goes first so unticking Oldschool restores nothing.
	static List<Write> resetWrites()
	{
		return Arrays.asList(
			new Write(BossHealthBarConfig.SAVED_MATCH_BOSS_COLORS_KEY, null),
			new Write(BossHealthBarConfig.SAVED_RARE_GOLD_BARS_KEY, null),
			new Write(BossHealthBarConfig.OLDSCHOOL_THEME_KEY, false),
			new Write(BossHealthBarConfig.MATCH_BOSS_COLORS_KEY, false),
			new Write(BossHealthBarConfig.RARE_GOLD_BARS_KEY, true));
	}

	// The remembered keys are cleared before anything is ticked back on, so the change events these
	// writes cause find nothing left to do.
	static List<Write> writes(String key, boolean oldValue, boolean newValue, Settings current)
	{
		if (oldValue == newValue)
		{
			return Collections.emptyList();
		}

		final List<Write> writes = new ArrayList<>();
		if (BossHealthBarConfig.OLDSCHOOL_THEME_KEY.equals(key))
		{
			if (newValue)
			{
				// Switching RuneLite profiles also reports changed keys. Values the new profile already
				// remembers are kept rather than overwritten with the boxes it has turned off.
				if (current.getSavedMatchBossColors() == null)
				{
					writes.add(new Write(BossHealthBarConfig.SAVED_MATCH_BOSS_COLORS_KEY, current.isMatchBossColors()));
				}
				if (current.getSavedRareGoldBars() == null)
				{
					writes.add(new Write(BossHealthBarConfig.SAVED_RARE_GOLD_BARS_KEY, current.isRareGoldBars()));
				}
				writes.add(new Write(BossHealthBarConfig.MATCH_BOSS_COLORS_KEY, false));
				writes.add(new Write(BossHealthBarConfig.RARE_GOLD_BARS_KEY, false));
			}
			else
			{
				restore(writes, null, current);
			}
		}
		else if (newValue && current.isOldschool()
			&& (BossHealthBarConfig.MATCH_BOSS_COLORS_KEY.equals(key) || BossHealthBarConfig.RARE_GOLD_BARS_KEY.equals(key)))
		{
			restore(writes, key, current);
			writes.add(new Write(BossHealthBarConfig.OLDSCHOOL_THEME_KEY, false));
		}
		return writes;
	}

	private static void restore(List<Write> writes, String skippedKey, Settings current)
	{
		if (current.getSavedMatchBossColors() != null)
		{
			writes.add(new Write(BossHealthBarConfig.SAVED_MATCH_BOSS_COLORS_KEY, null));
		}
		if (current.getSavedRareGoldBars() != null)
		{
			writes.add(new Write(BossHealthBarConfig.SAVED_RARE_GOLD_BARS_KEY, null));
		}
		if (current.getSavedMatchBossColors() != null && !BossHealthBarConfig.MATCH_BOSS_COLORS_KEY.equals(skippedKey))
		{
			writes.add(new Write(BossHealthBarConfig.MATCH_BOSS_COLORS_KEY, current.getSavedMatchBossColors()));
		}
		if (current.getSavedRareGoldBars() != null && !BossHealthBarConfig.RARE_GOLD_BARS_KEY.equals(skippedKey))
		{
			writes.add(new Write(BossHealthBarConfig.RARE_GOLD_BARS_KEY, current.getSavedRareGoldBars()));
		}
	}
}

package com.ghordrin.bosshealthbar;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

// Turns off the health bar of RuneLite's Opponent Information plugin while this plugin runs, and
// puts the user's own setting back afterwards.
@Singleton
class OpponentInfoOverride
{
	private static final String GROUP = "opponentinfo";
	private static final String KEY = "showOpponentHealthOverlay";
	// Stored in config so the original value can still be restored if the client closes while hidden.
	private static final String SAVED_KEY = "savedOpponentHealthOverlay";
	private static final String HIDDEN_KEY = "opponentHealthOverlayHidden";

	private final ConfigManager configManager;
	private final BossHealthBarConfig config;

	@Inject
	OpponentInfoOverride(ConfigManager configManager, BossHealthBarConfig config)
	{
		this.configManager = configManager;
		this.config = config;
	}

	void apply()
	{
		if (!config.hideVanillaOverlay())
		{
			return;
		}

		if (!isHidden())
		{
			final String current = configManager.getConfiguration(GROUP, KEY);
			if (current == null)
			{
				configManager.unsetConfiguration(BossHealthBarConfig.GROUP, SAVED_KEY);
			}
			else
			{
				configManager.setConfiguration(BossHealthBarConfig.GROUP, SAVED_KEY, current);
			}
			configManager.setConfiguration(BossHealthBarConfig.GROUP, HIDDEN_KEY, true);
		}

		configManager.setConfiguration(GROUP, KEY, false);
	}

	void restore()
	{
		if (!isHidden())
		{
			return;
		}

		final String saved = configManager.getConfiguration(BossHealthBarConfig.GROUP, SAVED_KEY);
		if (saved == null)
		{
			configManager.unsetConfiguration(GROUP, KEY);
		}
		else
		{
			configManager.setConfiguration(GROUP, KEY, saved);
		}

		configManager.unsetConfiguration(BossHealthBarConfig.GROUP, SAVED_KEY);
		configManager.unsetConfiguration(BossHealthBarConfig.GROUP, HIDDEN_KEY);
	}

	private boolean isHidden()
	{
		return Boolean.parseBoolean(configManager.getConfiguration(BossHealthBarConfig.GROUP, HIDDEN_KEY));
	}
}

package com.ghordrin.bosshealthbar;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.InteractingChanged;

@Slf4j
@Singleton
class OpponentTracker
{
	// Past the longest attack range, with room to reposition, but close enough that walking away counts.
	private static final int COMBAT_DISTANCE = 15;

	private final Client client;
	private final BossHealthBarConfig config;
	private final GameBossBar gameBossBar;
	private final TobBossBar tobBossBar;
	private final SuperiorTracker superiors;
	private final DamageTracker damage;
	private final FightTimer fightTimer;
	private final PairBosses pairs;
	private final BossMemory memory;

	@Getter(AccessLevel.PACKAGE)
	private Actor opponent;
	private long interactionLostMillis;
	private long lastHitTakenMillis;
	private long lastOpponentHitMillis;

	private BossMemory.Entry heldEntry;
	private NPC outOfSightNpc;
	private BossMemory.Entry outOfSightEntry;
	private Actor resumedOpponent;
	private BarState resumedState;
	private boolean opponentSeenDefeated;

	private Actor knownBossActor;
	private String knownBossName;
	private boolean knownBoss;

	private NpcFilter alsoShowFor = NpcFilter.EMPTY;
	private NpcFilter neverShowFor = NpcFilter.EMPTY;
	private final NpcFilter.LastMatch opponentListMatch = new NpcFilter.LastMatch();
	private final NpcFilter.LastMatch gameBarListMatch = new NpcFilter.LastMatch();

	@Inject
	OpponentTracker(Client client, BossHealthBarConfig config, GameBossBar gameBossBar, TobBossBar tobBossBar,
		SuperiorTracker superiors, DamageTracker damage, FightTimer fightTimer, PairBosses pairs, BossMemory memory)
	{
		this.client = client;
		this.config = config;
		this.gameBossBar = gameBossBar;
		this.tobBossBar = tobBossBar;
		this.superiors = superiors;
		this.damage = damage;
		this.fightTimer = fightTimer;
		this.pairs = pairs;
		this.memory = memory;
	}

	void onInteractingChanged(InteractingChanged event)
	{
		if (event.getSource() != client.getLocalPlayer())
		{
			return;
		}

		final Actor target = event.getTarget();
		if (target == null)
		{
			interactionLostMillis = System.currentTimeMillis();
			log.debug("Interaction lost with {}, will clear after {}s if not resumed", opponent, config.hideDelay());
			return;
		}

		interactionLostMillis = 0;

		if (target == opponent)
		{
			return;
		}

		// Attacking the smaller NPCs a boss spawns shouldn't take the bar off the boss.
		if (opponent != null && (!opponent.isDead() || !NpcUtil.canBeDefeated(opponent))
			&& priority(target) < priority(opponent))
		{
			log.debug("Keeping {} over lower priority target {}", opponent.getName(), target.getName());
			return;
		}

		setOpponent(target);
	}

	// While a game boss bar is up, the bar follows the NPC it shows.
	void followGameBars()
	{
		final NPC nativeBarBoss = gameBossBar.findNpc(opponent);
		final NPC gameBarBoss = nativeBarBoss != null ? nativeBarBoss : tobBossBar.findBoss();
		if (gameBarBoss != null && !gameBarBoss.isDead() && gameBarBoss != opponent && !isNeverShown(gameBarBoss))
		{
			setOpponent(gameBarBoss);
			interactionLostMillis = 0;
		}
	}

	void onNpcSpawned(NPC npc)
	{
		final int tick = client.getTickCount();
		final BossMemory.Entry entry = memory.find(npc.getIndex(), npc.getName(), tick);
		if (entry == null || entry != heldEntry || opponent != null || !BossMemory.isHeld(entry.tick, tick)
			|| isNeverShown(npc))
		{
			return;
		}

		// Back in sight soon after leaving it, with nothing else picked meanwhile, so the bar carries on.
		setOpponent(npc);
		interactionLostMillis = System.currentTimeMillis();
	}

	void onNpcDespawned(NPC npc)
	{
		if (npc != opponent)
		{
			if (memory.contains(npc.getIndex()) && isDefeated(npc))
			{
				memory.forget(npc.getIndex());
			}
			return;
		}

		final int tick = client.getTickCount();
		// A bar that despawns with the boss can take its health with it, so the last tick's reading counts too.
		final boolean defeated = opponentSeenDefeated || isDefeated(npc);
		final boolean playerDied = isLocalPlayerDead();
		final int distance = distanceToPlayer(npc);
		final boolean outOfSight = BossMemory.isOutOfSight(defeated, playerDied, distance);
		log.debug("Opponent {} despawned (id {}, current id {}, health {}/{}, dead {}, seen defeated {}, player died {}, distance {}, out of sight {})",
			npc.getName(), npc.getId(), NpcUtil.currentId(npc), npc.getHealthRatio(), npc.getHealthScale(),
			npc.isDead(), opponentSeenDefeated, playerDied, distance, outOfSight);
		opponentSeenDefeated = false;
		fightTimer.opponentDespawned(defeated && !pairs.otherMemberAlive(npc), tick);
		if (outOfSight)
		{
			heldEntry = memory.remember(npc.getIndex(), npc.getName(), tick, fightTimer.save());
			outOfSightNpc = npc;
			outOfSightEntry = heldEntry;
		}
		else
		{
			memory.forget(npc.getIndex());
		}
		resumedOpponent = null;
		resumedState = null;
		opponent = null;
		interactionLostMillis = 0;
		lastOpponentHitMillis = 0;
		damage.resetCombo();
	}

	void onHitsplatApplied(Actor actor, Hitsplat hitsplat)
	{
		if (!isCombatHit(hitsplat.getHitsplatType()))
		{
			return;
		}
		if (actor == client.getLocalPlayer())
		{
			lastHitTakenMillis = System.currentTimeMillis();
		}
		else if (actor != null && actor == opponent)
		{
			lastOpponentHitMillis = System.currentTimeMillis();
		}
	}

	// Clears the opponent once the fight has been quiet for longer than "Hide after", unless a
	// game boss bar still shows it.
	void onGameTick()
	{
		final Player player = client.getLocalPlayer();
		if (opponent == null || player == null || interactionLostMillis == 0)
		{
			return;
		}

		final boolean nearby = !opponent.isDead()
			&& opponent.getWorldArea().distanceTo(player.getWorldLocation()) <= COMBAT_DISTANCE;

		if (opponent != gameBossBar.findNpc(opponent)
			&& opponent != tobBossBar.findBoss()
			&& player.getInteracting() == null
			&& isQuietFor(interactionLostMillis, lastHitTakenMillis, lastOpponentHitMillis, nearby,
				System.currentTimeMillis(), config.hideDelay() * 1000L))
		{
			log.debug("Opponent {} timed out after {}s with no combat, clearing", opponent, config.hideDelay());
			opponent = null;
			fightTimer.reset();
			opponentSeenDefeated = false;
		}
	}

	static boolean isQuietFor(long interactionLostMillis, long lastHitTakenMillis, long lastOpponentHitMillis,
		boolean nearby, long now, long delayMillis)
	{
		if (interactionLostMillis == 0)
		{
			return false;
		}
		long lastCombat = interactionLostMillis;
		if (nearby)
		{
			lastCombat = Math.max(lastCombat, Math.max(lastHitTakenMillis, lastOpponentHitMillis));
		}
		return now - lastCombat > delayMillis;
	}

	// Damage over time is left out on purpose, so ticks that linger after a fight don't keep the bar up.
	static boolean isCombatHit(int hitsplatType)
	{
		switch (hitsplatType)
		{
			case HitsplatID.BLOCK_ME:
			case HitsplatID.BLOCK_OTHER:
			case HitsplatID.DAMAGE_ME:
			case HitsplatID.DAMAGE_OTHER:
			case HitsplatID.DAMAGE_ME_CYAN:
			case HitsplatID.DAMAGE_OTHER_CYAN:
			case HitsplatID.DAMAGE_ME_ORANGE:
			case HitsplatID.DAMAGE_OTHER_ORANGE:
			case HitsplatID.DAMAGE_ME_YELLOW:
			case HitsplatID.DAMAGE_OTHER_YELLOW:
			case HitsplatID.DAMAGE_ME_WHITE:
			case HitsplatID.DAMAGE_OTHER_WHITE:
			case HitsplatID.DAMAGE_MAX_ME:
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
			case HitsplatID.DAMAGE_MAX_ME_ORANGE:
			case HitsplatID.DAMAGE_MAX_ME_YELLOW:
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
			case HitsplatID.DAMAGE_ME_POISE:
			case HitsplatID.DAMAGE_OTHER_POISE:
			case HitsplatID.DAMAGE_MAX_ME_POISE:
				return true;
			default:
				return false;
		}
	}

	boolean shouldShowBarFor(Actor actor)
	{
		if (actor == null || actor.getName() == null)
		{
			return false;
		}

		final NpcFilter.Match match = listMatch(opponentListMatch, actor);
		return match != NpcFilter.Match.NEVER
			&& (match == NpcFilter.Match.ALSO
				|| !config.bossOnly()
				|| isKnownBoss(actor)
				|| isGameBarBoss(actor)
				|| (config.showAboveCombatLevel() && actor.getCombatLevel() >= config.minimumCombatLevel())
				|| (config.showSuperiors() && superiors.isSuperior(actor)));
	}

	// Matches the bar's Defeated: some bosses on the game's bar never set isDead() while they die, so 0 health counts too.
	boolean isDefeated(Actor actor)
	{
		if (!NpcUtil.canBeDefeated(actor))
		{
			return false;
		}
		if (actor.isDead())
		{
			return true;
		}
		final int nativeMaxHealth = gameBossBar.isTracking(actor) && gameBossBar.hasHealth() ? gameBossBar.maxHealth() : 0;
		if (nativeMaxHealth > 0)
		{
			return gameBossBar.health() <= 0;
		}
		final int tobMaxHealth = tobBossBar.isTracking(actor) ? tobBossBar.maxHealth() : 0;
		if (tobMaxHealth > 0)
		{
			return tobBossBar.health(tobMaxHealth) <= 0;
		}
		if (actor.getHealthScale() <= 0)
		{
			return false;
		}
		// Some turn into a form that can't be attacked as they die, before their bar reaches 0.
		return actor.getHealthRatio() == 0
			|| actor.getHealthRatio() == 1 && actor instanceof NPC && !NpcUtil.isAttackable((NPC) actor);
	}

	// Back for another phase after being defeated: it can be attacked again with health to spare.
	private static boolean isBackUp(Actor actor)
	{
		return actor instanceof NPC && !actor.isDead() && NpcUtil.isAttackable((NPC) actor)
			&& actor.getHealthScale() > 0 && actor.getHealthRatio() > 1;
	}

	// For the fight timer, a pair's fight only ends with its last member.
	boolean isFightOver(Actor actor)
	{
		return isDefeated(actor) && !pairs.otherMemberAlive(actor);
	}

	void reset()
	{
		opponent = null;
		interactionLostMillis = 0;
		lastHitTakenMillis = 0;
		lastOpponentHitMillis = 0;
		knownBossActor = null;
		knownBossName = null;
		opponentListMatch.clear();
		gameBarListMatch.clear();
		fightTimer.reset();
		memory.clear();
		heldEntry = null;
		outOfSightNpc = null;
		outOfSightEntry = null;
		opponentSeenDefeated = false;
		resumedOpponent = null;
		resumedState = null;
	}

	boolean wentOutOfSight(Actor actor)
	{
		return actor != null && actor == outOfSightNpc;
	}

	// The bar's last reading of an opponent that went out of sight, shown again if it comes back.
	void rememberState(Actor actor, BarState state)
	{
		if (actor == outOfSightNpc && outOfSightEntry != null)
		{
			outOfSightEntry.state = state;
		}
		outOfSightNpc = null;
		outOfSightEntry = null;
	}

	// The bar's last reading was 0, so the despawn was a kill after all.
	void forgetOutOfSight(Actor actor)
	{
		if (actor != outOfSightNpc)
		{
			return;
		}
		log.debug("Opponent {} was last read at 0 health, counting its despawn as a kill", actor.getName());
		memory.forget(outOfSightNpc.getIndex());
		if (heldEntry == outOfSightEntry)
		{
			heldEntry = null;
		}
		if (opponent == null)
		{
			fightTimer.opponentDespawned(true, client.getTickCount());
		}
		outOfSightNpc = null;
		outOfSightEntry = null;
	}

	// No member of the pair has been around for a while, so coming back to it later is a new fight.
	void pairCleared(String pair)
	{
		log.debug("Pair {} was forgotten, its next fight starts over", pair);
		fightTimer.pairCleared(pair);
		memory.forgetFight(pair);
	}

	void healedOnReturn(Actor actor)
	{
		log.debug("Remembered opponent {} came back with more health, starting a new fight", actor.getName());
		fightTimer.startOver(client.getTickCount());
	}

	BarState resumedState(Actor actor)
	{
		return actor != null && actor == resumedOpponent ? resumedState : null;
	}

	private int distanceToPlayer(NPC npc)
	{
		final Player player = client.getLocalPlayer();
		if (player == null)
		{
			return -1;
		}
		final WorldPoint tile = npc.getWorldLocation();
		final WorldPoint location = player.getWorldLocation();
		if (tile.getPlane() != location.getPlane())
		{
			return Integer.MAX_VALUE;
		}
		return BossMemory.tileDistance(tile.getX(), tile.getY(), location.getX(), location.getY());
	}

	private boolean isLocalPlayerDead()
	{
		final Player player = client.getLocalPlayer();
		return player != null && (player.isDead() || client.getBoostedSkillLevel(Skill.HITPOINTS) <= 0);
	}

	// Called once a tick. Kept for the despawn, when a boss bar may already have lost the health.
	boolean updateOpponentDefeated()
	{
		// Once defeated it stays so, since some die by turning into a death form that still shows a bit of health.
		opponentSeenDefeated = opponent != null
			&& (isDefeated(opponent) || opponentSeenDefeated && !isBackUp(opponent));
		return opponentSeenDefeated;
	}

	void loadLists()
	{
		alsoShowFor = NpcFilter.parse(config.alsoShowFor());
		neverShowFor = NpcFilter.parse(config.neverShowFor());
		opponentListMatch.clear();
		gameBarListMatch.clear();
	}

	private void setOpponent(Actor target)
	{
		final int tick = client.getTickCount();
		final BossMemory.Entry returned = target instanceof NPC
			? memory.take(((NPC) target).getIndex(), target.getName(), tick) : null;
		damage.resetCombo();
		heldEntry = null;
		opponentSeenDefeated = false;
		if (returned != null)
		{
			log.debug("Remembered opponent {} came back after {} ticks (remembered health {}/{}, fight start tick {})",
				target.getName(), tick - returned.tick, returned.state != null ? returned.state.ratio : -1,
				returned.state != null ? returned.state.scale : -1, returned.fight.startTick);
			fightTimer.opponentReturned(target, returned.fight, tick);
			resumedOpponent = target;
			resumedState = returned.state;
		}
		else
		{
			final String fightName = PairBosses.fightName(target);
			fightTimer.opponentChanged(target, fightName, opponent != null && isFightOver(opponent), pairs.hasPair(fightName),
				tick);
			resumedOpponent = null;
			resumedState = null;
		}
		opponent = target;
		lastOpponentHitMillis = 0;
		log.debug("New opponent: {} (combat level {}, known boss: {}, game boss bar: {})",
			target.getName(), target.getCombatLevel(), KnownBosses.contains(target.getName()), isGameBarBoss(target));
	}

	private int priority(Actor actor)
	{
		if (actor == null)
		{
			return -1;
		}
		if (!shouldShowBarFor(actor))
		{
			return 0;
		}
		return gameBossBar.isTracking(actor) || tobBossBar.isTracking(actor) ? 2 : 1;
	}

	private boolean isGameBarBoss(Actor actor)
	{
		return actor != null && (gameBossBar.isTracking(actor) || actor == tobBossBar.cachedBoss());
	}

	// Checked every frame, so the answer is kept for the last actor and name.
	private boolean isKnownBoss(Actor actor)
	{
		final String name = actor.getName();
		if (actor != knownBossActor || !name.equals(knownBossName))
		{
			knownBossActor = actor;
			knownBossName = name;
			knownBoss = KnownBosses.contains(name);
		}
		return knownBoss;
	}

	// Kept apart from the opponent's cached answer, so checking both each frame doesn't redo the match.
	private boolean isNeverShown(NPC npc)
	{
		return npc.getName() != null && listMatch(gameBarListMatch, npc) == NpcFilter.Match.NEVER;
	}

	private NpcFilter.Match listMatch(NpcFilter.LastMatch last, Actor actor)
	{
		if (!(actor instanceof NPC) || (alsoShowFor.isEmpty() && neverShowFor.isEmpty()))
		{
			return NpcFilter.Match.NONE;
		}
		return last.get((NPC) actor, neverShowFor, alsoShowFor);
	}
}

package com.ghordrin.bosshealthbar;

import com.google.common.collect.ImmutableSet;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.gameval.NpcID;
import net.runelite.client.game.NPCManager;
import net.runelite.client.util.Text;

// Bosses fought as two NPCs that take turns. Both count as one fight, and each keeps its last known state.
@Slf4j
@Singleton
class PairBosses
{
	static final String GUARDIANS = "grotesque guardians";
	// The members of a pair can be out of sight for a while, so they're only forgotten after this long.
	static final int CLEAR_TICKS = 10;

	static final class Member
	{
		final String pair;
		final int side;

		Member(String pair, int side)
		{
			this.pair = pair;
			this.side = side;
		}
	}

	static final class Slot
	{
		final Member member;
		NPC npc;
		boolean dead;
		int lastPresentTick;
		String name;
		int ratio = -1;
		int scale = -1;
		boolean exact;
		Integer maxHealth;
		BarState state;

		Slot(Member member)
		{
			this.member = member;
		}
	}

	private static final Map<Integer, Member> MEMBERS;

	static
	{
		final Map<Integer, Member> members = new HashMap<>();
		final Member dawn = new Member(GUARDIANS, 0);
		final Member dusk = new Member(GUARDIANS, 1);
		for (int id : new int[]{NpcID.GARGBOSS_DAWN_SPAWN, NpcID.GARGBOSS_DAWN_PHASE1,
			NpcID.GARGBOSS_DAWN_PHASE1_TRANSITION, NpcID.GARGBOSS_DAWN_PHASE3, NpcID.GARGBOSS_DAWN_DEATH})
		{
			members.put(id, dawn);
		}
		for (int id : new int[]{NpcID.GARGBOSS_DUSK_SPAWN, NpcID.GARGBOSS_DUSK_PHASE1_DEFENSIVE,
			NpcID.GARGBOSS_DUSK_PHASE1_TRANSITION, NpcID.GARGBOSS_DUSK_PHASE1_FLYTRANSITION,
			NpcID.GARGBOSS_DUSK_PHASE2_ATTACKING, NpcID.GARGBOSS_DUSK_PHASE3_DEFENSIVE,
			NpcID.GARGBOSS_DUSK_PHASE3_TRANSITION, NpcID.GARGBOSS_DUSK_PHASE4_SPAWN, NpcID.GARGBOSS_DUSK_PHASE4,
			NpcID.GARGBOSS_DUSK_DEATH})
		{
			members.put(id, dusk);
		}
		MEMBERS = Collections.unmodifiableMap(members);
	}

	// The forms the members spawn in when a fight starts, at full health.
	private static final Set<Integer> START_FORMS = ImmutableSet.of(NpcID.GARGBOSS_DAWN_SPAWN, NpcID.GARGBOSS_DUSK_SPAWN);
	// The forms the members change into as they die.
	private static final Set<Integer> DEATH_FORMS = ImmutableSet.of(NpcID.GARGBOSS_DAWN_DEATH, NpcID.GARGBOSS_DUSK_DEATH);

	private final Client client;
	private final GameBossBar gameBossBar;
	private final NPCManager npcManager;
	private final List<Slot> slots = new ArrayList<>();
	private final Set<String> ended = new HashSet<>();

	@Inject
	PairBosses(Client client, GameBossBar gameBossBar, NPCManager npcManager)
	{
		this.client = client;
		this.gameBossBar = gameBossBar;
		this.npcManager = npcManager;
	}

	static boolean isStartForm(int npcId)
	{
		return START_FORMS.contains(npcId);
	}

	static boolean isDeathForm(int npcId)
	{
		return DEATH_FORMS.contains(npcId);
	}

	static boolean isDying(NPC npc)
	{
		return npc.isDead() || isDeathForm(NpcUtil.currentId(npc));
	}

	static Member member(int npcId)
	{
		return MEMBERS.get(npcId);
	}

	static Member member(Actor actor)
	{
		return actor instanceof NPC ? member(NpcUtil.currentId((NPC) actor)) : null;
	}

	static boolean isPairMember(Actor actor)
	{
		return member(actor) != null;
	}

	static boolean isPairKey(String name)
	{
		return GUARDIANS.equals(name);
	}

	static Map<Integer, Member> members()
	{
		return MEMBERS;
	}

	// The name the fight timer goes by: the pair's, so swapping between its members carries on the fight.
	static String fightName(Actor actor)
	{
		final Member member = member(actor);
		return member != null ? member.pair : actor.getName();
	}

	void onNpcSpawned(NPC npc)
	{
		final Member member = member(npc);
		if (member == null)
		{
			return;
		}
		log.debug("Pair member {} spawned (id {})", npc.getName(), NpcUtil.currentId(npc));
		final Slot slot = slot(slots, member, true);
		final int id = NpcUtil.currentId(npc);
		slot.npc = npc;
		slot.dead = isDeathForm(id);
		slot.lastPresentTick = client.getTickCount();
		rename(slot, npc);
		if (isStartForm(id))
		{
			log.debug("Pair member {} spawned in its start form (id {}), seeding it at full health", npc.getName(), id);
			seedFull(slot, npcManager.getHealth(id));
		}
	}

	void onNpcChanged(NPC npc)
	{
		final Member member = member(npc);
		final Slot previous = slotOf(npc);
		if (previous != null && previous.member != member)
		{
			previous.npc = null;
		}
		if (member != null)
		{
			final Slot slot = slot(slots, member, true);
			slot.npc = npc;
			slot.lastPresentTick = client.getTickCount();
			if (isDeathForm(NpcUtil.currentId(npc)))
			{
				slot.dead = true;
			}
			rename(slot, npc);
		}
	}

	void onNpcDespawned(NPC npc)
	{
		final Slot slot = slotOf(npc);
		if (slot != null)
		{
			despawned(slots, slot, isDying(npc));
			if (!hasPair(slot.member.pair))
			{
				// Both members died, so the next ones that spawn start a new fight.
				ended.add(slot.member.pair);
			}
		}
	}

	// Returns the pairs that were forgotten this tick.
	Set<String> onGameTick(Actor opponent)
	{
		final int tick = client.getTickCount();
		adopt(opponent, tick);
		adopt(gameBossBar.findNpc(opponent), tick);
		for (Slot slot : slots)
		{
			final NPC npc = slot.npc;
			if (npc != null)
			{
				slot.lastPresentTick = tick;
				final boolean gameBar = gameBossBar.isTracking(npc) && gameBossBar.hasHealth();
				read(slot, gameBar ? gameBossBar.health() : 0, gameBar ? gameBossBar.maxHealth() : 0,
					npc.getHealthRatio(), npc.getHealthScale(), npcManager.getHealth(NpcUtil.currentId(npc)));
				updateDead(slot, isDying(npc));
			}
		}
		final Set<String> cleared = clearGone(slots, tick);
		if (ended.isEmpty())
		{
			return cleared;
		}
		final Set<String> over = new HashSet<>(cleared);
		over.addAll(ended);
		ended.clear();
		return over;
	}

	// A member that was already there when the plugin started never spawned for us. It's picked up once it's the
	// opponent or on the game's boss bar, and its partner with a single look through the scene.
	private void adopt(Actor actor, int tick)
	{
		final Member member = member(actor);
		if (member == null || slot(slots, member, false) != null)
		{
			return;
		}
		final boolean pairKnown = hasPair(slots, member.pair);
		adopt((NPC) actor, member, tick);
		if (pairKnown || client.getTopLevelWorldView() == null)
		{
			return;
		}
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			final Member other = member(npc);
			if (other != null && other.pair.equals(member.pair) && slot(slots, other, false) == null)
			{
				adopt(npc, other, tick);
			}
		}
	}

	// Health is unknown here, so the slot stays empty until a reading comes in.
	private void adopt(NPC npc, Member member, int tick)
	{
		log.debug("Pair member {} found without a spawn (id {})", npc.getName(), NpcUtil.currentId(npc));
		final Slot slot = slot(slots, member, true);
		slot.npc = npc;
		slot.dead = isDying(npc);
		slot.lastPresentTick = tick;
		rename(slot, npc);
	}

	static void updateDead(Slot slot, boolean dying)
	{
		if (dying || (slot.scale > 0 && slot.ratio == 0))
		{
			slot.dead = true;
		}
		else if (slot.scale > 0 && slot.ratio > 0)
		{
			slot.dead = false;
		}
	}

	// Held from the first member seen until both have died or been out of sight for CLEAR_TICKS.
	boolean hasPair(String pair)
	{
		return hasPair(slots, pair);
	}

	static boolean hasPair(List<Slot> slots, String pair)
	{
		for (Slot slot : slots)
		{
			if (slot.member.pair.equals(pair))
			{
				return true;
			}
		}
		return false;
	}

	// The other member of the actor's pair, if it has health to show.
	Slot partnerOf(Actor actor)
	{
		final Member member = member(actor);
		final Slot slot = member != null ? partner(slots, member) : null;
		return withHealth(slot);
	}

	private static Slot withHealth(Slot slot)
	{
		if (slot == null || slot.scale <= 0)
		{
			return null;
		}
		if (slot.state == null)
		{
			slot.state = new BarState(slot.name, 0, slot.maxHealth, slot.ratio, slot.scale, slot.exact, false,
				BarState.NO_PHASE_MARKERS, HealthIndicatorMarkers.NONE, null, null, Collections.emptyList(), null);
		}
		return slot;
	}

	// Whether the other member of the actor's pair is still in the fight, even while it's out of sight.
	boolean otherMemberAlive(Actor actor)
	{
		final Member member = member(actor);
		if (member == null)
		{
			return false;
		}
		for (Slot slot : slots)
		{
			if (slot.member.pair.equals(member.pair) && slot.member.side != member.side && isAlive(slot))
			{
				return true;
			}
		}
		return false;
	}

	void reset()
	{
		slots.clear();
		ended.clear();
	}

	private Slot slotOf(NPC npc)
	{
		for (Slot slot : slots)
		{
			if (slot.npc == npc)
			{
				return slot;
			}
		}
		return null;
	}

	private static void rename(Slot slot, NPC npc)
	{
		final String name = npc.getName() != null ? Text.removeTags(npc.getName()) : null;
		if (name != null && !name.equals(slot.name))
		{
			slot.name = name;
			slot.state = null;
		}
	}

	// The game's boss bar has exact health, then a fresh overhead bar. Without either, the last reading is kept,
	// since the overhead bar of a member that isn't being hit soon goes away.
	static boolean read(Slot slot, int barHealth, int barMaxHealth, int ratio, int scale, Integer maxHealth)
	{
		if (barMaxHealth > 0)
		{
			return set(slot, barHealth, barMaxHealth, true, barMaxHealth);
		}
		if (scale > 0 && ratio >= 0)
		{
			return set(slot, ratio, scale, false, maxHealth);
		}
		return false;
	}

	static void seedFull(Slot slot, Integer maxHealth)
	{
		if (maxHealth != null && maxHealth > 0)
		{
			set(slot, maxHealth, maxHealth, true, maxHealth);
		}
		else
		{
			set(slot, 1, 1, false, null);
		}
	}

	private static boolean set(Slot slot, int ratio, int scale, boolean exact, Integer maxHealth)
	{
		if (slot.ratio == ratio && slot.scale == scale && slot.exact == exact && Objects.equals(slot.maxHealth, maxHealth))
		{
			return false;
		}
		slot.ratio = ratio;
		slot.scale = scale;
		slot.exact = exact;
		slot.maxHealth = maxHealth;
		slot.state = null;
		return true;
	}

	static Slot partner(List<Slot> slots, Member member)
	{
		for (Slot slot : slots)
		{
			if (slot.member.pair.equals(member.pair) && slot.member.side != member.side)
			{
				return slot;
			}
		}
		return null;
	}

	static boolean isAlive(Slot slot)
	{
		return !slot.dead && (slot.npc == null || !isDying(slot.npc));
	}

	static Slot slot(List<Slot> slots, Member member, boolean create)
	{
		for (Slot slot : slots)
		{
			if (slot.member == member)
			{
				return slot;
			}
		}
		if (!create)
		{
			return null;
		}
		final Slot slot = new Slot(member);
		slots.add(slot);
		return slot;
	}

	// A member that dies is gone for good, one that leaves alive is kept with its last state.
	static void despawned(List<Slot> slots, Slot slot, boolean npcDead)
	{
		if (npcDead || slot.dead)
		{
			slots.remove(slot);
		}
		else
		{
			slot.npc = null;
		}
	}

	static Set<String> clearGone(List<Slot> slots, int tick)
	{
		if (slots.isEmpty())
		{
			return Collections.emptySet();
		}
		final Map<String, Integer> lastPresent = new HashMap<>();
		for (Slot slot : slots)
		{
			lastPresent.merge(slot.member.pair, slot.npc != null ? Integer.MAX_VALUE : slot.lastPresentTick, Math::max);
		}
		lastPresent.values().removeIf(lastTick -> tick - lastTick <= CLEAR_TICKS);
		if (lastPresent.isEmpty())
		{
			return Collections.emptySet();
		}
		slots.removeIf(slot -> lastPresent.containsKey(slot.member.pair));
		return lastPresent.keySet();
	}
}

package com.ghordrin.bosshealthbar;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;

// Shares your hits on the current opponent with your RuneLite party, so members who count party
// damage can add them to their number.
@Singleton
class PartyDamage
{
	private final Client client;
	private final BossHealthBarConfig config;
	private final PartyService partyService;
	private final WSClient wsClient;
	private final OpponentTracker opponentTracker;
	private final DamageTracker damageTracker;

	@Inject
	PartyDamage(Client client, BossHealthBarConfig config, PartyService partyService, WSClient wsClient,
		OpponentTracker opponentTracker, DamageTracker damageTracker)
	{
		this.client = client;
		this.config = config;
		this.partyService = partyService;
		this.wsClient = wsClient;
		this.opponentTracker = opponentTracker;
		this.damageTracker = damageTracker;
	}

	void startUp()
	{
		wsClient.registerMessage(BossBarPartyHit.class);
	}

	void shutDown()
	{
		wsClient.unregisterMessage(BossBarPartyHit.class);
	}

	void sendHit(Actor target, int damage)
	{
		if (damage <= 0 || !(target instanceof NPC) || !partyService.isInParty())
		{
			return;
		}
		partyService.send(new BossBarPartyHit(client.getWorld(), ((NPC) target).getIndex(), damage));
	}

	boolean countsPartyHits()
	{
		return config.damageNumberSource() == DamageNumberSource.PARTY && partyService.isInParty();
	}

	void onPartyHit(BossBarPartyHit hit)
	{
		if (!countsPartyHits())
		{
			return;
		}

		final PartyMember local = partyService.getLocalMember();
		if (local != null && local.getMemberId() == hit.getMemberId())
		{
			return;
		}

		final Actor opponent = opponentTracker.getOpponent();
		if (opponent instanceof NPC && ((NPC) opponent).getIndex() == hit.getNpcIndex() && client.getWorld() == hit.getWorld())
		{
			damageTracker.recordPartyHit(hit.getDamage(), client.getTickCount());
		}
	}
}

