import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.Text;

// Reads the defence the "Better Party Defence" or "Party Defence Tracker" plugin shows in its info box,
// and the magic defence from Better Party Defence.
@Slf4j
@Singleton
class PartyDefence
{
	private static final String PLUGIN_NAME = "Party Defence Tracker";
	private static final String BETTER_PLUGIN_NAME = "Better Party Defence";
	// InfoBox.getName() defaults to the plugin's class name and the info box's class name.
	@VisibleForTesting
	static final String BOX_NAME = "DefenceTrackerPlugin_DefenceInfoBox";
	@VisibleForTesting
	static final String BETTER_BOX_NAME = "BetterPartyDefencePlugin_DefenceInfoBox";

	@Value
	static class Reading
	{
		String text;
		Color color;
	}

	// Their info box can be gone for a tick while it's rebuilt, so the last reading is kept for one tick.
	@VisibleForTesting
	static class HeldReading
	{
		private String readingName;
		private Reading reading;
		private boolean missedTick;

		void accept(String name, Reading found)
		{
			if (found != null)
			{
				readingName = name;
				reading = found;
				missedTick = false;
			}
			else if (reading != null && !missedTick && Objects.equals(name, readingName))
			{
				missedTick = true;
			}
			else
			{
				clear();
			}
		}

		Reading readingFor(String name)
		{
			return name != null && name.equals(readingName) ? reading : null;
		}

		void clear()
		{
			readingName = null;
			reading = null;
			missedTick = false;
		}
	}

	private final Client client;
	private final BossHealthBarConfig config;
	private final PluginManager pluginManager;
	private final InfoBoxManager infoBoxManager;
	private final SkillIconManager skillIconManager;

	private Boolean pluginActive;
	private Boolean betterPluginActive;
	private boolean available;
	private boolean magicAvailable;
	private final HeldReading defence = new HeldReading();
	private final HeldReading magic = new HeldReading();
	private BufferedImage icon;
	private BufferedImage magicIcon;
	private final MagicIconMatcher magicIconMatcher = new MagicIconMatcher();
	private SpritePixels magicOverrideSource;
	private BufferedImage magicOverrideImage;

	@Inject
	PartyDefence(Client client, BossHealthBarConfig config, PluginManager pluginManager, InfoBoxManager infoBoxManager,
		SkillIconManager skillIconManager)
	{
		this.client = client;
		this.config = config;
		this.pluginManager = pluginManager;
		this.infoBoxManager = infoBoxManager;
		this.skillIconManager = skillIconManager;
	}

	void invalidatePlugin()
	{
		pluginActive = null;
		betterPluginActive = null;
	}

	void reset()
	{
		pluginActive = null;
		betterPluginActive = null;
		available = false;
		magicAvailable = false;
		defence.clear();
		magic.clear();
		magicIconMatcher.reset();
		magicOverrideSource = null;
		magicOverrideImage = null;
	}

	// Called each game tick, so the overlay doesn't go through the info boxes every frame.
	void update(Actor opponent)
	{
		if (pluginActive == null)
		{
			pluginActive = isPluginActive(PLUGIN_NAME);
		}
		if (betterPluginActive == null)
		{
			betterPluginActive = isPluginActive(BETTER_PLUGIN_NAME);
		}
		available = (pluginActive || betterPluginActive) && config.showPartyDefence();
		magicAvailable = betterPluginActive && config.showMagicDefence();

		final String name = opponent != null ? opponent.getName() : null;
		if (!available || name == null)
		{
			defence.clear();
		}
		if (!magicAvailable || name == null)
		{
			magic.clear();
		}
		if (name == null || !available && !magicAvailable)
		{
			return;
		}

		try
		{
			final List<InfoBox> infoBoxes = infoBoxManager.getInfoBoxes();
			final Predicate<BufferedImage> isMagic = betterPluginActive ? magicTest() : image -> false;
			if (available)
			{
				defence.accept(name, select(infoBoxes, name, betterPluginActive, isMagic));
			}
			if (magicAvailable)
			{
				magic.accept(name, findBetterMagic(infoBoxes, isMagic));
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't read party defence info box", e);
			defence.clear();
			magic.clear();
		}
	}

	private Predicate<BufferedImage> magicTest()
	{
		final BufferedImage skillImage = skillIconManager.getSkillImage(Skill.MAGIC);
		final Map<Integer, SpritePixels> overrides = client.getSpriteOverrides();
		final SpritePixels override = overrides != null ? overrides.get(SpriteID.Staticons.MAGIC) : null;
		if (override != magicOverrideSource)
		{
			magicOverrideSource = override;
			magicOverrideImage = override != null ? override.toBufferedImage() : null;
		}
		final BufferedImage overrideImage = magicOverrideImage;
		return image -> magicIconMatcher.isMagic(image, skillImage, overrideImage);
	}

	boolean isAvailable()
	{
		return available;
	}

	boolean isMagicAvailable()
	{
		return magicAvailable;
	}

	Reading readingFor(Actor opponent)
	{
		return opponent != null ? defence.readingFor(opponent.getName()) : null;
	}

	Reading magicReadingFor(Actor opponent)
	{
		return opponent != null ? magic.readingFor(opponent.getName()) : null;
	}

	BufferedImage icon()
	{
		if (icon == null)
		{
			icon = skillIconManager.getSkillImage(Skill.DEFENCE, true);
		}
		return icon;
	}

	BufferedImage magicIcon()
	{
		if (magicIcon == null)
		{
			magicIcon = skillIconManager.getSkillImage(Skill.MAGIC, true);
		}
		return magicIcon;
	}

	private boolean isPluginActive(String pluginName)
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (pluginName.equals(plugin.getName()))
			{
				return pluginManager.isPluginActive(plugin);
			}
		}
		return false;
	}

	@VisibleForTesting
	static Reading find(List<InfoBox> infoBoxes, String opponentName)
	{
		for (InfoBox infoBox : infoBoxes)
		{
			if (!matches(infoBox, opponentName))
			{
				continue;
			}
			final String text = infoBox.getText();
			if (text != null && !text.isEmpty())
			{
				return new Reading(text, infoBox.getTextColor());
			}
		}
		return null;
	}

	// Better Party Defence removes the other plugin's boxes while it runs, so its box wins when it's on.
	@VisibleForTesting
	static Reading select(List<InfoBox> infoBoxes, String opponentName, boolean betterPluginActive,
		Predicate<BufferedImage> isMagic)
	{
		return betterPluginActive ? findBetter(infoBoxes, isMagic) : find(infoBoxes, opponentName);
	}

	// Its tooltip doesn't name the NPC, so the reading is for whichever NPC that plugin tracks.
	@VisibleForTesting
	static Reading findBetter(List<InfoBox> infoBoxes, Predicate<BufferedImage> isMagic)
	{
		final List<InfoBox> boxes = betterBoxes(infoBoxes);
		final InfoBox magicBox = magicBox(boxes, isMagic);
		for (InfoBox box : boxes)
		{
			if (box != magicBox)
			{
				return reading(box);
			}
		}
		return null;
	}

	@VisibleForTesting
	static Reading findBetterMagic(List<InfoBox> infoBoxes, Predicate<BufferedImage> isMagic)
	{
		final InfoBox magicBox = magicBox(betterBoxes(infoBoxes), isMagic);
		return magicBox != null ? reading(magicBox) : null;
	}

	// The Defence and Magic defence boxes share a name and can be added in either order, so only the image
	// tells them apart. A box that isn't recognised as Magic is taken as Defence.
	private static InfoBox magicBox(List<InfoBox> boxes, Predicate<BufferedImage> isMagic)
	{
		for (InfoBox box : boxes)
		{
			if (isMagic.test(box.getImage()))
			{
				return box;
			}
		}
		return null;
	}

	private static List<InfoBox> betterBoxes(List<InfoBox> infoBoxes)
	{
		final List<InfoBox> boxes = new ArrayList<>(2);
		for (InfoBox infoBox : infoBoxes)
		{
			if (infoBox != null && BETTER_BOX_NAME.equals(infoBox.getName()))
			{
				boxes.add(infoBox);
			}
		}
		return boxes;
	}

	private static Reading reading(InfoBox infoBox)
	{
		final String text = infoBox.getText();
		return text != null && !text.isEmpty() ? new Reading(text, infoBox.getTextColor()) : null;
	}

	@VisibleForTesting
	static boolean matches(InfoBox infoBox, String opponentName)
	{
		if (infoBox == null || opponentName == null || !BOX_NAME.equals(infoBox.getName()))
		{
			return false;
		}
		final String tooltip = infoBox.getTooltip();
		return tooltip != null && Text.removeTags(tooltip).trim().equalsIgnoreCase(Text.removeTags(opponentName).trim());
	}
}

package com.ghordrin.bosshealthbar;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.chatbox.ChatboxItemSearch;

// Opens the custom icon search and the fill texture window.
@Singleton
class Pickers
{
	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final BossHealthBarConfig config;
	private final ChatboxItemSearch itemSearch;

	// Only touched on the EDT.
	private FillTexturePickerDialog texturePickerDialog;

	@Inject
	Pickers(Client client, ClientThread clientThread, ConfigManager configManager, BossHealthBarConfig config,
		ChatboxItemSearch itemSearch)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.config = config;
		this.itemSearch = itemSearch;
	}

	// Must be called on the client thread.
	void openIconPicker()
	{
		itemSearch
			.tooltipText("Custom icon")
			.onItemSelected(itemId -> configManager.setConfiguration(
				BossHealthBarConfig.GROUP, BossHealthBarConfig.CUSTOM_ICON_ITEM_ID_KEY, itemId))
			.build();
	}

	// The item search lives in the chatbox, so it only opens while logged in.
	void openIconPickerIfLoggedIn()
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				openIconPicker();
			}
		});
	}

	void openFillTexturePicker()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (texturePickerDialog == null || !texturePickerDialog.isDisplayable())
			{
				texturePickerDialog = new FillTexturePickerDialog(client, clientThread, configManager, config);
			}
			texturePickerDialog.setVisible(true);
			texturePickerDialog.toFront();
		});
	}

	void close()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (texturePickerDialog != null)
			{
				texturePickerDialog.dispose();
				texturePickerDialog = null;
			}
		});
	}
}

package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.BarAnimation.clamp01;
import java.util.Arrays;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

// The game's pillar charge bars, read from the scripts that drive them so they can be drawn while the game's are hidden.
@Slf4j
@Singleton
class PillarBars
{
	// Client script ids, which have no gameval constants.
	static final int UPDATE_SCRIPT = 3315;
	static final int FADE_IN_SCRIPT = 3312;
	static final int FADE_OUT_SCRIPT = 3323;

	static final int CORNERS = 4;
	private static final int ARGS_PER_CORNER = 4;
	// The script id, four corners and a trailing flag.
	static final int UPDATE_ARGS = 1 + CORNERS * ARGS_PER_CORNER + 1;
	private static final int UNCHANGED = -1;
	private static final int TRANSPARENT = 255;

	// In drawing order: north west, north east, south west, south east.
	private static final int[] BAR_BACKS = {
		InterfaceID.NightmareTotems.TOTEM_NW_BAR_BACK,
		InterfaceID.NightmareTotems.TOTEM_NE_BAR_BACK,
		InterfaceID.NightmareTotems.TOTEM_SW_BAR_BACK,
		InterfaceID.NightmareTotems.TOTEM_SE_BAR_BACK,
	};
	private static final int[] BAR_REMAINING = {
		InterfaceID.NightmareTotems.TOTEM_NW_BAR_REMAINING,
		InterfaceID.NightmareTotems.TOTEM_NE_BAR_REMAINING,
		InterfaceID.NightmareTotems.TOTEM_SW_BAR_REMAINING,
		InterfaceID.NightmareTotems.TOTEM_SE_BAR_REMAINING,
	};

	private final Client client;

	private final float[] fractions = new float[CORNERS];
	private final boolean[] full = new boolean[CORNERS];
	private final boolean[] known = new boolean[CORNERS];
	private final int[] maxes = new int[CORNERS];
	private final int[] currents = {UNCHANGED, UNCHANGED, UNCHANGED, UNCHANGED};
	private boolean shown;
	private boolean shownKnown;
	private boolean seen;
	private boolean hidden;

	@Inject
	PillarBars(Client client)
	{
		this.client = client;
	}

	void onScript(int scriptId, Object[] args)
	{
		if (scriptId == FADE_IN_SCRIPT || scriptId == FADE_OUT_SCRIPT)
		{
			shown = scriptId == FADE_IN_SCRIPT;
			shownKnown = true;
			return;
		}
		if (scriptId != UPDATE_SCRIPT || args == null || args.length < UPDATE_ARGS)
		{
			return;
		}

		for (int group = 0; group < CORNERS; group++)
		{
			final int first = 1 + group * ARGS_PER_CORNER;
			final Object back = args[first];
			final Object max = args[first + 2];
			final Object current = args[first + 3];
			if (!(back instanceof Integer) || !(max instanceof Integer) || !(current instanceof Integer))
			{
				continue;
			}

			final int corner = corner((Integer) back);
			if (corner >= 0)
			{
				apply(corner, (Integer) max, (Integer) current);
			}
		}
	}

	// Either value can come as unchanged, so the last one the script sent stands in for it.
	private void apply(int corner, int maxValue, int currentValue)
	{
		final int max = maxValue == UNCHANGED ? maxes[corner] : maxValue;
		if (max <= 0)
		{
			return;
		}
		maxes[corner] = max;
		final int current = currentValue == UNCHANGED ? currents[corner] : currentValue;
		if (current == UNCHANGED)
		{
			return;
		}
		currents[corner] = current;
		fractions[corner] = fraction(current, max);
		full[corner] = current >= max;
		known[corner] = true;
		log.debug("Pillar bar {}: {}/{}", corner, current, max);
	}

	void update(boolean replace)
	{
		final Widget totems = client.getWidget(InterfaceID.NightmareTotems.TOTEMS);
		if (totems == null)
		{
			hidden = false;
			clear();
			return;
		}

		if (!seen)
		{
			seed();
			seen = true;
		}

		if (replace)
		{
			if (!totems.isSelfHidden())
			{
				totems.setHidden(true);
				hidden = true;
			}
		}
		else
		{
			release();
		}
	}

	// Hidden widgets don't run their timers, so the widths are only read before the bars are first hidden.
	private void seed()
	{
		for (int corner = 0; corner < CORNERS; corner++)
		{
			final Widget back = client.getWidget(BAR_BACKS[corner]);
			final Widget remaining = client.getWidget(BAR_REMAINING[corner]);
			if (known[corner] || back == null || remaining == null)
			{
				continue;
			}
			fractions[corner] = seedFraction(remaining.getWidth(), back.getWidth());
			full[corner] = seedFull(remaining.getWidth(), back.getWidth());
		}

		if (!shownKnown)
		{
			final Widget border = client.getWidget(InterfaceID.NightmareTotems.TOTEMS_BORDER);
			shown = border != null && border.getOpacity() < TRANSPARENT;
		}
		log.debug("Pillar bars seeded: {} {} shown={}", Arrays.toString(fractions), Arrays.toString(full), shown);
	}

	private void release()
	{
		if (hidden)
		{
			final Widget totems = client.getWidget(InterfaceID.NightmareTotems.TOTEMS);
			if (totems != null)
			{
				totems.setHidden(false);
			}
		}
		hidden = false;
	}

	void reset()
	{
		release();
		clear();
	}

	private void clear()
	{
		Arrays.fill(fractions, 0f);
		Arrays.fill(full, false);
		Arrays.fill(known, false);
		Arrays.fill(maxes, 0);
		Arrays.fill(currents, UNCHANGED);
		shown = false;
		shownKnown = false;
		seen = false;
	}

	boolean isVisible()
	{
		return hidden && shown;
	}

	float fraction(int corner)
	{
		return fractions[corner];
	}

	boolean isFull(int corner)
	{
		return full[corner];
	}

	static int corner(int barBackId)
	{
		for (int corner = 0; corner < CORNERS; corner++)
		{
			if (BAR_BACKS[corner] == barBackId)
			{
				return corner;
			}
		}
		return -1;
	}

	static float fraction(int current, int max)
	{
		return clamp01(current / (float) max);
	}

	static float seedFraction(int remainingWidth, int backWidth)
	{
		return backWidth > 0 ? clamp01(remainingWidth / (float) backWidth) : 0f;
	}

	static boolean seedFull(int remainingWidth, int backWidth)
	{
		return backWidth > 0 && remainingWidth == backWidth;
	}

	boolean isShown()
	{
		return shown;
	}
}

package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.ColorUtil.brighten;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Paint;
import javax.inject.Inject;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

// Draws the game's pillar charge bars in the bar's style while this plugin hides the game's.
class PillarBarsOverlay extends Overlay
{
	private static final String[] LABELS = {"North West", "North East", "South West", "South East"};
	private static final float[] PREVIEW_FRACTIONS = {1f, 0.6f, 0.25f, 0f};
	private static final boolean[] PREVIEW_FULL = {true, false, false, false};

	static final int MIN_BAR_WIDTH = 64;
	static final int LABEL_PADDING = 4;
	static final int MIN_BAR_HEIGHT = 5;
	static final int MAX_BAR_HEIGHT = 9;
	static final int COLUMN_GAP = 6;
	static final int ROW_GAP = 3;
	static final int LABEL_GAP = 1;
	private static final float FULL_BRIGHTEN = 0.75f;

	// The game's own colors, used with the Oldschool theme.
	private static final Color FLAT_TRACK = new Color(0x2D2B00);
	private static final Color FLAT_FILL = new Color(0xDBD300);
	private static final Color FLAT_FULL = Color.WHITE;
	private static final Color FLAT_OUTLINE = new Color(0x191511);

	private final BossHealthBarConfig config;
	private final PillarBars pillarBars;
	private final BossHealthBarOverlay barOverlay;
	private final BarTextPainter textPainter;

	private final int[] labelWidths = new int[PillarBars.CORNERS];
	private FontMetrics labelMetrics;
	private int barWidth;
	private int labelHeight;

	private int trackPaintHeight = -1;
	private final Paint[] trackPaints = new Paint[2];

	private Color fullSource;
	private Color fullColor;

	@Inject
	private PillarBarsOverlay(BossHealthBarPlugin plugin, BossHealthBarConfig config, PillarBars pillarBars,
		BossHealthBarOverlay barOverlay, BarTextPainter textPainter)
	{
		super(plugin);
		this.config = config;
		this.pillarBars = pillarBars;
		this.barOverlay = barOverlay;
		this.textPainter = textPainter;

		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_SCENE);
		addMenuEntry(RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, BossHealthBarPlugin.NAME);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final boolean live = pillarBars.isVisible();
		if (!live && !barOverlay.isShowingPreview())
		{
			return null;
		}

		textPainter.updateFonts();
		final FontMetrics metrics = textPainter.hitpointsMetrics();
		if (metrics != labelMetrics)
		{
			measureLabels(metrics);
		}

		final int barHeight = barHeight(config.barHeight());
		final int cellHeight = cellHeight(labelHeight, barHeight);

		final ThemeColors colors = barOverlay.baseColors();
		final boolean flat = BarTheme.of(config).isFlat();
		final Color fill = flat ? FLAT_FILL : colors.getFillHigh();
		final Color full = flat ? FLAT_FULL : fullColor(fill);
		final Color outline = flat ? FLAT_OUTLINE : colors.getFrame();
		final Color labelColor = colors.getHitpointsText();
		updateTrackPaints(barHeight, cellHeight);

		textPainter.applyTextHints(graphics);
		for (int corner = 0; corner < PillarBars.CORNERS; corner++)
		{
			final int column = corner % 2;
			final int row = corner / 2;
			final int x = column * (barWidth + COLUMN_GAP);
			final int y = row * (cellHeight + ROW_GAP);
			textPainter.drawHitpointsStyleText(graphics, LABELS[corner], x + (barWidth - labelWidths[corner]) / 2,
				y + metrics.getAscent(), labelColor);

			final Paint track = flat ? FLAT_TRACK : colors.getTrack() != null ? colors.getTrack() : trackPaints[row];
			final float fraction = live ? pillarBars.fraction(corner) : PREVIEW_FRACTIONS[corner];
			final boolean isFull = live ? pillarBars.isFull(corner) : PREVIEW_FULL[corner];
			drawBar(graphics, x, y + labelHeight + LABEL_GAP, barHeight, fraction, isFull, track,
				isFull ? full : fill, outline);
		}

		return gridSize(barWidth, cellHeight);
	}

	private void drawBar(Graphics2D graphics, int x, int y, int height, float fraction, boolean isFull, Paint track,
		Color fill, Color outline)
	{
		final int innerWidth = barWidth - 2;
		graphics.setColor(outline);
		graphics.drawRect(x, y, barWidth - 1, height - 1);
		graphics.setPaint(track);
		graphics.fillRect(x + 1, y + 1, innerWidth, height - 2);
		final int filled = filledWidth(innerWidth, fraction, isFull);
		if (filled > 0)
		{
			graphics.setColor(fill);
			graphics.fillRect(x + 1, y + 1, filled, height - 2);
		}
	}

	private void measureLabels(FontMetrics metrics)
	{
		int widest = 0;
		for (int corner = 0; corner < PillarBars.CORNERS; corner++)
		{
			labelWidths[corner] = metrics.stringWidth(LABELS[corner]);
			widest = Math.max(widest, labelWidths[corner]);
		}
		barWidth = barWidth(widest);
		// One more for the text shadow.
		labelHeight = metrics.getAscent() + 1;
		labelMetrics = metrics;
		trackPaintHeight = -1;
	}

	private void updateTrackPaints(int barHeight, int cellHeight)
	{
		if (barHeight == trackPaintHeight)
		{
			return;
		}
		for (int row = 0; row < trackPaints.length; row++)
		{
			final int top = row * (cellHeight + ROW_GAP) + labelHeight + LABEL_GAP + 1;
			trackPaints[row] = new GradientPaint(0, top, BarPainter.TRACK_TOP, 0, top + barHeight - 2, BarPainter.TRACK_BOTTOM);
		}
		trackPaintHeight = barHeight;
	}

	private Color fullColor(Color fill)
	{
		if (fill != fullSource)
		{
			fullColor = brighten(fill, FULL_BRIGHTEN);
			fullSource = fill;
		}
		return fullColor;
	}

	static int barWidth(int widestLabel)
	{
		return Math.max(MIN_BAR_WIDTH, widestLabel + LABEL_PADDING);
	}

	static int barHeight(int configured)
	{
		return Math.max(MIN_BAR_HEIGHT, Math.min(MAX_BAR_HEIGHT, configured));
	}

	static int cellHeight(int labelHeight, int barHeight)
	{
		return labelHeight + LABEL_GAP + barHeight;
	}

	static Dimension gridSize(int barWidth, int cellHeight)
	{
		return new Dimension(barWidth * 2 + COLUMN_GAP, cellHeight * 2 + ROW_GAP);
	}

	static int filledWidth(int innerWidth, float fraction, boolean full)
	{
		return full ? innerWidth : Math.max(0, Math.min(innerWidth, Math.round(innerWidth * fraction)));
	}
}

package com.ghordrin.bosshealthbar;

import com.google.common.annotations.VisibleForTesting;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

// Reads the counts RuneLite's "Special Attack Counter" plugin shows in its info boxes, one per weapon.
@Slf4j
@Singleton
class SpecialAttackCounts
{
	private static final String PLUGIN_NAME = "Special Attack Counter";
	// InfoBox.getName() defaults to the plugin's class name and the info box's class name.
	@VisibleForTesting
	static final String BOX_NAME = "SpecialCounterPlugin_SpecialCounter";

	@Value
	static class Reading
	{
		BufferedImage image;
		String text;
		Color color;
	}

	private final BossHealthBarConfig config;
	private final PluginManager pluginManager;
	private final InfoBoxManager infoBoxManager;

	private Boolean pluginActive;
	private boolean available;
	private List<Reading> readings = Collections.emptyList();
	private boolean missedTick;

	@Inject
	SpecialAttackCounts(BossHealthBarConfig config, PluginManager pluginManager, InfoBoxManager infoBoxManager)
	{
		this.config = config;
		this.pluginManager = pluginManager;
		this.infoBoxManager = infoBoxManager;
	}

	void invalidatePlugin()
	{
		pluginActive = null;
	}

	void reset()
	{
		pluginActive = null;
		available = false;
		clear();
	}

	private void clear()
	{
		readings = Collections.emptyList();
		missedTick = false;
	}

	// Called each game tick, so the overlay doesn't go through the info boxes every frame.
	void update(Actor opponent)
	{
		if (pluginActive == null)
		{
			pluginActive = isPluginActive();
		}
		available = pluginActive && config.showSpecialAttackCounts();

		if (!available || opponent == null)
		{
			clear();
			return;
		}

		try
		{
			accept(find(infoBoxManager.getInfoBoxes()));
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't read Special Attack Counter info boxes", e);
			clear();
		}
	}

	// Their info boxes can be gone for a tick while they're rebuilt, so the last readings are kept for one tick.
	@VisibleForTesting
	void accept(List<Reading> found)
	{
		if (!found.isEmpty())
		{
			if (!found.equals(readings))
			{
				readings = found;
			}
			missedTick = false;
		}
		else if (!readings.isEmpty() && !missedTick)
		{
			missedTick = true;
		}
		else
		{
			clear();
		}
	}

	boolean isAvailable()
	{
		return available;
	}

	List<Reading> readings()
	{
		return readings;
	}

	private boolean isPluginActive()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (PLUGIN_NAME.equals(plugin.getName()))
			{
				return pluginManager.isPluginActive(plugin);
			}
		}
		return false;
	}

	@VisibleForTesting
	static List<Reading> find(List<InfoBox> infoBoxes)
	{
		List<Reading> found = null;
		for (InfoBox infoBox : infoBoxes)
		{
			if (!matches(infoBox))
			{
				continue;
			}
			final String text = infoBox.getText();
			if (text == null || text.isEmpty())
			{
				continue;
			}
			if (found == null)
			{
				found = new ArrayList<>();
			}
			found.add(new Reading(infoBox.getImage(), text, infoBox.getTextColor()));
		}
		return found != null ? Collections.unmodifiableList(found) : Collections.emptyList();
	}

	@VisibleForTesting
	static boolean matches(InfoBox infoBox)
	{
		return infoBox != null && BOX_NAME.equals(infoBox.getName());
	}
}

