package com.ghordrin.bosshealthbar;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;

@Slf4j
@Singleton
class SuperiorTracker
{
	private static final String SPAWN_MESSAGE = "A superior foe has appeared";
	private static final int MATCH_TICKS = 2;
	private static final int SEARCH_DISTANCE = 15;

	@Value
	static class Spawn<T>
	{
		T npc;
		boolean knownSuperior;
		boolean eligible;
	}

	@Value
	static class Match<T>
	{
		boolean decided;
		T superior;
	}

	private final Client client;
	private final Map<NPC, Integer> recentSpawnTicks = new HashMap<>();
	private final Set<NPC> superiors = new HashSet<>();
	private int messageTick = -1;

	@Inject
	SuperiorTracker(Client client)
	{
		this.client = client;
	}

	boolean isSuperior(Actor actor)
	{
		return actor instanceof NPC
			&& (superiors.contains(actor) || SuperiorIds.contains(NpcUtil.currentId((NPC) actor)));
	}

	void onNpcSpawned(NPC npc)
	{
		recentSpawnTicks.put(npc, client.getTickCount());
	}

	void onNpcDespawned(NPC npc)
	{
		recentSpawnTicks.remove(npc);
		superiors.remove(npc);
	}

	void onChatMessage(ChatMessage event)
	{
		if ((event.getType() == ChatMessageType.GAMEMESSAGE || event.getType() == ChatMessageType.SPAM)
			&& event.getMessage().contains(SPAWN_MESSAGE))
		{
			messageTick = client.getTickCount();
			log.debug("Superior spawn message on tick {}", messageTick);
		}
	}

	// Superiors in SuperiorIds are known by their ID. For any other, the chat message is matched to the
	// one attackable NPC that spawned near the player around the same tick, in either order.
	void onGameTick()
	{
		final int tick = client.getTickCount();
		recentSpawnTicks.values().removeIf(spawnTick -> tick - spawnTick > MATCH_TICKS);

		if (messageTick == -1)
		{
			return;
		}

		final Player player = client.getLocalPlayer();
		final List<Spawn<NPC>> spawns = new ArrayList<>();
		for (NPC npc : recentSpawnTicks.keySet())
		{
			final boolean known = SuperiorIds.contains(NpcUtil.currentId(npc));
			spawns.add(new Spawn<>(npc, known, !known && player != null && isEligible(npc, player)));
		}

		final Match<NPC> match = match(spawns);
		if (match.isDecided())
		{
			messageTick = -1;
			if (match.getSuperior() != null)
			{
				superiors.add(match.getSuperior());
				log.debug("Marked {} as a superior", match.getSuperior().getName());
			}
		}
		else if (tick - messageTick >= MATCH_TICKS)
		{
			messageTick = -1;
			log.debug("No spawned NPC found for the superior spawn message");
		}
	}

	private boolean isEligible(NPC npc, Player player)
	{
		return !npc.isDead() && !superiors.contains(npc) && NpcUtil.isAttackable(npc)
			&& npc.getWorldLocation().distanceTo(player.getWorldLocation()) <= SEARCH_DISTANCE;
	}

	// A known superior takes the message. Otherwise a single eligible spawn is marked; with several it
	// would be a guess, so none is.
	static <T> Match<T> match(List<Spawn<T>> spawns)
	{
		T only = null;
		int eligible = 0;
		for (Spawn<T> spawn : spawns)
		{
			if (spawn.isKnownSuperior())
			{
				return new Match<>(true, null);
			}
			if (spawn.isEligible())
			{
				only = spawn.getNpc();
				eligible++;
			}
		}
		if (eligible > 1)
		{
			log.debug("{} NPCs spawned with the superior spawn message, marking none", eligible);
			return new Match<>(true, null);
		}
		return new Match<>(eligible == 1, only);
	}

	void reset()
	{
		recentSpawnTicks.clear();
		superiors.clear();
		messageTick = -1;
	}
}

package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.ColorUtil.brighten;
import java.awt.Color;
import lombok.Builder;
import lombok.Value;

@Value
@Builder(toBuilder = true)
class ThemeColors
{
	static final Color DEFAULT_TEXT = new Color(0xE8E2D4);
	static final Color DEFAULT_HITPOINTS_TEXT = new Color(0xC8C0B0);
	private static final float MIN_TRAIL_CONTRAST = 1.5f;

	Color fillHigh;
	Color fillLow;
	Color trail;
	// Plain color behind the fill. Null keeps the default dark track.
	Color track;

	Color frame;

	Color text;
	Color levelText;
	Color hitpointsText;
	Color defeatedText;

	static ThemeColors of(Color fillHigh, Color fillLow, Color frame, Color trail)
	{
		return ThemeColors.builder()
			.fillHigh(fillHigh)
			.fillLow(fillLow)
			.trail(trail)
			.frame(frame)
			.text(DEFAULT_TEXT)
			.levelText(brighten(frame, 0.35f))
			.hitpointsText(DEFAULT_HITPOINTS_TEXT)
			.defeatedText(brighten(frame, 0.45f))
			.build();
	}

	// Follows how the built-in themes relate their colors: a darker fill at low health that leans red
	// for warm colors, a pale trail of the same hue, and a dark frame tinted with it.
	static ThemeColors fromBase(Color base)
	{
		final float[] hsb = Color.RGBtoHSB(base.getRed(), base.getGreen(), base.getBlue(), null);
		final float hue = hsb[0];
		final float saturation = hsb[1];
		final boolean grey = saturation < 0.12f;
		final boolean warm = hue >= 20f / 360f && hue <= 80f / 360f;

		final Color fillLow = Color.getHSBColor(hue + (warm ? -10f : 5f) / 360f,
			grey ? saturation : Math.min(1f, saturation * 1.03f + (saturation < 0.5f ? 0.14f : 0f)),
			hsb[2] * 0.68f);
		Color trail = Color.getHSBColor(hue, Math.min(0.5f, saturation * 0.4f), 0.97f);
		if (contrast(trail, base) < MIN_TRAIL_CONTRAST)
		{
			trail = Color.getHSBColor(hue + 0.5f, 0.45f, 0.9f);
		}
		final Color frame = Color.getHSBColor(hue, grey ? 0.06f : 0.2f, 0.45f);
		return of(base, fillLow, frame, trail);
	}

	static float contrast(Color a, Color b)
	{
		final float la = luminance(a);
		final float lb = luminance(b);
		return (Math.max(la, lb) + 0.05f) / (Math.min(la, lb) + 0.05f);
	}

	private static float luminance(Color c)
	{
		return 0.2126f * linear(c.getRed()) + 0.7152f * linear(c.getGreen()) + 0.0722f * linear(c.getBlue());
	}

	private static float linear(int channel)
	{
		final float c = channel / 255f;
		return c <= 0.03928f ? c / 12.92f : (float) Math.pow((c + 0.055f) / 1.055f, 2.4f);
	}
}

package com.ghordrin.bosshealthbar;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

@Singleton
class TobBossBar
{
	// Values of TOB_CLIENT_WAVEPROGRESS_TYPE. Other values show room progress instead of health.
	private static final int PROGRESS_NONE = 0;
	private static final int PROGRESS_BOSS_HEALTH = 1;
	private static final int SEARCH_DISTANCE = 32;

	private final Client client;

	private boolean hidden;
	private NPC boss;
	private boolean searchNeeded = true;

	@Inject
	TobBossBar(Client client)
	{
		this.client = client;
	}

	// The Theatre of Blood bar doesn't say which NPC it belongs to, so this takes the highest level
	// attackable NPC nearby. Cached until a stronger NPC spawns or the boss changes or despawns.
	NPC findBoss()
	{
		if (client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_TYPE) != PROGRESS_BOSS_HEALTH
			|| client.getWidget(InterfaceID.TobHud.PROGRESS_CONTAINER) == null)
		{
			boss = null;
			searchNeeded = true;
			return null;
		}

		if (!searchNeeded)
		{
			return boss;
		}

		searchNeeded = false;
		boss = null;
		final Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			if (npc.isDead() || !NpcUtil.isAttackable(npc)
				|| npc.getWorldLocation().distanceTo(player.getWorldLocation()) > SEARCH_DISTANCE)
			{
				continue;
			}

			if (boss == null
				|| npc.getCombatLevel() > boss.getCombatLevel()
				|| (npc.getCombatLevel() == boss.getCombatLevel() && NpcUtil.size(npc) > NpcUtil.size(boss)))
			{
				boss = npc;
			}
		}
		return boss;
	}

	// The last boss found, without searching again.
	NPC cachedBoss()
	{
		return boss;
	}

	boolean isTracking(Actor actor)
	{
		return actor != null && actor == findBoss();
	}

	void onNpcSpawned(NPC npc)
	{
		if (mayBeBoss(npc))
		{
			searchNeeded = true;
		}
	}

	void onNpcChanged(NPC npc)
	{
		if (npc == boss || mayBeBoss(npc))
		{
			searchNeeded = true;
		}
	}

	void onNpcDespawned(NPC npc)
	{
		if (npc == boss)
		{
			boss = null;
			searchNeeded = true;
		}
	}

	void onGameTick()
	{
		if (boss == null)
		{
			// The room's boss may only have come into range as the player walked in.
			searchNeeded = true;
		}
	}

	private boolean mayBeBoss(NPC npc)
	{
		return boss == null || npc.getCombatLevel() >= boss.getCombatLevel();
	}

	void update(Actor opponent, boolean replaceEnabled, boolean opponentGetsBar)
	{
		final Widget bar = client.getWidget(InterfaceID.TobHud.PROGRESS_CONTAINER);
		if (bar == null)
		{
			hidden = false;
			return;
		}

		if (replaceEnabled && isTracking(opponent) && opponentGetsBar)
		{
			if (!bar.isSelfHidden())
			{
				bar.setHidden(true);
				hidden = true;
			}
		}
		else
		{
			restore();
		}
	}

	void restore()
	{
		if (!hidden)
		{
			return;
		}

		final Widget bar = client.getWidget(InterfaceID.TobHud.PROGRESS_CONTAINER);
		if (bar != null && client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_TYPE) != PROGRESS_NONE)
		{
			bar.setHidden(false);
		}
		hidden = false;
	}

	void reset()
	{
		hidden = false;
		boss = null;
		searchNeeded = true;
	}

	int maxHealth()
	{
		return client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_MAX);
	}

	int health(int maxHealth)
	{
		return Math.max(0, Math.min(maxHealth, client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_VAL)));
	}
}

package com.ghordrin.bosshealthbar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class BarAnimationTest
{
	@Test
	public void lostHealthLeavesATrail()
	{
		final BarAnimation animation = new BarAnimation();
		animation.tick(1f, 1f, true, System.currentTimeMillis());
		animation.tick(0.4f, 1f, true, System.currentTimeMillis());

		assertEquals(0.4f, animation.getDisplayedFraction(), 0.001f);
		assertTrue(animation.getTrailFraction() > 0.9f);
	}

	@Test
	public void retargetJumpsToTheNewHealthWithoutATrail()
	{
		final BarAnimation animation = new BarAnimation();
		animation.tick(0.4f, 1f, true, System.currentTimeMillis());
		animation.retarget();
		animation.tick(1f, 1f, true, System.currentTimeMillis());

		assertEquals(1f, animation.getDisplayedFraction(), 0.001f);
		assertEquals(1f, animation.getTrailFraction(), 0.001f);

		animation.retarget();
		animation.tick(0.2f, 1f, true, System.currentTimeMillis());

		assertEquals(0.2f, animation.getDisplayedFraction(), 0.001f);
		assertEquals(0.2f, animation.getTrailFraction(), 0.001f);
	}

	@Test
	public void defeatEndsAfterTheFadeOrTheBurn()
	{
		final long hold = BarAnimation.DEFEAT_HOLD.toNanos();
		for (boolean burnAway : new boolean[]{false, true})
		{
			final BarAnimation animation = new BarAnimation();
			animation.startDefeat(1_000L);
			final long end = 1_000L + hold + (burnAway ? BarEffects.BURN_DURATION : BarAnimation.DEFEAT_FADE).toNanos();
			assertEquals(1f, animation.defeatOpacity(1_000L + hold, burnAway), 0.001f);
			assertTrue(animation.defeatOpacity(end - 1_000_000L, burnAway) >= 0f);
			assertEquals(-1f, animation.defeatOpacity(end, burnAway), 0f);
		}
	}

	@Test
	public void burnAwayFadesOnlyTheText()
	{
		final BarAnimation animation = new BarAnimation();
		animation.startDefeat(1_000L);
		final long halfway = 1_000L + BarAnimation.DEFEAT_HOLD.toNanos() + BarAnimation.DEFEAT_FADE.toNanos() / 2;

		assertEquals(0.5f, animation.defeatOpacity(halfway, false), 0.01f);
		assertEquals(1f, animation.defeatTextOpacity(halfway, false), 0f);
		assertEquals(1f, animation.defeatOpacity(halfway, true), 0f);
		assertEquals(0.5f, animation.defeatTextOpacity(halfway, true), 0.01f);
		assertEquals(BarAnimation.DEFEAT_FADE.toMillis() / 2, animation.defeatEffectMillis(halfway));
	}

	@Test
	public void noDefeatMeansNoDefeatEffect()
	{
		final BarAnimation animation = new BarAnimation();
		assertEquals(1f, animation.defeatOpacity(5_000_000_000L, true), 0f);
		assertEquals(1f, animation.defeatTextOpacity(5_000_000_000L, true), 0f);
		assertTrue(animation.defeatEffectMillis(5_000_000_000L) < 0);
	}
}

package com.ghordrin.bosshealthbar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class BarEffectsTest
{
	@Test
	public void randomIsRepeatableAndInRange()
	{
		for (int i = 0; i < 1000; i++)
		{
			final float value = BarEffects.random(42, i);
			assertTrue(value >= 0f && value < 1f);
			assertEquals(value, BarEffects.random(42, i), 0f);
		}
		assertTrue(BarEffects.random(1, 0) != BarEffects.random(2, 0));
	}

	@Test
	public void burnSparksOnlyFlyWhileTheBarBurns()
	{
		final BarEffects.Particle spark = new BarEffects.Particle();
		for (int i = 0; i < BarEffects.BURN_SPARK_COUNT; i++)
		{
			assertFalse(BarEffects.burnSpark(i, -1, spark));
			assertFalse(BarEffects.burnSpark(i, BarEffects.BURN_DURATION.toMillis() + 1000, spark));
		}

		int thrown = 0;
		for (int i = 0; i < BarEffects.BURN_SPARK_COUNT; i++)
		{
			for (long millis = 0; millis <= BarEffects.BURN_DURATION.toMillis(); millis += 25)
			{
				if (BarEffects.burnSpark(i, millis, spark))
				{
					thrown++;
					assertTrue(spark.along >= 0f && spark.along <= 1f);
					// A spark starts where the edge was when it was thrown, so never ahead of the edge.
					assertTrue(spark.along <= BarEffects.burnProgress(millis) + 0.0001f);
					assertTrue(spark.y <= 0f);
				}
			}
		}
		assertTrue(thrown > 0);
	}

	@Test
	public void burnRunsTheWholeBar()
	{
		assertEquals(0f, BarEffects.burnProgress(-100), 0f);
		assertEquals(0f, BarEffects.burnProgress(0), 0f);
		assertEquals(1f, BarEffects.burnProgress(BarEffects.BURN_DURATION.toMillis()), 0f);
		assertTrue(BarEffects.burnProgress(400) < BarEffects.burnProgress(800));
	}

	@Test
	public void sparkColorsFadeOut()
	{
		assertEquals(255, BarEffects.sparkColor(0f).getAlpha());
		assertEquals(0, BarEffects.sparkColor(1f).getAlpha());
		assertTrue(BarEffects.sparkColor(0.5f).getAlpha() < BarEffects.sparkColor(0.1f).getAlpha());
	}
}

package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.BarPainter.capRise;
import static com.ghordrin.bosshealthbar.BarPainter.capScale;
import static com.ghordrin.bosshealthbar.BarPainter.capWidth;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class BarEndsTest
{
	@Test
	public void subtleEndsAtTheReferenceHeight()
	{
		assertEquals(5, capWidth(8, false, BarEnds.SUBTLE));
		assertEquals(4, capRise(8, false, BarEnds.SUBTLE));
	}

	@Test
	public void subtleEndsLeaveTheBarWiderThanClassic()
	{
		for (int height = 4; height <= 24; height++)
		{
			assertTrue(capWidth(height, false, BarEnds.SUBTLE) < capWidth(height, false, BarEnds.CLASSIC));
		}
	}

	@Test
	public void subtleEndsHaveRoomForThePointAndTips()
	{
		for (int height = 4; height <= 24; height++)
		{
			final float s = capScale(height);
			// The point plus half the outline stroke, and the curled tip above the frame line plus half the outline.
			assertTrue(capWidth(height, false, BarEnds.SUBTLE) >= 3.6f * s + 1.2f * s);
			assertTrue(capRise(height, false, BarEnds.SUBTLE) >= 2.4f * s + 1.2f * s - 0.5f);
		}
	}

	@Test
	public void subtleEndsGrowWithBarHeight()
	{
		assertTrue(capWidth(24, false, BarEnds.SUBTLE) > capWidth(8, false, BarEnds.SUBTLE));
		assertTrue(capRise(24, false, BarEnds.SUBTLE) > capRise(8, false, BarEnds.SUBTLE));
	}

	@Test
	public void labelsMatchTheDropdown()
	{
		assertEquals("Classic", BarEnds.CLASSIC.toString());
		assertEquals("Subtle", BarEnds.SUBTLE.toString());
	}
}

package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.BarLayout.NOT_PLACED;
import static com.ghordrin.bosshealthbar.BarLayout.Spot.CENTER;
import static com.ghordrin.bosshealthbar.BarLayout.Spot.LEFT;
import static com.ghordrin.bosshealthbar.BarLayout.Spot.RIGHT;
import static com.ghordrin.bosshealthbar.BarTextPainter.DAMAGE_NUMBER;
import static com.ghordrin.bosshealthbar.BarTextPainter.DRAIN_CAP;
import static com.ghordrin.bosshealthbar.BarTextPainter.FIGHT_TIMER;
import static com.ghordrin.bosshealthbar.BarTextPainter.HITPOINTS;
import static com.ghordrin.bosshealthbar.BarTextPainter.ITEM_COUNT;
import static com.ghordrin.bosshealthbar.BarTextPainter.KILL_COUNT;
import static com.ghordrin.bosshealthbar.BarTextPainter.LEVEL_GAP;
import static com.ghordrin.bosshealthbar.BarTextPainter.MAGIC_DEFENCE;
import static com.ghordrin.bosshealthbar.BarTextPainter.NAME;
import static com.ghordrin.bosshealthbar.BarTextPainter.PARTY_DEFENCE;
import static com.ghordrin.bosshealthbar.BarTextPainter.SPECIAL_ATTACKS;
import static com.ghordrin.bosshealthbar.BarTextPainter.TEXT_INSET;
import static com.ghordrin.bosshealthbar.BarTextPainter.WEAKNESS;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import org.junit.Test;

public class BarLayoutTest
{
	private static final int WIDTH = 220;
	private static final int LEFT_EDGE = 10;
	private static final int RIGHT_EDGE = 210;
	private static final int GAP = 12;

	private final BarLayout layout = new BarLayout(ITEM_COUNT);

	private void layOut()
	{
		layout.layout(WIDTH, LEFT_EDGE, RIGHT_EDGE, GAP);
	}

	@Test
	public void leftItemsFillFromTheLeftEdgeInImportanceOrder()
	{
		layout.add(WEAKNESS, LEFT, 30);
		layout.add(KILL_COUNT, LEFT, 10);
		layout.add(PARTY_DEFENCE, LEFT, 20);
		layOut();

		assertEquals(10, layout.x(KILL_COUNT));
		assertEquals(32, layout.x(PARTY_DEFENCE));
		assertEquals(64, layout.x(WEAKNESS));
	}

	@Test
	public void rightItemsFillFromTheRightEdgeWithTheMostImportantAtTheEdge()
	{
		layout.add(NAME, RIGHT, 50);
		layout.add(DAMAGE_NUMBER, RIGHT, 30);
		layOut();

		assertEquals(160, layout.x(NAME));
		assertEquals(118, layout.x(DAMAGE_NUMBER));
	}

	@Test
	public void centreItemsAreCentredOnTheBarAndReadInImportanceOrder()
	{
		layout.add(KILL_COUNT, CENTER, 30);
		layout.add(HITPOINTS, CENTER, 20);
		layOut();

		// The group is 20 + 12 + 30 = 62 wide.
		assertEquals(79, layout.x(HITPOINTS));
		assertEquals(111, layout.x(KILL_COUNT));
	}

	@Test
	public void onceAnItemDoesNotFitTheRestOfItsSpotIsLeftOut()
	{
		layout.add(KILL_COUNT, LEFT, 100);
		layout.add(PARTY_DEFENCE, LEFT, 150);
		layout.add(SPECIAL_ATTACKS, LEFT, 10);
		layout.add(WEAKNESS, RIGHT, 10);
		layOut();

		assertEquals(10, layout.x(KILL_COUNT));
		assertEquals(NOT_PLACED, layout.x(PARTY_DEFENCE));
		assertEquals(NOT_PLACED, layout.x(SPECIAL_ATTACKS));
		// Other spots carry on.
		assertEquals(200, layout.x(WEAKNESS));
	}

	@Test
	public void anItemThatOnlyPartlyFitsIsLeftOutWhole()
	{
		layout.add(SPECIAL_ATTACKS, LEFT, RIGHT_EDGE - LEFT_EDGE + 1);
		layOut();

		assertEquals(NOT_PLACED, layout.x(SPECIAL_ATTACKS));
		assertEquals(0, layout.room(SPECIAL_ATTACKS));
	}

	@Test
	public void moreImportantItemsGetTheSpaceFirst()
	{
		layout.add(HITPOINTS, LEFT, 150);
		layout.add(DAMAGE_NUMBER, RIGHT, 60);
		layout.add(KILL_COUNT, RIGHT, 5);
		layOut();

		assertEquals(10, layout.x(HITPOINTS));
		assertEquals(NOT_PLACED, layout.x(DAMAGE_NUMBER));
		assertEquals(NOT_PLACED, layout.x(KILL_COUNT));
	}

	@Test
	public void itemsKeepTheGapToTheOtherSide()
	{
		layout.add(HITPOINTS, RIGHT, 100);
		layout.add(KILL_COUNT, LEFT, 88);
		layout.add(PARTY_DEFENCE, LEFT, 0);
		layOut();

		// 10 + 88 + 12 == 110, the hitpoints' x.
		assertEquals(10, layout.x(KILL_COUNT));
		assertEquals(NOT_PLACED, layout.x(PARTY_DEFENCE));
	}

	@Test
	public void theCentreGroupDropsItsLaterItemsWhenTheyWouldHitTheSides()
	{
		layout.add(HITPOINTS, LEFT, 60);
		layout.add(DAMAGE_NUMBER, CENTER, 20);
		layout.add(KILL_COUNT, CENTER, 40);
		layout.add(PARTY_DEFENCE, CENTER, 10);
		layout.add(SPECIAL_ATTACKS, RIGHT, 100);
		layOut();

		assertEquals(10, layout.x(HITPOINTS));
		assertEquals(100, layout.x(DAMAGE_NUMBER));
		// With the kill count the group would start at 74, inside the hitpoints' gap.
		assertEquals(NOT_PLACED, layout.x(KILL_COUNT));
		// It would fit on its own, but nothing moves into an earlier item's place.
		assertEquals(NOT_PLACED, layout.x(PARTY_DEFENCE));
		// Side items placed later keep clear of the centre group.
		assertEquals(NOT_PLACED, layout.x(SPECIAL_ATTACKS));
	}

	@Test
	public void sideItemsPlacedAfterTheCentreGroupStopAtIt()
	{
		layout.add(HITPOINTS, CENTER, 40);
		layout.add(KILL_COUNT, LEFT, 68);
		layout.add(PARTY_DEFENCE, RIGHT, 68);
		layout.add(WEAKNESS, RIGHT, 1);
		layOut();

		assertEquals(90, layout.x(HITPOINTS));
		assertEquals(10, layout.x(KILL_COUNT));
		assertEquals(142, layout.x(PARTY_DEFENCE));
		assertEquals(NOT_PLACED, layout.x(WEAKNESS));
	}

	@Test
	public void aKeptItemIsPlacedEvenWhenItDoesNotFit()
	{
		layout.addKept(NAME, LEFT, 500);
		layOut();

		assertEquals(10, layout.x(NAME));
		assertEquals(0, layout.room(NAME));
	}

	@Test
	public void theNameGetsTheRoomLeftBeforeItemsInOtherSpots()
	{
		layout.addKept(NAME, LEFT, 30);
		layout.add(DAMAGE_NUMBER, RIGHT, 40);
		layOut();

		assertEquals(170, layout.x(DAMAGE_NUMBER));
		assertEquals(170 - GAP - 10 - 30, layout.room(NAME));
	}

	@Test
	public void laterItemsInTheNamesSpotMoveOutAsTheNameGrows()
	{
		layout.addKept(NAME, LEFT, 30);
		layout.add(KILL_COUNT, LEFT, 20);
		layOut();

		final int room = layout.room(NAME);
		assertEquals(RIGHT_EDGE - (10 + 30 + GAP + 20), room);

		layout.setWidth(NAME, 30 + room);
		layOut();
		assertEquals(10, layout.x(NAME));
		assertEquals(RIGHT_EDGE - 20, layout.x(KILL_COUNT));
	}

	@Test
	public void aNameOnTheRightGrowsLeftwardsAndPushesTheDamageNumberAlong()
	{
		layout.addKept(NAME, RIGHT, 30);
		layout.add(DAMAGE_NUMBER, RIGHT, 40);
		layOut();

		assertEquals(180, layout.x(NAME));
		assertEquals(128, layout.x(DAMAGE_NUMBER));
		final int room = layout.room(NAME);
		assertEquals(128 - LEFT_EDGE, room);

		layout.setWidth(NAME, 30 + room);
		layOut();
		assertEquals(RIGHT_EDGE - 30 - room, layout.x(NAME));
		assertEquals(LEFT_EDGE, layout.x(DAMAGE_NUMBER));
	}

	@Test
	public void aCentredNameGrowsEvenlyUpToTheCloserSide()
	{
		layout.addKept(NAME, CENTER, 20);
		layout.add(KILL_COUNT, LEFT, 50);
		layOut();

		final int room = layout.room(NAME);
		// The kill count ends at 60, so the name can start at 72 and, centred, be 220 - 2 * 72 = 76 wide.
		assertEquals(76 - 20, room);

		layout.setWidth(NAME, 20 + room);
		layOut();
		assertEquals(72, layout.x(NAME));
		assertEquals(10, layout.x(KILL_COUNT));
	}

	@Test
	public void roomNeverGoesNegative()
	{
		layout.addKept(NAME, LEFT, 300);
		layout.add(DAMAGE_NUMBER, RIGHT, 40);
		layOut();

		assertEquals(0, layout.room(NAME));
	}

	@Test
	public void damageNumberSitsAgainstItsSpotsSide()
	{
		assertEquals(100, BarTextPainter.damageNumberX(LEFT, 100, 40, 20));
		assertEquals(110, BarTextPainter.damageNumberX(CENTER, 100, 40, 20));
		assertEquals(120, BarTextPainter.damageNumberX(RIGHT, 100, 40, 20));
	}

	@Test
	public void positionsDefaultToTheClassicLayout()
	{
		final BossHealthBarConfig defaults = new BossHealthBarConfig()
		{
		};
		assertEquals(BarPosition.TOP_LEFT, defaults.namePosition());
		assertEquals(BarPosition.TOP_RIGHT, defaults.damageNumberPosition());
		assertEquals(BarPosition.BOTTOM_RIGHT, defaults.hitpointsPosition());
		assertEquals(BarPosition.BOTTOM_LEFT, defaults.killCountPosition());
		assertEquals(BarPosition.BOTTOM_LEFT, defaults.partyDefencePosition());
		assertEquals(BarPosition.BOTTOM_LEFT, defaults.specialAttackCountsPosition());
		assertEquals(BarPosition.BOTTOM_LEFT, defaults.weaknessPosition());
		assertEquals(BarPosition.BOTTOM_LEFT, defaults.drainCapPosition());
		assertEquals(BarPosition.TOP_CENTER, defaults.fightTimerPosition());
		assertTrue(defaults.namePosition().isTop());
		assertFalse(defaults.hitpointsPosition().isTop());
	}

	// The checks below lay out the default positions the way the painter does and compare them with how the
	// header and footer were placed before positions could be chosen.
	private static final int BAR_WIDTH = 600;
	private static final int CAP_WIDTH = 9;
	private static final int BAR_LEFT = CAP_WIDTH + TEXT_INSET;
	private static final int BAR_RIGHT = BAR_WIDTH - CAP_WIDTH - TEXT_INSET;

	private static void layOutDefaults(BarLayout layout)
	{
		layout.layout(BAR_WIDTH, BAR_LEFT, BAR_RIGHT, LEVEL_GAP);
	}

	@Test
	public void defaultHeaderMatchesTheClassicLayout()
	{
		final BossHealthBarConfig defaults = new BossHealthBarConfig()
		{
		};
		final int iconAdvance = 18;
		final int levelWidth = LEVEL_GAP + 30;
		final int ellipsisWidth = 14;
		final int sizingWidth = 36;
		final int nameWidth = 120;

		final BarLayout header = new BarLayout(ITEM_COUNT);
		header.addKept(NAME, defaults.namePosition().getSpot(), iconAdvance + levelWidth + ellipsisWidth);
		header.add(DAMAGE_NUMBER, defaults.damageNumberPosition().getSpot(), sizingWidth);
		layOutDefaults(header);

		final int nameMaxWidth = ellipsisWidth + header.room(NAME);
		final int classicNameMaxWidth = BAR_RIGHT - (BAR_LEFT + iconAdvance) - (sizingWidth + LEVEL_GAP) - levelWidth;
		assertEquals(classicNameMaxWidth, nameMaxWidth);

		header.setWidth(NAME, iconAdvance + nameWidth + levelWidth);
		layOutDefaults(header);
		assertEquals(BAR_LEFT, header.x(NAME));
		assertEquals(BAR_RIGHT - 25, BarTextPainter.damageNumberX(header.spot(DAMAGE_NUMBER), header.x(DAMAGE_NUMBER),
			header.width(DAMAGE_NUMBER), 25));
	}

	@Test
	public void defaultFightTimerSitsCentredAboveTheBarAndLimitsTheName()
	{
		final BossHealthBarConfig defaults = new BossHealthBarConfig()
		{
		};
		final int ellipsisWidth = 14;
		final int timerWidth = 30;

		final BarLayout header = new BarLayout(ITEM_COUNT);
		header.addKept(NAME, defaults.namePosition().getSpot(), ellipsisWidth);
		header.add(DAMAGE_NUMBER, defaults.damageNumberPosition().getSpot(), 36);
		header.add(FIGHT_TIMER, defaults.fightTimerPosition().getSpot(), timerWidth);
		layOutDefaults(header);

		final int timerX = (BAR_WIDTH - timerWidth) / 2;
		assertEquals(timerX, header.x(FIGHT_TIMER));
		assertEquals(timerX - LEVEL_GAP - BAR_LEFT - ellipsisWidth, header.room(NAME));
	}

	@Test
	public void defaultFooterMatchesTheClassicLayout()
	{
		final BossHealthBarConfig defaults = new BossHealthBarConfig()
		{
		};
		final int hitpointsWidth = 80;
		final int[] widths = {0, hitpointsWidth, 0, 0, 40, 50, 45, 70, 35, 30};

		final BarLayout footer = new BarLayout(ITEM_COUNT);
		footer.add(HITPOINTS, defaults.hitpointsPosition().getSpot(), hitpointsWidth);
		footer.add(KILL_COUNT, defaults.killCountPosition().getSpot(), widths[KILL_COUNT]);
		footer.add(PARTY_DEFENCE, defaults.partyDefencePosition().getSpot(), widths[PARTY_DEFENCE]);
		footer.add(MAGIC_DEFENCE, defaults.partyDefencePosition().getSpot(), widths[MAGIC_DEFENCE]);
		footer.add(SPECIAL_ATTACKS, defaults.specialAttackCountsPosition().getSpot(), widths[SPECIAL_ATTACKS]);
		footer.add(WEAKNESS, defaults.weaknessPosition().getSpot(), widths[WEAKNESS]);
		footer.add(DRAIN_CAP, defaults.drainCapPosition().getSpot(), widths[DRAIN_CAP]);
		layOutDefaults(footer);

		assertEquals(BAR_RIGHT - hitpointsWidth, footer.x(HITPOINTS));
		int left = BAR_LEFT;
		for (int item = KILL_COUNT; item <= DRAIN_CAP; item++)
		{
			assertEquals(left, footer.x(item));
			left += widths[item] + LEVEL_GAP;
		}
	}

	@Test
	public void defaultFooterKeepsTheHitpointsSlotAndCentresDefeated()
	{
		final int defeatedWidth = 51;
		final BarLayout footer = new BarLayout(ITEM_COUNT);
		footer.add(HITPOINTS, BarLayout.Spot.RIGHT, 80);
		footer.add(KILL_COUNT, BarLayout.Spot.LEFT, 40);
		footer.add(PARTY_DEFENCE, BarLayout.Spot.LEFT, 50);
		layOutDefaults(footer);

		assertEquals(BAR_RIGHT - 80, footer.x(HITPOINTS));
		assertEquals(BAR_LEFT, footer.x(KILL_COUNT));
		assertEquals(BAR_LEFT + 40 + LEVEL_GAP, footer.x(PARTY_DEFENCE));
		assertEquals(Math.floorDiv(BAR_WIDTH - defeatedWidth, 2), footer.centredX(defeatedWidth, HITPOINTS));
	}

	@Test
	public void defeatedIsLeftOutWhenTheLeftItemsReachTheMiddle()
	{
		final BarLayout footer = new BarLayout(ITEM_COUNT);
		footer.add(HITPOINTS, BarLayout.Spot.RIGHT, 80);
		footer.add(KILL_COUNT, BarLayout.Spot.LEFT, 260);
		layOutDefaults(footer);

		// The kill count ends at 271, within a gap of where "Defeated" would start (274).
		assertEquals(BAR_LEFT, footer.x(KILL_COUNT));
		assertEquals(NOT_PLACED, footer.centredX(51, HITPOINTS));
	}

	@Test
	public void defeatedIsLeftOutWhenAnotherItemIsInTheCentreOfItsRow()
	{
		final BarLayout footer = new BarLayout(ITEM_COUNT);
		footer.add(HITPOINTS, BarLayout.Spot.RIGHT, 80);
		footer.add(KILL_COUNT, CENTER, 40);
		layOutDefaults(footer);

		assertEquals(280, footer.x(KILL_COUNT));
		assertEquals(NOT_PLACED, footer.centredX(51, HITPOINTS));
	}

	@Test
	public void defeatedShowsWithHitpointsAndKillCountBothOnTheRight()
	{
		final BarLayout footer = new BarLayout(ITEM_COUNT);
		footer.add(HITPOINTS, BarLayout.Spot.RIGHT, 80);
		footer.add(KILL_COUNT, BarLayout.Spot.RIGHT, 40);
		layOutDefaults(footer);

		// The kill count stays where it was while the opponent was alive.
		assertEquals(BAR_RIGHT - 80, footer.x(HITPOINTS));
		assertEquals(BAR_RIGHT - 80 - LEVEL_GAP - 40, footer.x(KILL_COUNT));
		assertEquals(274, footer.centredX(51, HITPOINTS));
	}

	@Test
	public void defeatedReplacesCentredHitpointsRatherThanAvoidingThem()
	{
		final BarLayout footer = new BarLayout(ITEM_COUNT);
		footer.add(HITPOINTS, CENTER, 80);
		layOutDefaults(footer);

		assertEquals(260, footer.x(HITPOINTS));
		assertEquals(274, footer.centredX(51, HITPOINTS));
	}

	private static final int LARGE_ROW = 24;
	private static final int SMALL_ROW = 16;

	private static BossHealthBarConfig rowConfig(boolean showName, boolean showDamage, boolean showDefeat,
		boolean showKillCount)
	{
		return new BossHealthBarConfig()
		{
			@Override
			public boolean showBossName()
			{
				return showName;
			}

			@Override
			public boolean showDamageNumber()
			{
				return showDamage;
			}

			@Override
			public boolean showDefeatAnimation()
			{
				return showDefeat;
			}

			@Override
			public boolean showKillCount()
			{
				return showKillCount;
			}
		};
	}

	private static BarPosition[] defaultPositions()
	{
		final BarPosition[] positions = new BarPosition[ITEM_COUNT];
		positions[NAME] = BarPosition.TOP_LEFT;
		positions[DAMAGE_NUMBER] = BarPosition.TOP_RIGHT;
		positions[HITPOINTS] = BarPosition.BOTTOM_RIGHT;
		positions[FIGHT_TIMER] = BarPosition.TOP_CENTER;
		for (int item = KILL_COUNT; item <= DRAIN_CAP; item++)
		{
			positions[item] = BarPosition.BOTTOM_LEFT;
		}
		return positions;
	}

	private static BarPosition[] allAt(BarPosition position)
	{
		final BarPosition[] positions = new BarPosition[ITEM_COUNT];
		Arrays.fill(positions, position);
		return positions;
	}

	private static int[] rowHeights(BossHealthBarConfig config, BarPosition[] positions, boolean others)
	{
		final boolean[] available = new boolean[ITEM_COUNT];
		BarTextPainter.itemsAvailable(config, others, others, others, others, others, available);
		// The default RuneScape fonts: the name and damage number reach 18 above the baseline and 6 below,
		// the small text 12 above and 4 below.
		final int[] above = new int[ITEM_COUNT];
		final int[] below = new int[ITEM_COUNT];
		Arrays.fill(above, 12);
		Arrays.fill(below, SMALL_ROW - 12);
		above[NAME] = above[DAMAGE_NUMBER] = 18;
		below[NAME] = below[DAMAGE_NUMBER] = LARGE_ROW - 18;
		return new int[]{
			BarTextPainter.rowHeight(positions, available, true, above, below),
			BarTextPainter.rowHeight(positions, available, false, above, below)};
	}

	@Test
	public void hitpointsNoneWithoutTheDefeatAnimationLeavesTheBottomRowEmpty()
	{
		final int[] heights = rowHeights(rowConfig(true, true, false, false), defaultPositions(), false);
		assertEquals(LARGE_ROW, heights[0]);
		assertEquals(0, heights[1]);
	}

	@Test
	public void theDefeatAnimationReservesTheHitpointsRowEvenWithHitpointsNone()
	{
		final int[] heights = rowHeights(rowConfig(true, true, true, false), defaultPositions(), false);
		assertEquals(LARGE_ROW, heights[0]);
		assertEquals(SMALL_ROW, heights[1]);

		final BarPosition[] hitpointsOnTop = defaultPositions();
		hitpointsOnTop[HITPOINTS] = BarPosition.TOP_CENTER;
		final int[] moved = rowHeights(rowConfig(false, false, true, false), hitpointsOnTop, false);
		assertEquals(SMALL_ROW, moved[0]);
		assertEquals(0, moved[1]);
	}

	@Test
	public void everythingOnTopLeavesNoBottomRow()
	{
		final int[] heights = rowHeights(rowConfig(true, true, true, true), allAt(BarPosition.TOP_RIGHT), true);
		assertEquals(LARGE_ROW, heights[0]);
		assertEquals(0, heights[1]);
	}

	@Test
	public void everythingOnTheBottomLeavesNoTopRow()
	{
		final int[] heights = rowHeights(rowConfig(true, true, true, true), allAt(BarPosition.BOTTOM_LEFT), true);
		assertEquals(0, heights[0]);
		assertEquals(LARGE_ROW, heights[1]);
	}

	@Test
	public void aRowWithOnlySmallItemsUsesTheSmallHeight()
	{
		final BarPosition[] positions = defaultPositions();
		positions[KILL_COUNT] = BarPosition.TOP_LEFT;
		final int[] heights = rowHeights(rowConfig(false, false, false, true), positions, false);
		assertEquals(SMALL_ROW, heights[0]);
		assertEquals(0, heights[1]);
	}
}

package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.BarPainter.capScale;
import static com.ghordrin.bosshealthbar.BarAnimation.clamp01;
import static com.ghordrin.bosshealthbar.BarAnimation.easeOut;
import static com.ghordrin.bosshealthbar.BarTextPainter.estimateHealth;
import static com.ghordrin.bosshealthbar.BarTextPainter.hitpointsPercent;
import static com.ghordrin.bosshealthbar.GameBossBar.markerFraction;
import static com.ghordrin.bosshealthbar.BarAnimation.progress;
import static com.ghordrin.bosshealthbar.BarPainter.scaledCapWidth;
import static com.ghordrin.bosshealthbar.BarPainter.scaledFrameStroke;
import java.time.Duration;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class BossHealthBarOverlayTest
{
	private static final int[] MAX_HEALTHS = {1, 2, 10, 99, 100, 255, 1000, 4000};
	private static final int[] SCALES = {1, 2, 30, 100, 255};

	@Test
	public void estimateHealthRoundTripsToTheObservedRatio()
	{
		for (int max : MAX_HEALTHS)
		{
			for (int scale : SCALES)
			{
				for (int health = 1; health <= max; health++)
				{
					final int ratio = 1 + (scale - 1) * health / max;
					final int estimate = estimateHealth(ratio, scale, max);

					assertTrue("estimate " + estimate + " out of range for max " + max,
						estimate >= 1 && estimate <= max);
					assertEquals("max " + max + " scale " + scale + " health " + health,
						ratio, 1 + (scale - 1) * estimate / max);
				}
			}
		}
	}

	@Test
	public void estimateHealthReturnsZeroWhenTheBarIsEmpty()
	{
		assertEquals(0, estimateHealth(0, 30, 400));
		assertEquals(0, estimateHealth(-1, 30, 400));
	}

	@Test
	public void estimateHealthReturnsFullAtTheTopOfTheScale()
	{
		assertEquals(400, estimateHealth(30, 30, 400));
	}

	@Test
	public void estimateHealthHandlesAScaleOfOne()
	{
		final int estimate = estimateHealth(1, 1, 100);
		assertTrue(estimate >= 1 && estimate <= 100);
	}

	@Test
	public void hitpointsPercentMatchesTheRawRatioInTheMiddleOfTheBar()
	{
		assertEquals(50, hitpointsPercent(50, 100));
		assertEquals(99, hitpointsPercent(99, 100));
	}

	@Test
	public void hitpointsPercentOnlyShowsZeroOrFullWhenTrulyEmptyOrFull()
	{
		assertEquals(0, hitpointsPercent(0, 100));
		assertEquals(100, hitpointsPercent(100, 100));
	}

	@Test
	public void hitpointsPercentClampsAwayFromZeroAndFullWhileStillAliveOrDamaged()
	{
		assertEquals(1, hitpointsPercent(1, 1_000_000));
		assertEquals(99, hitpointsPercent(999_999, 1_000_000));
	}

	@Test
	public void markersSitWhereTheGamePutsThem()
	{
		assertEquals(0f, markerFraction(1, 400), 0.0001f);
		assertEquals(1f, markerFraction(401, 400), 0.0001f);
		assertEquals(0.5f, markerFraction(201, 400), 0.0001f);
	}

	@Test
	public void markersStayOnTheBar()
	{
		for (int max : MAX_HEALTHS)
		{
			for (int value = 0; value <= max + 2; value++)
			{
				final float fraction = markerFraction(value, max);
				assertTrue("value " + value + " of " + max + " gave " + fraction,
					fraction >= 0f && fraction <= 1f);
			}
		}
	}

	@Test
	public void clampKeepsFractionsInRange()
	{
		assertEquals(0f, clamp01(-5f), 0f);
		assertEquals(1f, clamp01(5f), 0f);
		assertEquals(0.25f, clamp01(0.25f), 0f);
	}

	@Test
	public void progressRunsFromZeroToOneAcrossTheDuration()
	{
		final Duration delay = Duration.ofMillis(100);
		final Duration duration = Duration.ofMillis(400);

		assertEquals(0f, progress(Duration.ofMillis(50).toNanos(), delay, duration), 0.0001f);
		assertEquals(0f, progress(delay.toNanos(), delay, duration), 0.0001f);
		assertEquals(0.5f, progress(Duration.ofMillis(300).toNanos(), delay, duration), 0.0001f);
		assertEquals(1f, progress(Duration.ofMillis(500).toNanos(), delay, duration), 0.0001f);
		assertEquals(1f, progress(Duration.ofSeconds(10).toNanos(), delay, duration), 0.0001f);
		assertEquals(1f, progress(Long.MAX_VALUE, delay, duration), 0.0001f);
	}

	@Test
	public void easeOutKeepsItsEndsAndOnlyMovesForward()
	{
		assertEquals(0f, easeOut(0f), 0.0001f);
		assertEquals(1f, easeOut(1f), 0.0001f);

		float previous = -1f;
		for (int i = 0; i <= 100; i++)
		{
			final float eased = easeOut(i / 100f);
			assertTrue("eased value went backwards at " + i, eased > previous);
			assertTrue("eased value left the range at " + i, eased >= 0f && eased <= 1f);
			previous = eased;
		}

		assertTrue(easeOut(0.5f) > 0.5f);
	}

	@Test
	public void capsOnlyGrowOnceTheBarIsTallerThanTheReferenceHeight()
	{
		assertEquals(1f, capScale(4), 0.0001f);
		assertEquals(1f, capScale(8), 0.0001f);
		assertTrue(capScale(24) > capScale(9));
		assertTrue(capScale(9) > capScale(8));
	}

	@Test
	public void scaledCapWidthGrowsWithBarHeight()
	{
		assertEquals(scaledCapWidth(4), scaledCapWidth(8));
		assertTrue(scaledCapWidth(24) > scaledCapWidth(8));
	}

	@Test
	public void scaledFrameStrokeNeverGoesBelowAHairline()
	{
		assertEquals(1f, scaledFrameStroke(4), 0.0001f);
		assertEquals(1f, scaledFrameStroke(8), 0.0001f);
		assertTrue(scaledFrameStroke(24) > 1f);
	}
}

