package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.DamageTracker.NO_TICK;
import static com.ghordrin.bosshealthbar.DamageTracker.isSameAttack;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class DamageTrackerTest
{
	@Test
	public void noStartTickIsNeverTheSameAttack()
	{
		assertFalse(isSameAttack(NO_TICK, 100));
		assertFalse(isSameAttack(NO_TICK, 0));
	}

	@Test
	public void theSameTickAndTheNextTickAreTheSameAttack()
	{
		assertTrue(isSameAttack(100, 100));
		assertTrue(isSameAttack(100, 101));
	}

	@Test
	public void twoTicksLaterIsANewAttack()
	{
		assertFalse(isSameAttack(100, 102));
	}

	@Test
	public void aTickFromBeforeTheStartIsANewAttack()
	{
		assertFalse(isSameAttack(100, 5));
	}

	@Test
	public void hitsOnTheSameTickAddUp()
	{
		final DamageTracker tracker = new DamageTracker();
		hit(tracker, 20, 100);
		hit(tracker, 15, 100);

		assertEquals(35, tracker.getComboDamage());
	}

	@Test
	public void hitsTwoTicksApartStartFresh()
	{
		final DamageTracker tracker = new DamageTracker();
		hit(tracker, 20, 100);
		hit(tracker, 15, 102);

		assertEquals(15, tracker.getComboDamage());
	}

	@Test
	public void aFourTickCadenceNeverAccumulates()
	{
		final DamageTracker tracker = new DamageTracker();
		for (int tick = 100; tick < 140; tick += 4)
		{
			hit(tracker, 25, tick);
			assertEquals(25, tracker.getComboDamage());
		}
	}

	@Test
	public void multiHitAttackAddsUpThenTheNextAttackStartsFresh()
	{
		final DamageTracker tracker = new DamageTracker();
		hit(tracker, 20, 100);
		hit(tracker, 10, 100);
		hit(tracker, 5, 101);
		hit(tracker, 5, 101);
		assertEquals(40, tracker.getComboDamage());

		hit(tracker, 12, 105);
		assertEquals(12, tracker.getComboDamage());
	}

	@Test
	public void hitsOnEveryTickDoNotChainIntoOneTotal()
	{
		final DamageTracker tracker = new DamageTracker();
		hit(tracker, 10, 100);
		hit(tracker, 10, 101);
		hit(tracker, 10, 102);
		assertEquals(10, tracker.getComboDamage());

		hit(tracker, 10, 103);
		assertEquals(20, tracker.getComboDamage());
	}

	@Test
	public void resetComboStartsTheNextHitFresh()
	{
		final DamageTracker tracker = new DamageTracker();
		hit(tracker, 20, 100);
		tracker.resetCombo();
		hit(tracker, 15, 100);

		assertEquals(15, tracker.getComboDamage());
	}

	@Test
	public void partyHitsKeepAddingWhileTheyKeepComing()
	{
		final DamageTracker tracker = new DamageTracker();
		tracker.addToCombo(20, 1000, 100, true);
		tracker.addToCombo(15, 3400, 104, true);
		tracker.addToCombo(10, 5800, 108, true);

		assertEquals(45, tracker.getComboDamage());
	}

	@Test
	public void partyTotalStartsFreshAfterAPause()
	{
		final DamageTracker tracker = new DamageTracker();
		tracker.addToCombo(20, 1000, 100, true);
		tracker.addToCombo(15, 3501, 105, true);

		assertEquals(15, tracker.getComboDamage());
	}

	@Test
	public void zeroPartyHitsAreIgnored()
	{
		final DamageTracker tracker = new DamageTracker();
		tracker.recordPartyHit(0, 100);

		assertEquals(0, tracker.getComboDamage());
	}

	private static void hit(DamageTracker tracker, int amount, int tick)
	{
		tracker.addToCombo(amount, tick * 600L, tick, false);
	}
}

package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.FightTimer.NO_TICK;
import static com.ghordrin.bosshealthbar.FightTimer.SWAP_TICKS;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class FightTimerTest
{
	private final FightTimer timer = new FightTimer();

	@Test
	public void formatsMinutesAndSeconds()
	{
		assertEquals("0:00", FightTimer.format(0));
		assertEquals("0:00", FightTimer.format(1));
		assertEquals("0:01", FightTimer.format(2));
		assertEquals("0:59", FightTimer.format(99));
		assertEquals("1:00", FightTimer.format(100));
		assertEquals("1:23", FightTimer.format(139));
		assertEquals("59:59", FightTimer.format(5999));
	}

	@Test
	public void formatsHoursFromAnHour()
	{
		assertEquals("1:00:00", FightTimer.format(6000));
		assertEquals("1:05:09", FightTimer.format(6515));
		assertEquals("12:34:56", FightTimer.format(75494));
	}

	@Test
	public void elapsedStopsAtTheEndTick()
	{
		assertEquals(NO_TICK, FightTimer.elapsedTicks(NO_TICK, NO_TICK, 50));
		assertEquals(40, FightTimer.elapsedTicks(10, NO_TICK, 50));
		assertEquals(20, FightTimer.elapsedTicks(10, 30, 50));
	}

	@Test
	public void aSameNamedNpcCarriesOnAnUndefeatedFight()
	{
		assertTrue(FightTimer.keepsCounting("Boss", false, NO_TICK, "Boss", false, 100));
		assertFalse(FightTimer.keepsCounting("Boss", true, NO_TICK, "Boss", false, 100));
		assertFalse(FightTimer.keepsCounting("Boss", false, NO_TICK, "Minion", false, 100));
		assertFalse(FightTimer.keepsCounting(null, false, NO_TICK, "Boss", false, 100));
	}

	@Test
	public void aSameNamedNpcOnlyCarriesOnShortlyAfterTheLastOneWentAway()
	{
		assertTrue(FightTimer.keepsCounting("Boss", false, 100, "Boss", false, 100 + SWAP_TICKS));
		assertFalse(FightTimer.keepsCounting("Boss", false, 100, "Boss", false, 101 + SWAP_TICKS));
	}

	@Test
	public void showsNothingBeforeTheFirstHit()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK,10);
		timer.onGameTick(true, false, 11);
		assertNull(timer.getText());
	}

	@Test
	public void countsFromTheFirstHitAndIgnoresLaterOnes()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK,10);
		timer.onHit(20);
		assertEquals("0:00", timer.getText());
		timer.onHit(30);
		timer.onGameTick(true, false, 120);
		assertEquals("1:00", timer.getText());
	}

	@Test
	public void theTextIsOnlyRebuiltWhenTheTimeChanges()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK,10);
		timer.onHit(10);
		timer.onGameTick(true, false, 12);
		final String text = timer.getText();
		timer.onGameTick(true, false, 12);
		assertSame(text, timer.getText());
	}

	@Test
	public void stopsWhenDefeatedAndKeepsTheTime()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK,0);
		timer.onHit(0);
		timer.onGameTick(true, true, 100);
		timer.onGameTick(true, true, 150);
		assertEquals("1:00", timer.getText());

		timer.opponentDespawned(true, 160);
		assertEquals("1:00", timer.getText());
	}

	@Test
	public void despawningAsItDiesStopsTheTimer()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK,0);
		timer.onHit(0);
		timer.opponentDespawned(true, 100);
		timer.onGameTick(false, false, 200);
		assertEquals("1:00", timer.getText());
	}

	@Test
	public void carriesOnWhenItComesBackFromZero()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK,0);
		timer.onHit(0);
		timer.onGameTick(true, true, 50);
		timer.onGameTick(true, false, 100);
		assertEquals("1:00", timer.getText());
	}

	@Test
	public void aDifferentOpponentStartsOver()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK,0);
		timer.onHit(0);
		timer.onGameTick(true, false, 100);
		timer.opponentChanged("Minion", false, false, NO_TICK, 101);
		assertNull(timer.getText());
		timer.onHit(105);
		assertEquals("0:00", timer.getText());
	}

	@Test
	public void aPhaseSwapToASameNamedNpcKeepsCounting()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK,0);
		timer.onHit(0);
		timer.opponentChanged("Boss", false, false, NO_TICK,50);
		timer.onGameTick(true, false, 100);
		assertEquals("1:00", timer.getText());

		timer.opponentDespawned(false, 110);
		timer.opponentChanged("Boss", false, false, NO_TICK,112);
		timer.onGameTick(true, false, 200);
		assertEquals("2:00", timer.getText());
	}

	@Test
	public void aSameNamedNpcAfterADefeatStartsOver()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK,0);
		timer.onHit(0);
		timer.opponentChanged("Boss", true, false, NO_TICK, 50);
		assertNull(timer.getText());

		timer.onHit(60);
		timer.opponentDespawned(true, 100);
		timer.opponentChanged("Boss", false, false, NO_TICK,101);
		assertNull(timer.getText());
	}

	@Test
	public void aSameNamedNpcLongAfterTheLastOneWentAwayStartsOver()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK,0);
		timer.onHit(0);
		timer.opponentDespawned(false, 50);
		timer.opponentChanged("Boss", false, false, NO_TICK,51 + SWAP_TICKS);
		assertNull(timer.getText());
	}

	@Test
	public void onlyAHitFromThisOrTheLastTickCountsFromBeforeTheOpponentWasPicked()
	{
		assertEquals(100, FightTimer.recentHitTick(100, 100));
		assertEquals(100, FightTimer.recentHitTick(100, 101));
		assertEquals(NO_TICK, FightTimer.recentHitTick(100, 102));
		assertEquals(NO_TICK, FightTimer.recentHitTick(NO_TICK, 100));
	}

	@Test
	public void theHitThatBroughtUpTheOpponentStartsTheTimer()
	{
		timer.opponentChanged("Boss", false, false, 100, 101);
		timer.onGameTick(true, false, 200);
		assertEquals("1:00", timer.getText());
	}

	@Test
	public void anEarlierHitDoesNotRestartAFightThatCarriesOn()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK, 0);
		timer.onHit(0);
		timer.opponentChanged("Boss", false, false, 50, 50);
		timer.onGameTick(true, false, 100);
		assertEquals("1:00", timer.getText());
	}

	@Test
	public void aSameNamedNpcSoonAfterADefeatedOneDespawnedStartsOver()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK, 0);
		timer.onHit(0);
		timer.opponentDespawned(true, 100);
		timer.opponentChanged("Boss", false, false, NO_TICK, 102);
		assertNull(timer.getText());
	}

	@Test
	public void aPairCarriesOnWhateverTheGapBetweenItsMembersWhileItIsHeld()
	{
		assertTrue(FightTimer.keepsCounting(PairBosses.GUARDIANS, false, 100, PairBosses.GUARDIANS, true, 101 + SWAP_TICKS));
		assertFalse(FightTimer.keepsCounting(PairBosses.GUARDIANS, false, 100, PairBosses.GUARDIANS, false, 101 + SWAP_TICKS));
		assertTrue(FightTimer.keepsCounting(PairBosses.GUARDIANS, false, 100, PairBosses.GUARDIANS, false, 100 + SWAP_TICKS));
		assertFalse(FightTimer.keepsCounting(PairBosses.GUARDIANS, true, 100, PairBosses.GUARDIANS, true, 101));
		assertFalse(FightTimer.keepsCounting("Boss", false, 100, "Boss", true, 101 + SWAP_TICKS));
	}

	@Test
	public void swappingBetweenTheMembersOfAPairKeepsCounting()
	{
		timer.opponentChanged(PairBosses.GUARDIANS, false, true, NO_TICK, 0);
		timer.onHit(0);
		timer.opponentChanged(PairBosses.GUARDIANS, false, true, NO_TICK, 30);
		// The first member dies while the other one is still up, so it isn't counted as defeated.
		timer.onGameTick(true, false, 50);
		timer.opponentDespawned(false, 60);
		timer.opponentChanged(PairBosses.GUARDIANS, false, true, NO_TICK, 60 + SWAP_TICKS * 3);
		timer.onGameTick(true, false, 200);
		assertEquals("2:00", timer.getText());
	}

	@Test
	public void aPairThatWasForgottenStartsOverWhenItComesBack()
	{
		timer.opponentChanged(PairBosses.GUARDIANS, false, true, NO_TICK, 0);
		timer.onHit(0);
		timer.opponentDespawned(false, 100);
		timer.pairCleared("Boss");
		timer.pairCleared(PairBosses.GUARDIANS);
		// The time shown stays until the next opponent.
		timer.onGameTick(false, false, 150);
		assertEquals("1:30", timer.getText());

		// Back in a new fight with both members spawned, so the pair is held again.
		timer.opponentChanged(PairBosses.GUARDIANS, false, true, NO_TICK, 800);
		assertNull(timer.getText());
		timer.onHit(800);
		timer.onGameTick(true, false, 900);
		assertEquals("1:00", timer.getText());
	}

	@Test
	public void aPairThatIsNoLongerHeldStartsOverAfterALongGap()
	{
		timer.opponentChanged(PairBosses.GUARDIANS, false, true, NO_TICK, 0);
		timer.onHit(0);
		timer.opponentDespawned(false, 100);
		timer.opponentChanged(PairBosses.GUARDIANS, false, false, NO_TICK, 101 + SWAP_TICKS);
		assertNull(timer.getText());
	}

	@Test
	public void aPairStopsWithItsLastMemberAndThenStartsOver()
	{
		timer.opponentChanged(PairBosses.GUARDIANS, false, true, NO_TICK, 0);
		timer.onHit(0);
		timer.onGameTick(true, true, 100);
		timer.opponentDespawned(true, 105);
		timer.onGameTick(false, false, 150);
		assertEquals("1:00", timer.getText());

		timer.opponentChanged(PairBosses.GUARDIANS, false, true, NO_TICK, 300);
		assertNull(timer.getText());
	}

	@Test
	public void resetClearsTheFight()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK,0);
		timer.onHit(0);
		timer.reset();
		assertNull(timer.getText());
		timer.opponentChanged("Boss", false, false, NO_TICK,5);
		assertNull(timer.getText());
	}

	@Test
	public void anOpponentBackFromOutOfSightKeepsItsStart()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK, 0);
		timer.onHit(0);
		timer.opponentDespawned(false, 50);
		final FightTimer.Fight fight = timer.save();
		timer.opponentChanged("Minion", false, false, NO_TICK, 60);
		timer.opponentReturned(fight, NO_TICK, 70 + SWAP_TICKS);
		timer.onGameTick(true, false, 100);
		assertEquals("1:00", timer.getText());
		timer.onGameTick(true, false, 200);
		assertEquals("2:00", timer.getText());
	}

	@Test
	public void aStoppedFightStaysStoppedWhenTheOpponentComesBack()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK, 0);
		timer.onHit(0);
		timer.onGameTick(true, true, 100);
		timer.opponentDespawned(false, 120);
		final FightTimer.Fight fight = timer.save();
		timer.reset();
		timer.opponentReturned(fight, NO_TICK, 200);
		assertEquals("1:00", timer.getText());
	}

	@Test
	public void anOpponentBackBeforeAnyHitStartsOnTheNextHit()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK, 0);
		timer.opponentDespawned(false, 50);
		final FightTimer.Fight fight = timer.save();
		timer.opponentReturned(fight, NO_TICK, 100);
		assertNull(timer.getText());
		timer.onHit(110);
		timer.onGameTick(true, false, 210);
		assertEquals("1:00", timer.getText());
	}

	@Test
	public void startingOverCountsFromThatTick()
	{
		timer.opponentChanged("Boss", false, false, NO_TICK, 0);
		timer.onHit(0);
		timer.onGameTick(true, true, 50);
		timer.startOver(100);
		timer.onGameTick(true, false, 200);
		assertEquals("1:00", timer.getText());
	}

	@Test
	public void theSlotSizingSwapsEveryDigit()
	{
		assertEquals("0:00", BarTextPainter.withDigits("1:23", '0'));
		assertEquals("4:44:44", BarTextPainter.withDigits("1:05:09", '4'));
	}
}

package com.ghordrin.bosshealthbar;

import java.awt.Font;
import net.runelite.client.config.FontType;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class FontDefaultMigrationTest
{
	private static final FontType OLD_DEFAULT = new FontType().withFamily(Font.SERIF).withSize(17);

	@Test
	public void oldDefaultIsMigrated()
	{
		assertTrue(FontDefaultMigration.isOldDefault(OLD_DEFAULT));
	}

	@Test
	public void otherFontsAreKept()
	{
		assertFalse(FontDefaultMigration.isOldDefault(null));
		assertFalse(FontDefaultMigration.isOldDefault(OLD_DEFAULT.withSize(18)));
		assertFalse(FontDefaultMigration.isOldDefault(OLD_DEFAULT.withBold(true)));
		assertFalse(FontDefaultMigration.isOldDefault(OLD_DEFAULT.withItalic(true)));
		assertFalse(FontDefaultMigration.isOldDefault(OLD_DEFAULT.withFamily(Font.SANS_SERIF)));
		assertFalse(FontDefaultMigration.isOldDefault(FontType.REGULAR));
		assertFalse(FontDefaultMigration.isOldDefault(FontType.BOLD));
		assertFalse(FontDefaultMigration.isOldDefault(FontType.SMALL));
	}

	@Test
	public void runescapeFontsGetTheirNativeSize()
	{
		final FontType regular = FontDefaultMigration.withNativePixelSize(FontType.REGULAR.withSize(17));
		assertEquals(FontType.REGULAR.getFamily(), regular.getFamily());
		assertEquals(16, regular.getSize());

		final FontType small = FontDefaultMigration.withNativePixelSize(FontType.SMALL.withSize(17));
		assertEquals(FontType.SMALL.getFamily(), small.getFamily());
		assertEquals(16, small.getSize());

		final FontType bold = FontDefaultMigration.withNativePixelSize(
			FontType.REGULAR.withBold(true).withItalic(true).withSize(20));
		assertEquals(16, bold.getSize());
		assertTrue(bold.isBold());
		assertTrue(bold.isItalic());
	}

	@Test
	public void otherFontsKeepTheirSize()
	{
		assertNull(FontDefaultMigration.withNativePixelSize(FontType.REGULAR));
		assertNull(FontDefaultMigration.withNativePixelSize(FontType.SMALL));
		assertNull(FontDefaultMigration.withNativePixelSize(OLD_DEFAULT));
		assertNull(FontDefaultMigration.withNativePixelSize(OLD_DEFAULT.withSize(24)));
		assertNull(FontDefaultMigration.withNativePixelSize(null));
	}
}

