package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.BossHealthBarConfig.MATCH_BOSS_COLORS_KEY;
import static com.ghordrin.bosshealthbar.BossHealthBarConfig.OLDSCHOOL_THEME_KEY;
import static com.ghordrin.bosshealthbar.BossHealthBarConfig.RARE_GOLD_BARS_KEY;
import static com.ghordrin.bosshealthbar.BossHealthBarConfig.SAVED_MATCH_BOSS_COLORS_KEY;
import static com.ghordrin.bosshealthbar.BossHealthBarConfig.SAVED_RARE_GOLD_BARS_KEY;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import org.junit.Test;

public class OldschoolToggleTest
{
	// Stands in for ConfigManager: a write that changes a value posts a change event straight away,
	// which the plugin handles again. Unset boxes read as their defaults.
	private static class FakeConfig
	{
		final Map<String, Boolean> values = new HashMap<>();
		int events;

		FakeConfig(boolean oldschool, boolean match, boolean rare)
		{
			values.put(OLDSCHOOL_THEME_KEY, oldschool);
			values.put(MATCH_BOSS_COLORS_KEY, match);
			values.put(RARE_GOLD_BARS_KEY, rare);
		}

		void set(String key, Boolean value)
		{
			final Boolean old = values.get(key);
			if (Objects.equals(old, value))
			{
				return;
			}
			if (value == null)
			{
				values.remove(key);
			}
			else
			{
				values.put(key, value);
			}

			assertTrue("too many change events", ++events < 50);
			if (!OldschoolToggle.handles(key))
			{
				return;
			}
			for (OldschoolToggle.Write write : OldschoolToggle.writes(key, orDefault(key, old), orDefault(key, value), settings()))
			{
				set(write.getKey(), write.getValue());
			}
		}

		OldschoolToggle.Settings settings()
		{
			return new OldschoolToggle.Settings(get(OLDSCHOOL_THEME_KEY), get(MATCH_BOSS_COLORS_KEY),
				get(RARE_GOLD_BARS_KEY), values.get(SAVED_MATCH_BOSS_COLORS_KEY), values.get(SAVED_RARE_GOLD_BARS_KEY));
		}

		boolean get(String key)
		{
			return orDefault(key, values.get(key));
		}

		private static boolean orDefault(String key, Boolean value)
		{
			return value != null ? value : RARE_GOLD_BARS_KEY.equals(key);
		}
	}

	@Test
	public void tickingOnRemembersAndTurnsOffTheOtherBoxes()
	{
		final List<OldschoolToggle.Write> writes = OldschoolToggle.writes(OLDSCHOOL_THEME_KEY, false, true,
			new OldschoolToggle.Settings(true, true, false, null, null));
		assertEquals(Arrays.asList(
			new OldschoolToggle.Write(SAVED_MATCH_BOSS_COLORS_KEY, true),
			new OldschoolToggle.Write(SAVED_RARE_GOLD_BARS_KEY, false),
			new OldschoolToggle.Write(MATCH_BOSS_COLORS_KEY, false),
			new OldschoolToggle.Write(RARE_GOLD_BARS_KEY, false)), writes);
	}

	@Test
	public void tickingOffClearsMemoryThenRestores()
	{
		final List<OldschoolToggle.Write> writes = OldschoolToggle.writes(OLDSCHOOL_THEME_KEY, true, false,
			new OldschoolToggle.Settings(false, false, false, true, false));
		assertEquals(Arrays.asList(
			new OldschoolToggle.Write(SAVED_MATCH_BOSS_COLORS_KEY, null),
			new OldschoolToggle.Write(SAVED_RARE_GOLD_BARS_KEY, null),
			new OldschoolToggle.Write(MATCH_BOSS_COLORS_KEY, true),
			new OldschoolToggle.Write(RARE_GOLD_BARS_KEY, false)), writes);
	}

	@Test
	public void tickingAConflictTurnsOldschoolOffAndRestoresOnlyTheOther()
	{
		final List<OldschoolToggle.Write> writes = OldschoolToggle.writes(MATCH_BOSS_COLORS_KEY, false, true,
			new OldschoolToggle.Settings(true, true, false, false, true));
		assertEquals(Arrays.asList(
			new OldschoolToggle.Write(SAVED_MATCH_BOSS_COLORS_KEY, null),
			new OldschoolToggle.Write(SAVED_RARE_GOLD_BARS_KEY, null),
			new OldschoolToggle.Write(RARE_GOLD_BARS_KEY, true),
			new OldschoolToggle.Write(OLDSCHOOL_THEME_KEY, false)), writes);
	}

	@Test
	public void nothingToDoWhenTheValueDidntChange()
	{
		final OldschoolToggle.Settings settings = new OldschoolToggle.Settings(true, false, false, true, true);
		assertTrue(OldschoolToggle.writes(OLDSCHOOL_THEME_KEY, true, true, settings).isEmpty());
		assertTrue(OldschoolToggle.writes(MATCH_BOSS_COLORS_KEY, false, false, settings).isEmpty());
	}

	@Test
	public void conflictBoxesOnlyMatterWhileOldschoolIsOn()
	{
		final OldschoolToggle.Settings off = new OldschoolToggle.Settings(false, true, true, null, null);
		assertTrue(OldschoolToggle.writes(MATCH_BOSS_COLORS_KEY, false, true, off).isEmpty());
		assertTrue(OldschoolToggle.writes(RARE_GOLD_BARS_KEY, false, true, off).isEmpty());

		final OldschoolToggle.Settings on = new OldschoolToggle.Settings(true, false, false, true, true);
		assertTrue(OldschoolToggle.writes(RARE_GOLD_BARS_KEY, true, false, on).isEmpty());
		assertTrue(OldschoolToggle.writes("barWidth", false, true, on).isEmpty());
	}

	@Test
	public void tickingOnKeepsWhatIsAlreadyRemembered()
	{
		final List<OldschoolToggle.Write> writes = OldschoolToggle.writes(OLDSCHOOL_THEME_KEY, false, true,
			new OldschoolToggle.Settings(true, false, false, true, true));
		assertEquals(Arrays.asList(
			new OldschoolToggle.Write(MATCH_BOSS_COLORS_KEY, false),
			new OldschoolToggle.Write(RARE_GOLD_BARS_KEY, false)), writes);
	}

	@Test
	public void repeatedTogglingRoundTrips()
	{
		final FakeConfig config = new FakeConfig(false, true, false);
		for (int i = 0; i < 5; i++)
		{
			config.set(OLDSCHOOL_THEME_KEY, true);
			assertFalse(config.get(MATCH_BOSS_COLORS_KEY));
			assertFalse(config.get(RARE_GOLD_BARS_KEY));

			config.set(OLDSCHOOL_THEME_KEY, false);
			assertTrue(config.get(MATCH_BOSS_COLORS_KEY));
			assertFalse(config.get(RARE_GOLD_BARS_KEY));
			assertNull(config.values.get(SAVED_MATCH_BOSS_COLORS_KEY));
			assertNull(config.values.get(SAVED_RARE_GOLD_BARS_KEY));
		}
	}

	@Test
	public void lastClickWinsWithoutLooping()
	{
		final FakeConfig config = new FakeConfig(false, false, true);
		config.set(OLDSCHOOL_THEME_KEY, true);
		assertFalse(config.get(RARE_GOLD_BARS_KEY));

		config.set(MATCH_BOSS_COLORS_KEY, true);
		assertFalse(config.get(OLDSCHOOL_THEME_KEY));
		assertTrue(config.get(MATCH_BOSS_COLORS_KEY));
		assertTrue(config.get(RARE_GOLD_BARS_KEY));
		assertNull(config.values.get(SAVED_MATCH_BOSS_COLORS_KEY));
		assertNull(config.values.get(SAVED_RARE_GOLD_BARS_KEY));

		config.set(OLDSCHOOL_THEME_KEY, true);
		config.set(RARE_GOLD_BARS_KEY, true);
		assertFalse(config.get(OLDSCHOOL_THEME_KEY));
		assertTrue(config.get(MATCH_BOSS_COLORS_KEY));
		assertTrue(config.get(RARE_GOLD_BARS_KEY));
	}

	@Test
	public void tickingRareGoldBarsTurnsOldschoolOffAndRestoresMatchBossColors()
	{
		final List<OldschoolToggle.Write> writes = OldschoolToggle.writes(RARE_GOLD_BARS_KEY, false, true,
			new OldschoolToggle.Settings(true, false, true, true, false));
		assertEquals(Arrays.asList(
			new OldschoolToggle.Write(SAVED_MATCH_BOSS_COLORS_KEY, null),
			new OldschoolToggle.Write(SAVED_RARE_GOLD_BARS_KEY, null),
			new OldschoolToggle.Write(MATCH_BOSS_COLORS_KEY, true),
			new OldschoolToggle.Write(OLDSCHOOL_THEME_KEY, false)), writes);
	}

	@Test
	public void unsetRareGoldBarsCountsAsOn()
	{
		final FakeConfig config = new FakeConfig(false, false, true);
		config.values.remove(RARE_GOLD_BARS_KEY);
		config.set(OLDSCHOOL_THEME_KEY, true);
		assertEquals(Boolean.TRUE, config.values.get(SAVED_RARE_GOLD_BARS_KEY));
		assertFalse(config.get(RARE_GOLD_BARS_KEY));

		config.set(OLDSCHOOL_THEME_KEY, false);
		assertTrue(config.get(RARE_GOLD_BARS_KEY));
	}

	@Test
	public void resetEndsOnTheDefaultsInAnyOrder()
	{
		final String[][] orders = {
			{OLDSCHOOL_THEME_KEY, MATCH_BOSS_COLORS_KEY, RARE_GOLD_BARS_KEY},
			{OLDSCHOOL_THEME_KEY, RARE_GOLD_BARS_KEY, MATCH_BOSS_COLORS_KEY},
			{MATCH_BOSS_COLORS_KEY, OLDSCHOOL_THEME_KEY, RARE_GOLD_BARS_KEY},
			{MATCH_BOSS_COLORS_KEY, RARE_GOLD_BARS_KEY, OLDSCHOOL_THEME_KEY},
			{RARE_GOLD_BARS_KEY, OLDSCHOOL_THEME_KEY, MATCH_BOSS_COLORS_KEY},
			{RARE_GOLD_BARS_KEY, MATCH_BOSS_COLORS_KEY, OLDSCHOOL_THEME_KEY},
		};
		for (String[] order : orders)
		{
			final FakeConfig config = new FakeConfig(false, true, false);
			config.set(OLDSCHOOL_THEME_KEY, true);

			// RuneLite's Reset puts each setting back to its default, then the plugin's reset writes run.
			for (String key : order)
			{
				config.set(key, RARE_GOLD_BARS_KEY.equals(key));
			}
			for (OldschoolToggle.Write write : OldschoolToggle.resetWrites())
			{
				config.set(write.getKey(), write.getValue());
			}

			final String name = Arrays.toString(order);
			assertFalse(name, config.get(OLDSCHOOL_THEME_KEY));
			assertFalse(name, config.get(MATCH_BOSS_COLORS_KEY));
			assertTrue(name, config.get(RARE_GOLD_BARS_KEY));
			assertNull(name, config.values.get(SAVED_MATCH_BOSS_COLORS_KEY));
			assertNull(name, config.values.get(SAVED_RARE_GOLD_BARS_KEY));
		}
	}
}

package com.ghordrin.bosshealthbar;

import net.runelite.api.HitsplatID;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class OpponentTrackerTest
{
	private static final long DELAY = 5000;

	@Test
	public void staysWhileStillInteracting()
	{
		assertFalse(OpponentTracker.isQuietFor(0, 0, 0, true, 100_000, DELAY));
	}

	@Test
	public void hidesOnceTheDelayHasPassedSinceInteractionStopped()
	{
		assertFalse(OpponentTracker.isQuietFor(10_000, 0, 0, true, 15_000, DELAY));
		assertTrue(OpponentTracker.isQuietFor(10_000, 0, 0, true, 15_001, DELAY));
	}

	@Test
	public void aHitTakenRestartsTheDelay()
	{
		assertFalse(OpponentTracker.isQuietFor(10_000, 14_000, 0, true, 18_000, DELAY));
		assertTrue(OpponentTracker.isQuietFor(10_000, 14_000, 0, true, 19_001, DELAY));
	}

	@Test
	public void aHitOnTheOpponentRestartsTheDelay()
	{
		assertFalse(OpponentTracker.isQuietFor(10_000, 0, 16_000, true, 21_000, DELAY));
		assertTrue(OpponentTracker.isQuietFor(10_000, 0, 16_000, true, 21_001, DELAY));
	}

	@Test
	public void theLatestHitCounts()
	{
		assertFalse(OpponentTracker.isQuietFor(10_000, 17_000, 13_000, true, 22_000, DELAY));
		assertTrue(OpponentTracker.isQuietFor(10_000, 17_000, 13_000, true, 22_001, DELAY));
	}

	@Test
	public void hitsBeforeInteractionStoppedDoNotExtendTheDelay()
	{
		assertTrue(OpponentTracker.isQuietFor(10_000, 2_000, 3_000, true, 15_001, DELAY));
	}

	@Test
	public void hitsAreIgnoredWhenTheOpponentIsNotNearby()
	{
		assertTrue(OpponentTracker.isQuietFor(10_000, 14_000, 14_500, false, 15_001, DELAY));
	}

	@Test
	public void damageAndBlocksCount()
	{
		assertTrue(OpponentTracker.isCombatHit(HitsplatID.DAMAGE_ME));
		assertTrue(OpponentTracker.isCombatHit(HitsplatID.DAMAGE_OTHER));
		assertTrue(OpponentTracker.isCombatHit(HitsplatID.DAMAGE_ME_POISE));
		assertTrue(OpponentTracker.isCombatHit(HitsplatID.BLOCK_ME));
		assertTrue(OpponentTracker.isCombatHit(HitsplatID.BLOCK_OTHER));
	}

	@Test
	public void damageOverTimeAndHealsDoNotCount()
	{
		assertFalse(OpponentTracker.isCombatHit(HitsplatID.POISON));
		assertFalse(OpponentTracker.isCombatHit(HitsplatID.VENOM));
		assertFalse(OpponentTracker.isCombatHit(HitsplatID.BURN));
		assertFalse(OpponentTracker.isCombatHit(HitsplatID.BLEED));
		assertFalse(OpponentTracker.isCombatHit(HitsplatID.DOOM));
		assertFalse(OpponentTracker.isCombatHit(HitsplatID.CORRUPTION));
		assertFalse(OpponentTracker.isCombatHit(HitsplatID.HEAL));
	}
}

package com.ghordrin.bosshealthbar;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.gameval.NpcID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PairBossesTest
{
	private static final int[] FIRST = {NpcID.GARGBOSS_DAWN_SPAWN, NpcID.GARGBOSS_DAWN_PHASE1,
		NpcID.GARGBOSS_DAWN_PHASE1_TRANSITION, NpcID.GARGBOSS_DAWN_PHASE3, NpcID.GARGBOSS_DAWN_DEATH};
	private static final int[] SECOND = {NpcID.GARGBOSS_DUSK_SPAWN, NpcID.GARGBOSS_DUSK_PHASE1_DEFENSIVE,
		NpcID.GARGBOSS_DUSK_PHASE1_TRANSITION, NpcID.GARGBOSS_DUSK_PHASE1_FLYTRANSITION,
		NpcID.GARGBOSS_DUSK_PHASE2_ATTACKING, NpcID.GARGBOSS_DUSK_PHASE3_DEFENSIVE,
		NpcID.GARGBOSS_DUSK_PHASE3_TRANSITION, NpcID.GARGBOSS_DUSK_PHASE4_SPAWN, NpcID.GARGBOSS_DUSK_PHASE4,
		NpcID.GARGBOSS_DUSK_DEATH};

	private final List<PairBosses.Slot> slots = new ArrayList<>();

	@Test
	public void theTableCoversExactlyEachFormOfBothMembers()
	{
		final Set<Integer> ids = new HashSet<>();
		for (int id : FIRST)
		{
			ids.add(id);
		}
		for (int id : SECOND)
		{
			ids.add(id);
		}
		assertEquals(15, ids.size());
		assertEquals(ids, PairBosses.members().keySet());

		final PairBosses.Member first = PairBosses.member(FIRST[0]);
		final PairBosses.Member second = PairBosses.member(SECOND[0]);
		assertNotSame(first, second);
		assertEquals(PairBosses.GUARDIANS, first.pair);
		assertEquals(PairBosses.GUARDIANS, second.pair);
		Arrays.stream(FIRST).forEach(id -> assertSame(first, PairBosses.member(id)));
		Arrays.stream(SECOND).forEach(id -> assertSame(second, PairBosses.member(id)));
		assertNull(PairBosses.member(NpcID.GARGBOSS_DUSK_SPAWN - 1));
	}

	@Test
	public void onlyThePairNameIsAPairKey()
	{
		assertTrue(PairBosses.isPairKey(PairBosses.GUARDIANS));
		assertFalse(PairBosses.isPairKey("Dusk"));
		assertFalse(PairBosses.isPairKey(null));
	}

	@Test
	public void aMemberThatDiesIsForgottenAndOneThatLeavesIsKept()
	{
		final PairBosses.Slot dead = PairBosses.slot(slots, PairBosses.member(FIRST[0]), true);
		final PairBosses.Slot away = PairBosses.slot(slots, PairBosses.member(SECOND[0]), true);
		dead.dead = true;
		PairBosses.despawned(slots, dead, false);
		PairBosses.despawned(slots, away, false);
		assertNull(PairBosses.slot(slots, PairBosses.member(FIRST[0]), false));
		assertSame(away, PairBosses.slot(slots, PairBosses.member(SECOND[0]), false));
		assertNull(away.npc);
		assertTrue(PairBosses.isAlive(away));

		PairBosses.despawned(slots, away, true);
		assertTrue(slots.isEmpty());
	}

	@Test
	public void aPairIsForgottenOnceNoMemberHasBeenAroundForAWhile()
	{
		final PairBosses.Slot first = PairBosses.slot(slots, PairBosses.member(FIRST[0]), true);
		final PairBosses.Slot second = PairBosses.slot(slots, PairBosses.member(SECOND[0]), true);
		first.lastPresentTick = 100;
		second.lastPresentTick = 90;

		assertTrue(PairBosses.clearGone(slots, 100 + PairBosses.CLEAR_TICKS).isEmpty());
		assertEquals(2, slots.size());
		assertTrue(PairBosses.hasPair(slots, PairBosses.GUARDIANS));

		assertEquals(Collections.singleton(PairBosses.GUARDIANS), PairBosses.clearGone(slots, 101 + PairBosses.CLEAR_TICKS));
		assertTrue(slots.isEmpty());
		assertFalse(PairBosses.hasPair(slots, PairBosses.GUARDIANS));
	}

	@Test
	public void aPairThatComesBackAfterBeingForgottenIsHeldAgain()
	{
		final PairBosses.Slot away = PairBosses.slot(slots, PairBosses.member(FIRST[0]), true);
		away.lastPresentTick = 0;
		assertEquals(Collections.singleton(PairBosses.GUARDIANS), PairBosses.clearGone(slots, 500));

		// The pair comes back: the new slots are a new pair, held until it's gone again.
		final PairBosses.Slot back = PairBosses.slot(slots, PairBosses.member(SECOND[0]), true);
		back.lastPresentTick = 500;
		assertTrue(PairBosses.hasPair(slots, PairBosses.GUARDIANS));
		assertTrue(PairBosses.clearGone(slots, 500 + PairBosses.CLEAR_TICKS).isEmpty());
	}

	@Test
	public void onlyTheDeathFormsCountAsDying()
	{
		assertTrue(PairBosses.isDeathForm(NpcID.GARGBOSS_DAWN_DEATH));
		assertTrue(PairBosses.isDeathForm(NpcID.GARGBOSS_DUSK_DEATH));
		Arrays.stream(FIRST).filter(id -> id != NpcID.GARGBOSS_DAWN_DEATH)
			.forEach(id -> assertFalse(PairBosses.isDeathForm(id)));
		Arrays.stream(SECOND).filter(id -> id != NpcID.GARGBOSS_DUSK_DEATH)
			.forEach(id -> assertFalse(PairBosses.isDeathForm(id)));
	}

	@Test
	public void aMemberInItsDeathFormIsDeadWhateverItsHealth()
	{
		final PairBosses.Slot slot = new PairBosses.Slot(PairBosses.member(FIRST[0]));
		PairBosses.read(slot, 0, 0, 20, 30, 450);
		PairBosses.updateDead(slot, false);
		assertTrue(PairBosses.isAlive(slot));

		PairBosses.updateDead(slot, true);
		assertFalse(PairBosses.isAlive(slot));

		// A dead member is forgotten when it despawns, so the timer can stop at the last kill.
		slots.add(slot);
		PairBosses.despawned(slots, slot, false);
		assertTrue(slots.isEmpty());
	}

	@Test
	public void aZeroReadingIsDeadAndAFreshOneIsAliveAgain()
	{
		final PairBosses.Slot slot = new PairBosses.Slot(PairBosses.member(SECOND[0]));
		PairBosses.updateDead(slot, false);
		assertTrue(PairBosses.isAlive(slot));

		PairBosses.read(slot, 0, 0, 0, 30, 450);
		PairBosses.updateDead(slot, false);
		assertFalse(PairBosses.isAlive(slot));

		PairBosses.read(slot, 0, 0, 5, 30, 450);
		PairBosses.updateDead(slot, false);
		assertTrue(PairBosses.isAlive(slot));
	}

	@Test
	public void onlyTheFirstFormOfEachMemberIsAStartForm()
	{
		assertTrue(PairBosses.isStartForm(NpcID.GARGBOSS_DAWN_SPAWN));
		assertTrue(PairBosses.isStartForm(NpcID.GARGBOSS_DUSK_SPAWN));
		assertFalse(PairBosses.isStartForm(NpcID.GARGBOSS_DUSK_PHASE4_SPAWN));
		assertFalse(PairBosses.isStartForm(NpcID.GARGBOSS_DAWN_PHASE1));
	}

	@Test
	public void aStartFormIsSeededAtFullHealth()
	{
		final PairBosses.Slot slot = new PairBosses.Slot(PairBosses.member(FIRST[0]));
		PairBosses.seedFull(slot, 450);
		assertReading(slot, 450, 450, true, 450);

		final PairBosses.Slot unknown = new PairBosses.Slot(PairBosses.member(FIRST[0]));
		PairBosses.seedFull(unknown, null);
		assertReading(unknown, 1, 1, false, null);
	}

	@Test
	public void theGameBarWinsOverTheOverheadBarWhichWinsOverTheLastReading()
	{
		final PairBosses.Slot slot = new PairBosses.Slot(PairBosses.member(SECOND[0]));
		PairBosses.seedFull(slot, 450);

		assertTrue(PairBosses.read(slot, 300, 450, 20, 30, 450));
		assertReading(slot, 300, 450, true, 450);

		assertTrue(PairBosses.read(slot, 0, 0, 15, 30, 450));
		assertReading(slot, 15, 30, false, 450);

		// The overhead bar went away, so the last reading stays.
		assertFalse(PairBosses.read(slot, 0, 0, -1, -1, 450));
		assertReading(slot, 15, 30, false, 450);
	}

	@Test
	public void theStateIsOnlyRebuiltWhenTheReadingChanges()
	{
		final PairBosses.Slot slot = new PairBosses.Slot(PairBosses.member(SECOND[0]));
		PairBosses.read(slot, 0, 0, 15, 30, 450);
		slot.state = new BarState("Test", 0, 450, 15, 30, false, false, BarState.NO_PHASE_MARKERS,
			HealthIndicatorMarkers.NONE, null, null, Collections.emptyList(), null);
		final BarState state = slot.state;

		assertFalse(PairBosses.read(slot, 0, 0, 15, 30, 450));
		assertSame(state, slot.state);

		assertTrue(PairBosses.read(slot, 0, 0, 14, 30, 450));
		assertNull(slot.state);
	}

	@Test
	public void thePartnerIsTheOtherMemberOfThePair()
	{
		final PairBosses.Member first = PairBosses.member(FIRST[0]);
		final PairBosses.Member second = PairBosses.member(SECOND[0]);
		assertNull(PairBosses.partner(slots, first));

		final PairBosses.Slot firstSlot = PairBosses.slot(slots, first, true);
		assertNull(PairBosses.partner(slots, first));
		assertSame(firstSlot, PairBosses.partner(slots, second));

		final PairBosses.Slot secondSlot = PairBosses.slot(slots, second, true);
		assertSame(secondSlot, PairBosses.partner(slots, first));
	}

	@Test
	public void thePartnerRowFitsTheHitpointsFontWhileItHasText()
	{
		assertEquals(14, BarTextPainter.partnerRowHeight(true, false, 10, 4));
		assertEquals(14, BarTextPainter.partnerRowHeight(false, true, 10, 4));
		assertEquals(0, BarTextPainter.partnerRowHeight(false, false, 10, 4));
	}

	@Test
	public void theSlotIsFoundByMember()
	{
		final PairBosses.Slot slot = PairBosses.slot(slots, PairBosses.member(FIRST[1]), true);
		assertSame(slot, PairBosses.slot(slots, PairBosses.member(FIRST[3]), true));
		assertNotNull(slot);
		assertEquals(1, slots.size());
	}

	private static void assertReading(PairBosses.Slot slot, int ratio, int scale, boolean exact, Integer maxHealth)
	{
		assertEquals(ratio, slot.ratio);
		assertEquals(scale, slot.scale);
		assertEquals(exact, slot.exact);
		assertEquals(maxHealth, slot.maxHealth);
	}
}

package com.ghordrin.bosshealthbar;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.Predicate;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PartyDefenceTest
{
	private static class DefenceTrackerPlugin extends Plugin
	{
	}

	private static class OtherPlugin extends Plugin
	{
	}

	private static class DefenceInfoBox extends InfoBox
	{
		private final String text;
		private final Color color;

		DefenceInfoBox(Plugin plugin, String tooltip, String text, Color color)
		{
			this(plugin, null, tooltip, text, color);
		}

		DefenceInfoBox(Plugin plugin, BufferedImage image, String tooltip, String text, Color color)
		{
			super(image, plugin);
			setTooltip(tooltip);
			this.text = text;
			this.color = color;
		}

		@Override
		public String getText()
		{
			return text;
		}

		@Override
		public Color getTextColor()
		{
			return color;
		}
	}

	private static class VulnerabilityInfoBox extends DefenceInfoBox
	{
		VulnerabilityInfoBox(Plugin plugin, String tooltip)
		{
			super(plugin, tooltip, "V", Color.WHITE);
		}
	}

	private static class BetterPartyDefencePlugin extends Plugin
	{
	}

	private static final Plugin TRACKER = new DefenceTrackerPlugin();
	private static final Plugin BETTER = new BetterPartyDefencePlugin();
	private static final BufferedImage DEFENCE_IMAGE = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
	private static final BufferedImage MAGIC_IMAGE = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
	private static final Predicate<BufferedImage> IS_MAGIC = image -> image == MAGIC_IMAGE;
	private static final Predicate<BufferedImage> NOTHING_IS_MAGIC = image -> false;

	private static DefenceInfoBox box(String tooltip, String text, Color color)
	{
		return new DefenceInfoBox(TRACKER, tooltip, text, color);
	}

	private static DefenceInfoBox betterBox(BufferedImage image, String text, Color color)
	{
		return new DefenceInfoBox(BETTER, image, "No specs yet", text, color);
	}

	@Test
	public void boxesAreNamedLikeTheirs()
	{
		assertEquals(PartyDefence.BOX_NAME, box("Big Boss", "10", Color.WHITE).getName());
		assertEquals(PartyDefence.BETTER_BOX_NAME, betterBox(DEFENCE_IMAGE, "10", Color.WHITE).getName());
	}

	@Test
	public void betterSkipsTheMagicDefenceBox()
	{
		final PartyDefence.Reading reading = PartyDefence.findBetter(Arrays.asList(
			betterBox(MAGIC_IMAGE, "150", Color.WHITE),
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN)), IS_MAGIC);

		assertEquals(new PartyDefence.Reading("120", Color.GREEN), reading);
	}

	@Test
	public void betterTakesTheFirstBoxWhenNeitherIsMagic()
	{
		final PartyDefence.Reading reading = PartyDefence.findBetter(Arrays.asList(
			box("Big Boss", "5", Color.WHITE),
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN),
			betterBox(new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB), "150", Color.WHITE)), IS_MAGIC);

		assertEquals(new PartyDefence.Reading("120", Color.GREEN), reading);
		assertEquals(reading, PartyDefence.findBetter(Arrays.asList(
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN),
			betterBox(MAGIC_IMAGE, "150", Color.WHITE)), NOTHING_IS_MAGIC));
	}

	@Test
	public void betterIgnoresEmptyText()
	{
		assertNull(PartyDefence.findBetter(Arrays.asList(
			betterBox(DEFENCE_IMAGE, "", Color.WHITE),
			betterBox(MAGIC_IMAGE, "150", Color.WHITE)), IS_MAGIC));
		assertNull(PartyDefence.findBetter(Collections.singletonList(betterBox(DEFENCE_IMAGE, null, Color.WHITE)), IS_MAGIC));
		assertNull(PartyDefence.findBetter(Collections.singletonList(betterBox(MAGIC_IMAGE, "150", Color.WHITE)), IS_MAGIC));
		assertNull(PartyDefence.findBetter(Collections.emptyList(), IS_MAGIC));
	}

	@Test
	public void magicIsTheBoxWithTheMagicImage()
	{
		final List<InfoBox> boxes = Arrays.asList(
			box("Big Boss", "5", Color.WHITE),
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN),
			betterBox(MAGIC_IMAGE, "150", Color.YELLOW));

		assertEquals(new PartyDefence.Reading("150", Color.YELLOW), PartyDefence.findBetterMagic(boxes, IS_MAGIC));
		assertEquals(new PartyDefence.Reading("150", Color.YELLOW), PartyDefence.findBetterMagic(Arrays.asList(
			betterBox(MAGIC_IMAGE, "150", Color.YELLOW),
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN)), IS_MAGIC));
	}

	@Test
	public void unrecognisedImagesGiveDefenceFromTheFirstBoxAndNoMagic()
	{
		final List<InfoBox> boxes = Arrays.asList(
			betterBox(new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB), "150", Color.YELLOW),
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN));

		assertEquals(new PartyDefence.Reading("150", Color.YELLOW), PartyDefence.findBetter(boxes, IS_MAGIC));
		assertNull(PartyDefence.findBetterMagic(boxes, IS_MAGIC));
	}

	@Test
	public void themedMagicIconIsFoundByItsPixelsInEitherOrder()
	{
		final BufferedImage skillMagic = icon(25, 0xFF2040C0);
		final BufferedImage skillDefence = icon(25, 0xFFA0A0A0);
		final MagicIconMatcher matcher = new MagicIconMatcher();
		final Predicate<BufferedImage> isMagic = image -> matcher.isMagic(image, skillMagic, null);
		final InfoBox themedMagic = betterBox(MagicIconMatcher.themed(skillMagic), "150", Color.YELLOW);
		final InfoBox themedDefence = betterBox(MagicIconMatcher.themed(skillDefence), "120", Color.GREEN);

		for (List<InfoBox> boxes : Arrays.asList(Arrays.asList(themedMagic, themedDefence),
			Arrays.asList(themedDefence, themedMagic)))
		{
			assertEquals(new PartyDefence.Reading("120", Color.GREEN), PartyDefence.findBetter(boxes, isMagic));
			assertEquals(new PartyDefence.Reading("150", Color.YELLOW), PartyDefence.findBetterMagic(boxes, isMagic));
		}
	}

	@Test
	public void themedMagicIconFromAnOverrideIsFoundByItsPixels()
	{
		final BufferedImage skillMagic = icon(25, 0xFF2040C0);
		final BufferedImage override = icon(30, 0xFF10E020);
		final MagicIconMatcher matcher = new MagicIconMatcher();

		assertTrue(matcher.isMagic(MagicIconMatcher.themed(override), skillMagic, override));
		assertTrue(matcher.isMagic(MagicIconMatcher.themed(skillMagic), skillMagic, override));
		assertTrue(matcher.isMagic(skillMagic, skillMagic, null));
		assertFalse(matcher.isMagic(MagicIconMatcher.themed(override), skillMagic, null));
		assertFalse(matcher.isMagic(MagicIconMatcher.themed(icon(25, 0xFFA0A0A0)), skillMagic, override));
		assertFalse(matcher.isMagic(null, skillMagic, override));
	}

	private static BufferedImage icon(int size, int argb)
	{
		final BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		for (int y = 2; y < size - 2; y++)
		{
			for (int x = y % 3; x < size - 2; x += 2)
			{
				image.setRGB(x, y, argb);
			}
		}
		return image;
	}

	@Test
	public void aSingleBoxWithoutTheMagicImageIsDefence()
	{
		final List<InfoBox> boxes = Collections.singletonList(betterBox(DEFENCE_IMAGE, "120", Color.GREEN));

		assertEquals(new PartyDefence.Reading("120", Color.GREEN), PartyDefence.findBetter(boxes, IS_MAGIC));
		assertNull(PartyDefence.findBetterMagic(boxes, IS_MAGIC));
		assertNull(PartyDefence.findBetterMagic(Collections.singletonList(box("Big Boss", "24", Color.RED)), IS_MAGIC));
	}

	@Test
	public void magicIgnoresEmptyText()
	{
		assertNull(PartyDefence.findBetterMagic(Arrays.asList(
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN),
			betterBox(MAGIC_IMAGE, "", Color.WHITE)), IS_MAGIC));
		assertNull(PartyDefence.findBetterMagic(Arrays.asList(
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN),
			betterBox(MAGIC_IMAGE, null, Color.WHITE)), IS_MAGIC));
	}

	@Test
	public void betterIsUsedWhenItsOn()
	{
		final List<InfoBox> boxes = Arrays.asList(
			box("Big Boss", "24", Color.RED),
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN));

		assertEquals(new PartyDefence.Reading("120", Color.GREEN), PartyDefence.select(boxes, "Big Boss", true, IS_MAGIC));
		assertNull(PartyDefence.select(Collections.singletonList(box("Big Boss", "24", Color.RED)), "Big Boss", true, IS_MAGIC));
	}

	@Test
	public void trackerIsUsedWhenBetterIsOff()
	{
		final List<InfoBox> boxes = Arrays.asList(
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN),
			box("Small Boss", "5", Color.WHITE),
			box("Big Boss", "24", Color.RED));

		assertEquals(new PartyDefence.Reading("24", Color.RED), PartyDefence.select(boxes, "Big Boss", false, NOTHING_IS_MAGIC));
		assertNull(PartyDefence.select(boxes, "Other Boss", false, NOTHING_IS_MAGIC));
	}

	@Test
	public void matchesTheTooltipWithoutColorTagsOrCase()
	{
		assertTrue(PartyDefence.matches(box("<col=ffffff>Big Boss</col>", "10", Color.WHITE), "Big Boss"));
		assertTrue(PartyDefence.matches(box("Big Boss", "10", Color.WHITE), "big boss"));
		assertTrue(PartyDefence.matches(box("Big Boss", "10", Color.WHITE), "<col=ffff00>Big Boss</col>"));
		assertFalse(PartyDefence.matches(box("Big Boss", "10", Color.WHITE), "Bigger Boss"));
	}

	@Test
	public void ignoresOtherBoxesAndMissingValues()
	{
		assertFalse(PartyDefence.matches(new VulnerabilityInfoBox(TRACKER, "Big Boss"), "Big Boss"));
		assertFalse(PartyDefence.matches(new DefenceInfoBox(new OtherPlugin(), "Big Boss", "10", Color.WHITE), "Big Boss"));
		assertFalse(PartyDefence.matches(box(null, "10", Color.WHITE), "Big Boss"));
		assertFalse(PartyDefence.matches(box("Big Boss", "10", Color.WHITE), null));
		assertFalse(PartyDefence.matches(null, "Big Boss"));
	}

	@Test
	public void picksTheBoxForTheOpponent()
	{
		final PartyDefence.Reading reading = PartyDefence.find(Arrays.asList(
			new VulnerabilityInfoBox(TRACKER, "Big Boss"),
			box("Small Boss", "5", Color.WHITE),
			box("", "7", Color.WHITE),
			box("<col=ffffff>Big Boss</col>", "", Color.WHITE),
			box("<col=ffffff>Big Boss</col>", "24", Color.RED)), "Big Boss");

		assertEquals(new PartyDefence.Reading("24", Color.RED), reading);
	}

	@Test
	public void findsNothingWithoutAMatch()
	{
		assertNull(PartyDefence.find(Collections.emptyList(), "Big Boss"));
		assertNull(PartyDefence.find(Collections.singletonList(box("Small Boss", "5", Color.WHITE)), "Big Boss"));
		assertNull(PartyDefence.find(Collections.singletonList(box("Big Boss", null, Color.WHITE)), "Big Boss"));
	}

	@Test
	public void keepsTheReadingForOneTickWhenTheBoxIsMissing()
	{
		final PartyDefence.HeldReading defence = new PartyDefence.HeldReading();
		final PartyDefence.Reading reading = new PartyDefence.Reading("24", Color.RED);

		defence.accept("Big Boss", reading);
		assertSame(reading, defence.readingFor("Big Boss"));

		defence.accept("Big Boss", null);
		assertSame(reading, defence.readingFor("Big Boss"));

		defence.accept("Big Boss", null);
		assertNull(defence.readingFor("Big Boss"));
	}

	@Test
	public void aNewReadingResetsTheMissedTick()
	{
		final PartyDefence.HeldReading defence = new PartyDefence.HeldReading();
		final PartyDefence.Reading first = new PartyDefence.Reading("24", Color.RED);
		final PartyDefence.Reading second = new PartyDefence.Reading("20", Color.RED);

		defence.accept("Big Boss", first);
		defence.accept("Big Boss", null);
		defence.accept("Big Boss", second);
		defence.accept("Big Boss", null);
		assertSame(second, defence.readingFor("Big Boss"));
	}

	@Test
	public void readingIsOnlyForTheSameName()
	{
		final PartyDefence.HeldReading defence = new PartyDefence.HeldReading();
		defence.accept("Big Boss", new PartyDefence.Reading("24", Color.RED));

		assertNull(defence.readingFor("Small Boss"));
		assertNull(defence.readingFor(null));

		defence.accept("Small Boss", null);
		assertNull(defence.readingFor("Big Boss"));
		assertNull(defence.readingFor("Small Boss"));
	}
}

package com.ghordrin.bosshealthbar;

import static com.ghordrin.bosshealthbar.PillarBars.FADE_IN_SCRIPT;
import static com.ghordrin.bosshealthbar.PillarBars.FADE_OUT_SCRIPT;
import static com.ghordrin.bosshealthbar.PillarBars.UPDATE_SCRIPT;
import java.awt.Dimension;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.gameval.InterfaceID;
import org.junit.Test;

public class PillarBarsTest
{
	private static final int NW = InterfaceID.NightmareTotems.TOTEM_NW_BAR_BACK;
	private static final int NE = InterfaceID.NightmareTotems.TOTEM_NE_BAR_BACK;
	private static final int SW = InterfaceID.NightmareTotems.TOTEM_SW_BAR_BACK;
	private static final int SE = InterfaceID.NightmareTotems.TOTEM_SE_BAR_BACK;
	private static final float DELTA = 0.0001f;

	private final PillarBars bars = new PillarBars(null);

	private static Object[] update(int[]... groups)
	{
		final Object[] args = new Object[PillarBars.UPDATE_ARGS];
		args[0] = UPDATE_SCRIPT;
		for (int group = 0; group < groups.length; group++)
		{
			for (int i = 0; i < 4; i++)
			{
				args[1 + group * 4 + i] = groups[group][i];
			}
		}
		args[PillarBars.UPDATE_ARGS - 1] = 0;
		return args;
	}

	private static int[] group(int back, int max, int current)
	{
		return new int[]{back, back + 1, max, current};
	}

	@Test
	public void parsesByComponentInAnyOrder()
	{
		bars.onScript(UPDATE_SCRIPT, update(group(SE, 100, 10), group(NW, 100, 40), group(NE, 100, 70), group(SW, 50, 25)));

		assertEquals(0.4f, bars.fraction(0), DELTA);
		assertEquals(0.7f, bars.fraction(1), DELTA);
		assertEquals(0.5f, bars.fraction(2), DELTA);
		assertEquals(0.1f, bars.fraction(3), DELTA);
	}

	@Test
	public void unchangedValueKeepsTheBar()
	{
		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 40), group(NE, 100, 40), group(SW, 100, 40), group(SE, 100, 40)));
		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, -1), group(NE, -1, 50), group(SW, 0, 80), group(SE, 100, 60)));

		assertEquals(0.4f, bars.fraction(0), DELTA);
		assertEquals(0.5f, bars.fraction(1), DELTA);
		assertEquals(0.4f, bars.fraction(2), DELTA);
		assertEquals(0.6f, bars.fraction(3), DELTA);
	}

	@Test
	public void anUnchangedCurrentIsRescaledByANewMax()
	{
		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 40), group(NE, 100, 100), group(SW, 100, 40), group(SE, 100, 40)));
		bars.onScript(UPDATE_SCRIPT, update(group(NW, 200, -1), group(NE, 200, -1), group(SW, -1, -1), group(SE, 50, -1)));

		assertEquals(0.2f, bars.fraction(0), DELTA);
		assertEquals(0.5f, bars.fraction(1), DELTA);
		assertFalse(bars.isFull(1));
		assertEquals(0.4f, bars.fraction(2), DELTA);
		assertEquals(0.8f, bars.fraction(3), DELTA);
	}

	@Test
	public void anUnchangedValueWithNothingStoredIsSkipped()
	{
		bars.onScript(UPDATE_SCRIPT, update(group(NW, -1, 50), group(NE, 100, -1), group(SW, -1, -1), group(SE, 0, 50)));
		for (int corner = 0; corner < PillarBars.CORNERS; corner++)
		{
			assertEquals(0f, bars.fraction(corner), DELTA);
		}

		// The max from the first update is kept for a later current.
		bars.onScript(UPDATE_SCRIPT, update(group(NW, -1, -1), group(NE, -1, 25), group(SW, -1, -1), group(SE, -1, -1)));
		assertEquals(0.25f, bars.fraction(1), DELTA);
		assertEquals(0f, bars.fraction(0), DELTA);
	}

	@Test
	public void resetForgetsTheStoredValues()
	{
		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 40), group(NE, 100, 40), group(SW, 100, 40), group(SE, 100, 40)));
		bars.reset();
		bars.onScript(UPDATE_SCRIPT, update(group(NW, -1, 50), group(NE, 200, -1), group(SW, -1, -1), group(SE, -1, -1)));
		for (int corner = 0; corner < PillarBars.CORNERS; corner++)
		{
			assertEquals(0f, bars.fraction(corner), DELTA);
		}
	}

	@Test
	public void clampsAndSetsFull()
	{
		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 150), group(NE, 100, 100), group(SW, 100, 99), group(SE, 100, 0)));

		assertEquals(1f, bars.fraction(0), DELTA);
		assertTrue(bars.isFull(0));
		assertTrue(bars.isFull(1));
		assertFalse(bars.isFull(2));
		assertFalse(bars.isFull(3));
		assertEquals(0f, bars.fraction(3), DELTA);

		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 0), group(NE, 100, 100), group(SW, 100, 99), group(SE, 100, 0)));
		assertFalse(bars.isFull(0));
		assertEquals(0f, bars.fraction(0), DELTA);
	}

	@Test
	public void fadeScriptsShowAndHide()
	{
		assertFalse(bars.isShown());
		bars.onScript(FADE_IN_SCRIPT, new Object[]{FADE_IN_SCRIPT});
		assertTrue(bars.isShown());
		bars.onScript(FADE_OUT_SCRIPT, null);
		assertFalse(bars.isShown());
	}

	@Test
	public void ignoresOtherScriptsAndBadArguments()
	{
		bars.onScript(UPDATE_SCRIPT + 1, update(group(NW, 100, 50), group(NE, 100, 50), group(SW, 100, 50), group(SE, 100, 50)));
		bars.onScript(UPDATE_SCRIPT, null);
		bars.onScript(UPDATE_SCRIPT, new Object[]{UPDATE_SCRIPT, NW, NW + 1, 100, 50});

		final Object[] wrongTypes = update(group(NW, 100, 50), group(NE, 100, 50), group(SW, 100, 50), group(SE, 100, 50));
		wrongTypes[1] = "text";
		wrongTypes[8] = null;
		wrongTypes[12] = "text";
		wrongTypes[13] = 12345;
		bars.onScript(UPDATE_SCRIPT, wrongTypes);

		for (int corner = 0; corner < PillarBars.CORNERS; corner++)
		{
			assertEquals(0f, bars.fraction(corner), DELTA);
			assertFalse(bars.isFull(corner));
		}
		assertFalse(bars.isShown());
		assertFalse(bars.isVisible());
	}

	@Test
	public void mapsCorners()
	{
		assertEquals(0, PillarBars.corner(NW));
		assertEquals(1, PillarBars.corner(NE));
		assertEquals(2, PillarBars.corner(SW));
		assertEquals(3, PillarBars.corner(SE));
		assertEquals(-1, PillarBars.corner(-1));
	}

	@Test
	public void seedsFromWidths()
	{
		assertEquals(0.5f, PillarBars.seedFraction(30, 60), DELTA);
		assertEquals(1f, PillarBars.seedFraction(60, 60), DELTA);
		assertEquals(0f, PillarBars.seedFraction(30, 0), DELTA);
		assertEquals(0f, PillarBars.seedFraction(0, -1), DELTA);
		assertTrue(PillarBars.seedFull(60, 60));
		assertFalse(PillarBars.seedFull(59, 60));
		assertFalse(PillarBars.seedFull(0, 0));
	}

	@Test
	public void layoutSize()
	{
		assertEquals(64, PillarBarsOverlay.barWidth(40));
		assertEquals(74, PillarBarsOverlay.barWidth(70));
		assertEquals(5, PillarBarsOverlay.barHeight(4));
		assertEquals(9, PillarBarsOverlay.barHeight(24));
		assertEquals(7, PillarBarsOverlay.barHeight(7));
		assertEquals(22, PillarBarsOverlay.cellHeight(12, 9));
		assertEquals(new Dimension(134, 47), PillarBarsOverlay.gridSize(64, 22));
	}

	@Test
	public void filledWidth()
	{
		assertEquals(62, PillarBarsOverlay.filledWidth(62, 0.2f, true));
		assertEquals(31, PillarBarsOverlay.filledWidth(62, 0.5f, false));
		assertEquals(0, PillarBarsOverlay.filledWidth(62, 0f, false));
		assertEquals(62, PillarBarsOverlay.filledWidth(62, 1.5f, false));
	}
}

package com.ghordrin.bosshealthbar;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SpecialAttackCountsTest
{
	private static class SpecialCounterPlugin extends Plugin
	{
	}

	private static class OtherPlugin extends Plugin
	{
	}

	private static class SpecialCounter extends InfoBox
	{
		private final String text;
		private final Color color;

		SpecialCounter(Plugin plugin, BufferedImage image, String text, Color color)
		{
			super(image, plugin);
			this.text = text;
			this.color = color;
		}

		@Override
		public String getText()
		{
			return text;
		}

		@Override
		public Color getTextColor()
		{
			return color;
		}
	}

	private static class OtherCounter extends SpecialCounter
	{
		OtherCounter(Plugin plugin)
		{
			super(plugin, null, "1", Color.WHITE);
		}
	}

	private static final Plugin COUNTER_PLUGIN = new SpecialCounterPlugin();
	private static final BufferedImage MAUL = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
	private static final BufferedImage GODSWORD = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);

	private static SpecialCounter box(BufferedImage image, String text, Color color)
	{
		return new SpecialCounter(COUNTER_PLUGIN, image, text, color);
	}

	private static List<SpecialAttackCounts.Reading> readings(SpecialAttackCounts.Reading... readings)
	{
		return Arrays.asList(readings);
	}

	@Test
	public void boxesAreNamedLikeTheirs()
	{
		assertEquals(SpecialAttackCounts.BOX_NAME, box(MAUL, "2", Color.WHITE).getName());
	}

	@Test
	public void ignoresOtherBoxes()
	{
		assertTrue(SpecialAttackCounts.matches(box(MAUL, "2", Color.WHITE)));
		assertFalse(SpecialAttackCounts.matches(new OtherCounter(COUNTER_PLUGIN)));
		assertFalse(SpecialAttackCounts.matches(new SpecialCounter(new OtherPlugin(), MAUL, "2", Color.WHITE)));
		assertFalse(SpecialAttackCounts.matches(null));
	}

	@Test
	public void findsEveryCountInInfoBoxOrder()
	{
		final List<SpecialAttackCounts.Reading> found = SpecialAttackCounts.find(Arrays.asList(
			box(MAUL, "2", Color.WHITE),
			new OtherCounter(COUNTER_PLUGIN),
			box(null, "", Color.WHITE),
			box(null, null, Color.WHITE),
			box(GODSWORD, "31", Color.GREEN)));

		assertEquals(readings(
			new SpecialAttackCounts.Reading(MAUL, "2", Color.WHITE),
			new SpecialAttackCounts.Reading(GODSWORD, "31", Color.GREEN)), found);
	}

	@Test
	public void findsNothingWithoutBoxes()
	{
		assertTrue(SpecialAttackCounts.find(Collections.emptyList()).isEmpty());
		assertTrue(SpecialAttackCounts.find(Collections.singletonList(new OtherCounter(COUNTER_PLUGIN))).isEmpty());
	}

	@Test
	public void keepsTheReadingsForOneTickWhenTheBoxesAreMissing()
	{
		final SpecialAttackCounts counts = new SpecialAttackCounts(null, null, null);
		final List<SpecialAttackCounts.Reading> found = readings(new SpecialAttackCounts.Reading(MAUL, "2", Color.WHITE));

		counts.accept(found);
		assertSame(found, counts.readings());

		counts.accept(Collections.emptyList());
		assertSame(found, counts.readings());

		counts.accept(Collections.emptyList());
		assertTrue(counts.readings().isEmpty());
	}

	@Test
	public void newReadingsResetTheMissedTick()
	{
		final SpecialAttackCounts counts = new SpecialAttackCounts(null, null, null);
		final List<SpecialAttackCounts.Reading> first = readings(new SpecialAttackCounts.Reading(MAUL, "2", Color.WHITE));
		final List<SpecialAttackCounts.Reading> second = readings(new SpecialAttackCounts.Reading(MAUL, "3", Color.WHITE));

		counts.accept(first);
		counts.accept(Collections.emptyList());
		counts.accept(second);
		counts.accept(Collections.emptyList());
		assertSame(second, counts.readings());
	}

	@Test
	public void groupWidthCoversEveryWeapon()
	{
		final Graphics2D graphics = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		final FontMetrics metrics = graphics.getFontMetrics(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
		graphics.dispose();

		final List<SpecialAttackCounts.Reading> noIcons = readings(
			new SpecialAttackCounts.Reading(null, "2", Color.WHITE),
			new SpecialAttackCounts.Reading(null, "31", Color.WHITE));
		assertEquals(10 + metrics.stringWidth("2") + 6 + metrics.stringWidth("31"),
			BarTextPainter.specialAttacksEnd(noIcons, metrics, 10, 13));

		// A 36x32 item image at height 13 is 15 wide with 1px of padding each side, plus the 3px gap.
		final BufferedImage itemImage = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		final List<SpecialAttackCounts.Reading> withIcon = readings(new SpecialAttackCounts.Reading(itemImage, "2", Color.WHITE));
		assertEquals(10 + 16 + metrics.stringWidth("2"), BarTextPainter.specialAttacksEnd(withIcon, metrics, 10, 13));
	}

	@Test
	public void unchangedReadingsKeepTheSameList()
	{
		final SpecialAttackCounts counts = new SpecialAttackCounts(null, null, null);
		final List<SpecialAttackCounts.Reading> first = readings(new SpecialAttackCounts.Reading(MAUL, "2", Color.WHITE));

		counts.accept(first);
		counts.accept(readings(new SpecialAttackCounts.Reading(MAUL, "2", Color.WHITE)));
		assertSame(first, counts.readings());
	}
}

package com.ghordrin.bosshealthbar;

import java.util.Arrays;
import java.util.Collections;
import net.runelite.api.gameval.NpcID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SuperiorTrackerTest
{
	private static SuperiorTracker.Spawn<String> known(String npc)
	{
		return new SuperiorTracker.Spawn<>(npc, true, false);
	}

	private static SuperiorTracker.Spawn<String> eligible(String npc)
	{
		return new SuperiorTracker.Spawn<>(npc, false, true);
	}

	private static SuperiorTracker.Spawn<String> ineligible(String npc)
	{
		return new SuperiorTracker.Spawn<>(npc, false, false);
	}

	@Test
	public void knownSuperiorsAreRecognisedById()
	{
		assertTrue(SuperiorIds.contains(NpcID.SUPERIOR_ABYSSAL_DEMON));
		assertTrue(SuperiorIds.contains(NpcID.SUPERIOR_GARGOYLE_DEAD));
		assertTrue(SuperiorIds.contains(NpcID.LEAGUE_SUPERIOR_HYDRA));
		assertTrue(SuperiorIds.contains(NpcID.DEADMAN_BREACH_SUPERIOR_DARK_BEAST));
		assertTrue(SuperiorIds.contains(NpcID.SUPERIOR_VENATOR));
	}

	@Test
	public void thrallsDeathSpawnsAndQuestMonstersAreNotSuperiors()
	{
		assertFalse(SuperiorIds.contains(NpcID.ARCEUUS_THRALL_GHOST_SUPERIOR));
		assertFalse(SuperiorIds.contains(NpcID.ARCEUUS_THRALL_SKELETON_SUPERIOR));
		assertFalse(SuperiorIds.contains(NpcID.ARCEUUS_THRALL_ZOMBIE_SUPERIOR));
		assertFalse(SuperiorIds.contains(NpcID.THRALL_IMP_MAGIC_SUPERIOR));
		assertFalse(SuperiorIds.contains(NpcID.THRALL_IMP_RANGED_SUPERIOR));
		assertFalse(SuperiorIds.contains(NpcID.THRALL_IMP_MELEE_SUPERIOR));
		assertFalse(SuperiorIds.contains(NpcID.SUPERIOR_NECHRYAEL_MELEE_SPAWN));
		assertFalse(SuperiorIds.contains(NpcID.SUPERIOR_NECHRYAEL_MAGIC_SPAWN));
		assertFalse(SuperiorIds.contains(NpcID.VIKINGEXILE_BASILISK_SUPERIOR));
		assertFalse(SuperiorIds.contains(NpcID.SLAYER_ABYSSAL));
	}

	@Test
	public void aKnownSuperiorTakesTheMessageOverACloserSpawn()
	{
		final SuperiorTracker.Match<String> match = SuperiorTracker.match(Arrays.asList(eligible("closer"), known("superior")));
		assertTrue(match.isDecided());
		assertNull(match.getSuperior());
	}

	@Test
	public void oneUnknownCandidateIsMarked()
	{
		final SuperiorTracker.Match<String> match = SuperiorTracker.match(Arrays.asList(ineligible("far"), eligible("new")));
		assertTrue(match.isDecided());
		assertEquals("new", match.getSuperior());
	}

	@Test
	public void twoCandidatesMarkNone()
	{
		final SuperiorTracker.Match<String> match = SuperiorTracker.match(Arrays.asList(eligible("a"), eligible("b")));
		assertTrue(match.isDecided());
		assertNull(match.getSuperior());
	}

	@Test
	public void withoutCandidatesTheMessageKeepsWaiting()
	{
		assertFalse(SuperiorTracker.match(Collections.<SuperiorTracker.Spawn<String>>emptyList()).isDecided());
		assertFalse(SuperiorTracker.match(Collections.singletonList(ineligible("dead"))).isDecided());
	}
}

package com.ghordrin.bosshealthbar;

import java.awt.Color;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ThemeColorsTest
{
	@Test
	public void themesKeepTheirColors()
	{
		final ThemeColors zamorak = HealthBarTheme.ZAMORAK.getColors();
		assertEquals(new Color(0xB01818), zamorak.getFillHigh());
		assertEquals(new Color(0x6A0C0C), zamorak.getFillLow());
		assertEquals(new Color(0xF0A030), zamorak.getTrail());
		assertEquals(new Color(0x5A4E4E), zamorak.getFrame());
		assertEquals(ColorUtil.brighten(new Color(0x5A4E4E), 0.35f), zamorak.getLevelText());
	}

	@Test
	public void derivedColorsStayReadableForAnyBase()
	{
		for (float hue = 0f; hue < 1f; hue += 1f / 36f)
		{
			for (float saturation : new float[]{0.05f, 0.3f, 0.6f, 0.9f})
			{
				for (float brightness : new float[]{0.45f, 0.7f, 0.95f})
				{
					final Color base = Color.getHSBColor(hue, saturation, brightness);
					final ThemeColors colors = ThemeColors.fromBase(base);
					final String label = String.format("base %06X", base.getRGB() & 0xFFFFFF);

					assertEquals(label, base, colors.getFillHigh());
					assertTrue(label, brightness(colors.getFillLow()) < brightness(base));
					assertTrue(label, ThemeColors.contrast(colors.getTrail(), base) >= 1.5f
						|| hueGap(colors.getTrail(), base) >= 0.25f);
				}
			}
		}
	}

	private static float brightness(Color c)
	{
		return Color.RGBtoHSB(c.getRed(), c.getGreen(), c.getBlue(), null)[2];
	}

	private static float hueGap(Color a, Color b)
	{
		final float ha = Color.RGBtoHSB(a.getRed(), a.getGreen(), a.getBlue(), null)[0];
		final float hb = Color.RGBtoHSB(b.getRed(), b.getGreen(), b.getBlue(), null)[0];
		final float gap = Math.abs(ha - hb);
		return Math.min(gap, 1f - gap);
	}
}
